fn supports_staged_point_binder_transform(binder: &AvfxBinder) -> bool {
    // These options affect target queries and independent Binder getters even
    // without PrpS.Pos. A zero/absent position must not bypass their limits.
    if binder.rotation_type != 0
        || binder.start_to_global_direction
        || binder.vfx_scale_enabled
        || binder.vfx_scale_depth_offset
        || binder.vfx_scale_interpolation
        || binder.transform_scale_depth_offset
        || binder.transform_scale_interpolation
        || binder.following_target_orientation
        || binder.document_scale_enabled
        || binder.adjust_to_screen_enabled
        || binder.ify
        || binder.bet
        || binder.properties_1.is_some()
        || binder.properties_2.is_some()
        || binder.properties_goal.is_some()
    {
        return false;
    }
    if let Some(properties) = &binder.properties_start {
        if properties.generate_delay != 0
            || properties.ring_enabled
            || (properties.position != Default::default()
                && static_point_binder_position(binder).is_none())
        {
            return false;
        }
    }
    if let Some(data) = &binder.data {
        if data.spring_strength_random.is_some() {
            return false;
        }
        if let Some(spring) = &data.spring_strength {
            if spring.pre_behavior != 0
                || spring.post_behavior != 0
                || spring.random_type != 0
                || spring.keys.len() != 1
                || spring.keys[0].time != 0
                || spring.keys[0].z != 1.0
            {
                return false;
            }
        }
    }
    true
}

fn point_target_after_initial_copy(outer: &AvfxBinder, inner: &AvfxBinder) -> Option<[f32; 3]> {
    if static_point_binder_position(outer) != Some([0.0; 3]) {
        return None;
    }
    let Some(inner_start) = inner.properties_start.as_ref() else {
        return None;
    };
    if inner_start.bind_point_id != inner.bind_point_id {
        return None;
    }
    let Some(data) = inner.data.as_ref() else {
        return None;
    };
    let Some(spring) = data.spring_strength.as_ref() else {
        return None;
    };
    if spring.pre_behavior != 0
        || spring.post_behavior != 0
        || spring.random_type != 0
        || spring.keys.len() != 2
        || spring.keys[0].time < 0
        || spring.keys[0].z != 1.0
        || spring.keys[1].time <= spring.keys[0].time
        || spring
            .keys
            .iter()
            .any(|key| !key.x.is_finite() || !key.y.is_finite() || !key.z.is_finite())
        || data.spring_strength_random.is_some()
        || data.carry_over_factor.is_some()
        || data.carry_over_factor_random.is_some()
        || data.distance.is_some()
        || data.distance_random.is_some()
        || !data.source.scalars.is_empty()
        || !data.source.curves.keys().all(|name| name == "SpS")
        || !data.source.curve3s.is_empty()
        || !data.source.color_curves.is_empty()
    {
        return None;
    }
    let mut without_spring = inner.clone();
    without_spring.data = outer.data.clone();
    let position = static_point_binder_position(&without_spring)?;
    without_spring.bind_point_id = outer.bind_point_id;
    let start = without_spring.properties_start.as_mut().unwrap();
    start.bind_point_id = outer.bind_point_id;
    start.position = outer.properties_start.as_ref()?.position.clone();
    (without_spring == *outer).then_some(position)
}

fn supports_dynamic_point_subtree(file: &AvfxFile, index: usize, visiting: &mut [bool]) -> bool {
    let Some(emitter) = file.emitters.get(index) else {
        return false;
    };
    if visiting[index]
        || emitter.emitter_type != Some(EmitterType::Point)
        || !matches!(emitter.data, None | Some(AvfxEmitterData::None))
    {
        return false;
    }
    visiting[index] = true;
    let current_item = |item: &AvfxEmitterItem| {
        matches!(coordinate_mode(item.parent_influence_coord), 2 | 8)
            && item.local_direction == 0
            && !item.influence_coord_binder
            && item.influence_coord_unstickiness == 0.0
    };
    let particles = emitter
        .particle_items
        .iter()
        .filter(|item| item.enabled)
        .all(|item| {
            let Some(particle) = usize::try_from(item.target_index)
                .ok()
                .and_then(|index| file.particles.get(index))
            else {
                return false;
            };
            if !current_item(item) {
                return false;
            }
            if !matches!(
                particle.particle_type,
                Some(
                    ParticleType::Quad
                        | ParticleType::Model
                        | ParticleType::Windmill
                        | ParticleType::Polyline
                        | ParticleType::Powder
                )
            ) {
                return false;
            }
            if particle.particle_type == Some(ParticleType::Powder)
                && particle.simple_anim_enable
                && particle
                    .simple
                    .as_ref()
                    .is_some_and(|simple| !simple.bind_parent)
            {
                let simple = particle.simple.as_ref().unwrap();
                return particle.loop_end <= particle.loop_start
                    && !item.override_life
                    && !item.inherit_parent_life
                    && item.start_frame == 0
                    && particle.life.enabled
                    && particle.life.value.is_finite()
                    && particle.life.value > 0.0
                    && particle.life.value_random == 0.0
                    && particle.life.random_type == 0
                    && (simple.injection_vertex_bind_model_index as i8) < 0
                    && !simple.scale_by_parent;
            }
            true
        });
    let emitters = emitter
        .emitter_items
        .iter()
        .filter(|item| item.enabled)
        .all(|item| {
            current_item(item)
                && !item.override_life
                && !item.inherit_parent_life
                && item.start_frame == 0
                && usize::try_from(item.target_index)
                    .ok()
                    .is_some_and(|index| supports_dynamic_point_subtree(file, index, visiting))
        });
    visiting[index] = false;
    particles && emitters
}
use std::{
    cell::{Cell, RefCell},
    collections::{HashMap, HashSet},
};

/// Playback retains Framework input history for the admitted Point-emitter subset.
/// Other files use the continuous preview, with the reason available to callers.
/// Absolute-time adapters run one input at their first timestamp, including
/// zero, and after seeking; subsequent unchanged timestamps remain reads.
/// This does not assert client fidelity for existing curve, Binder or GPU rules.
pub struct VfxPlayback {
    runtime: VfxRuntime,
    model_skin_targets: HashSet<usize>,
    state: Option<StagedPlayback>,
    fallback_reason: Option<String>,
    clock: FrameworkClock,
    seconds: f64,
    has_input: bool,
    model_skin_input_pending: bool,
}

impl VfxPlayback {
    /// Apply original Common fade control to the Scheduler at this live ordinal
    /// and all its currently registered descendants. Duration is in frames;
    /// mode's low two bits mean 0=unchanged alpha, 1=fade in, 2=fade out,
    /// 3=fade out and suppress ordinary factories. The flag inhibits retirement
    /// on fade completion. Numeric runs on the next explicit update, including
    /// zero delta; this call does not prepare objects or advance any clock.
    /// Pending factories inherit the owner's then-current fade on attachment.
    /// Control does not revive retired storage, and seeking discards it.
    pub fn configure_scheduler_fade(
        &mut self,
        scheduler_index: i32,
        duration: i32,
        mode: u32,
        inhibit_retirement: bool,
    ) -> Result<bool, String> {
        let Ok(ordinal) = usize::try_from(scheduler_index) else {
            return Ok(false);
        };
        if !self.runtime.has_resolved_binder_sources() {
            return Err("Scheduler fade requires resolved Binder sources".into());
        }
        let state = self
            .state
            .as_mut()
            .ok_or("Scheduler fade requires active staged playback")?;
        let Some(group) = state
            .scheduler_ordinary
            .iter()
            .enumerate()
            .filter(|(_, s)| s.linked)
            .nth(ordinal)
            .map(|(i, _)| i)
        else {
            return Ok(false);
        };
        configure_scheduler_fade_tree(
            &self.runtime.file,
            state,
            group,
            duration,
            mode,
            inhibit_retirement,
        )?;
        Ok(true)
    }

    /// External Document input between Framework updates. The Scheduler is its
    /// ordinal among currently registered Schedulers and the trigger number is
    /// one based (0x1403b1de0). A target
    /// Timeline is attached now at age zero, without an implicit Time/Prepare;
    /// the next explicit input advances it normally. Invalid mapping/unsupported
    /// targets leave playback intact. Seeking/reset does not replay inputs.
    pub fn trigger_document(
        &mut self,
        scheduler_index: i32,
        trigger_number: i32,
    ) -> Result<bool, String> {
        let groups = self
            .state
            .as_ref()
            .filter(|s| !s.scheduler_ordinary.is_empty())
            .map(|s| {
                s.scheduler_ordinary
                    .iter()
                    .enumerate()
                    .filter(|(_, v)| v.linked)
                    .map(|(i, _)| i)
                    .collect::<Vec<_>>()
            })
            .unwrap_or_else(|| (0..self.runtime.file.schedulers.len()).collect());
        let Some(mut input) = super::VfxSchedulerTrigger::from_document_input(
            groups.len(),
            scheduler_index,
            trigger_number,
        ) else {
            return Ok(false);
        };
        input.scheduler_index = groups[input.scheduler_index];
        if !self.runtime.has_resolved_binder_sources() {
            return Err("external triggers require resolved Binder sources".into());
        }
        let state = self
            .state
            .as_mut()
            .ok_or("external triggers require active staged playback")?;
        state.trigger_document(&self.runtime, input)
    }
}

