    #[test]
    fn default_smpl_line_endpoint_cache_reaches_slots_without_length_draw_random() {
        use super::super::{VfxClientColorCurveDefaults, VfxClientRandomState, VfxClientTrigMode};
        let cases: serde_json::Value =
            serde_json::from_str(include_str!("fixtures/line-geometry.json")).unwrap();
        for case in cases
            .as_array()
            .unwrap()
            .iter()
            .filter(|c| c["geometry"] == 4 && c["simple"] == true && c["warm"] == false)
        {
            let mut file = fixture();
            file.emitters[0].position = Default::default();
            file.emitters[0].create_interval = curve(&[(0, 1000.0)]);
            file.particles[0] = super::super::particle_curves::tests::line_fixture(case);
            file.particles[0].simple = simple_line_fixture().particles.remove(0).simple;
            file.particles[0].simple.as_mut().unwrap().create_count = 2;
            let mut value = VfxPlayback::new(
                VfxRuntime::new(&file)
                    .with_client_binder_random_state(
                        VfxClientRandomState::from_words([
                            123456789, 362436069, 521288629, 88675123,
                        ]),
                        VfxClientTrigMode::Sse2,
                    )
                    .with_client_color_curve_defaults(VfxClientColorCurveDefaults {
                        empty_random_type: 0,
                        empty_rgba: [1.0; 4],
                    })
                    .with_client_particle_constructor(),
            );
            let check = |value: &VfxPlayback, row: &serde_json::Value, active_slots| {
                assert_eq!(value.fallback_reason(), None, "{case}");
                let output = quads(value);
                assert_eq!(output.len(), active_slots, "{case}");
                // Original endpoint cache enters the existing byte-color pack;
                // white slot colors leave it unchanged before quantization.
                let expected: Vec<_> = row["colors"]
                    .as_array()
                    .unwrap()
                    .chunks_exact(4)
                    .flat_map(|rgba| {
                        super::super::quantize_powder_color(std::array::from_fn(|i| {
                            f32::from_bits(rgba[i].as_u64().unwrap() as u32)
                        }))
                    })
                    .map(f32::to_bits)
                    .collect();
                for quad in &output {
                    let line = quad.line.unwrap();
                    assert!(line.endpoint_offset.is_some());
                    assert_eq!(
                        serde_json::json!(
                            line.color_begin
                                .into_iter()
                                .chain(line.color_end)
                                .map(f32::to_bits)
                                .collect::<Vec<_>>()
                        ),
                        serde_json::json!(expected),
                        "{case}"
                    );
                }
                let random = value.client_binder_random_state();
                assert_eq!(
                    serde_json::json!(random.unwrap().words()),
                    row["state"],
                    "{case}"
                );
                assert_eq!(quads(value), output);
                assert_eq!(value.client_binder_random_state(), random);
            };
            for (i, delta) in [0.0, 3.5, 6.5, 0.0].into_iter().enumerate() {
                step(&mut value, delta);
                // Slots are born during positive Numeric input, not Draw.
                check(
                    &value,
                    &case["instances"][0]["steps"][i],
                    if i == 0 { 0 } else { 2 },
                );
            }
            value.reset();
            step(&mut value, 0.0);
            check(&value, &case["instances"][0]["steps"][0], 0);
        }
    }

