    #[test]
    fn default_vr_birth_before_prewarm_reaches_positions_and_replays() {
        use super::super::{VfxClientColorCurveDefaults, VfxClientRandomState, VfxClientTrigMode};
        let cases: serde_json::Value =
            serde_json::from_str(include_str!("fixtures/particle-vr-default-draw.json")).unwrap();
        for case in cases.as_array().unwrap() {
            let mut file = fixture();
            let emitter = &mut file.emitters[0];
            emitter.create_interval = curve(&[(0, 1000.0)]);
            emitter.position = Default::default();
            emitter.emitter_type = Some(EmitterType::Cone);
            emitter.data = Some(AvfxEmitterData::Cone(ConeEmitterData {
                inner_size: curve(&[(0, 0.0)]),
                outer_size: curve(&[(0, 0.0)]),
                injection_speed: curve(&[(0, 0.125)]),
                injection_angle: curve(&[(0, 0.0)]),
                ..Default::default()
            }));
            let mode = case["mode"].as_u64().unwrap() as u32;
            let item = &mut emitter.particle_items[0];
            item.local_direction = case["localDirection"].as_i64().unwrap() as i32;
            item.start_frame = if case["prewarm"] == true { 4 } else { 0 };
            item.start_frame_null_update = case["prewarm"] == true;
            let particle = &mut file.particles[0];
            if item.start_frame_null_update {
                particle.particle_type = Some(ParticleType::Laser);
                particle.data = AvfxParticleData::Laser(AvfxParticleDataLaser {
                    length: curve(&[(0, 1.0)]),
                    width: curve(&[(0, 1.0)]),
                    ..Default::default()
                });
            }
            particle.air_resistance = curve(&[(0, 0.5)]);
            particle.air_resistance_random = curve(&[(0, 0.25)]);
            particle.air_resistance_random.random_type = mode;
            particle.rotation_velocity = [0.25, -0.5, 0.75].map(|v| curve(&[(0, v)]));
            particle.rotation_velocity_random = std::array::from_fn(|_| {
                let mut c = curve(&[(0, 0.125)]);
                c.random_type = mode;
                c
            });
            let crt = if case["crt"] == 0 {
                VfxClientTrigMode::Sse2
            } else {
                VfxClientTrigMode::AvxFma
            };
            let runtime = VfxRuntime::new(&file)
                .with_client_binder_random_state(
                    VfxClientRandomState::from_words([123456789, 362436069, 521288629, 88675123]),
                    crt,
                )
                .with_client_color_curve_defaults(VfxClientColorCurveDefaults {
                    empty_random_type: 0,
                    empty_rgba: [1.0; 4],
                })
                .with_client_particle_constructor();
            let mut value = VfxPlayback::new(runtime);
            assert_eq!(value.fallback_reason(), None, "{case}");
            let initial = quads(&value);
            assert_eq!(initial.len(), 1);
            assert_eq!(
                serde_json::json!(initial[0].position.map(f32::to_bits)),
                case["initialOffset"]
            );
            assert_eq!(
                serde_json::json!(value.client_binder_random_state().unwrap().words()),
                case["initialState"]
            );
            for (i, row) in case["steps"].as_array().unwrap().iter().enumerate() {
                step(&mut value, if i == 0 { 0.0 } else { 3.75 });
                assert_eq!(value.fallback_reason(), None, "{case}");
                let output = quads(&value);
                assert_eq!(output.len(), 1);
                assert_eq!(
                    serde_json::json!(output[0].position.map(f32::to_bits)),
                    row["offset"],
                    "case {case} input {i}"
                );
                let random = value.client_binder_random_state().unwrap();
                assert_eq!(serde_json::json!(random.words()), row["state"]);
                assert_eq!(quads(&value), output);
                assert_eq!(value.client_binder_random_state(), Some(random));
            }
            value.reset();
            step(&mut value, 0.0);
            step(&mut value, 3.75);
            assert_eq!(
                serde_json::json!(quads(&value)[0].position.map(f32::to_bits)),
                case["steps"][1]["offset"]
            );
            assert_eq!(
                serde_json::json!(value.client_binder_random_state().unwrap().words()),
                case["steps"][1]["state"]
            );
        }
    }

    #[test]
    fn default_vr_end_birth_prewarm_preserves_native_random_order() {
        use super::super::{VfxClientColorCurveDefaults, VfxClientRandomState, VfxClientTrigMode};
        let cases: serde_json::Value =
            serde_json::from_str(include_str!("fixtures/particle-vr-default-draw.json")).unwrap();
        for case in cases
            .as_array()
            .unwrap()
            .iter()
            .filter(|c| c["prewarm"] == true)
        {
            let mut file = fixture();
            let emitter = &mut file.emitters[0];
            emitter.position = Default::default();
            emitter.emitter_type = Some(EmitterType::Cone);
            emitter.data = Some(AvfxEmitterData::Cone(ConeEmitterData {
                inner_size: curve(&[(0, 0.0)]),
                outer_size: curve(&[(0, 0.0)]),
                injection_speed: curve(&[(0, 0.125)]),
                injection_angle: curve(&[(0, 0.0)]),
                ..Default::default()
            }));
            let item = &mut emitter.particle_items[0];
            item.create_time = 2;
            item.local_direction = case["localDirection"].as_i64().unwrap() as i32;
            item.start_frame = 4;
            item.start_frame_null_update = true;
            let mode = case["mode"].as_u64().unwrap() as u32;
            let particle = &mut file.particles[0];
            particle.particle_type = Some(ParticleType::Laser);
            particle.data = AvfxParticleData::Laser(AvfxParticleDataLaser {
                length: curve(&[(0, 1.0)]),
                width: curve(&[(0, 1.0)]),
                ..Default::default()
            });
            particle.air_resistance = curve(&[(0, 0.5)]);
            particle.air_resistance_random = curve(&[(0, 0.25)]);
            particle.air_resistance_random.random_type = mode;
            particle.rotation_velocity = [0.25, -0.5, 0.75].map(|v| curve(&[(0, v)]));
            particle.rotation_velocity_random = std::array::from_fn(|_| {
                let mut c = curve(&[(0, 0.125)]);
                c.random_type = mode;
                c
            });
            let runtime = VfxRuntime::new(&file)
                .with_client_binder_random_state(
                    VfxClientRandomState::from_words([123456789, 362436069, 521288629, 88675123]),
                    if case["crt"] == 0 {
                        VfxClientTrigMode::Sse2
                    } else {
                        VfxClientTrigMode::AvxFma
                    },
                )
                .with_client_color_curve_defaults(VfxClientColorCurveDefaults {
                    empty_random_type: 0,
                    empty_rgba: [1.0; 4],
                })
                .with_client_particle_constructor();
            let mut value = VfxPlayback::new(runtime);
            assert_eq!(value.fallback_reason(), None);
            assert!(quads(&value).is_empty());
            let state = value.state.as_mut().unwrap();
            state
                .instances
                .control_roots(&file, |p| end_owned_root(&mut state.roots[0], 0, p))
                .unwrap();
            // END creates and prewarms the forced particle before recursively
            // retiring it. Its callbacks must consume the original shared stream
            // even though that particle will never be drawn.
            assert_eq!(
                serde_json::json!(value.client_binder_random_state().unwrap().words()),
                case["initialState"],
                "{case}"
            );
            assert!(quads(&value).is_empty());
            let random = value.client_binder_random_state();
            step(&mut value, 0.0);
            assert_eq!(value.fallback_reason(), None);
            assert_eq!(value.client_binder_random_state(), random);
        }
    }

