    #[test]
    fn client_color_playback_owns_first_and_keeps_quad_reads_pure() {
        use super::super::{VfxClientColorCurveState, VfxClientRandomState};
        let file = client_color_playback_file();
        let runtime = client_color_runtime(&file);
        let independent_runtime = runtime.clone();
        let mut value = VfxPlayback::new(runtime);
        assert_eq!(value.fallback_reason(), None);
        let mut expected = VfxClientRandomState::from_words([1, 2, 3, 4]);
        let defaults = super::super::VfxClientColorCurveDefaults {
            empty_random_type: 4,
            empty_rgba: [1.0; 4],
        };
        let emitter =
            VfxClientColorCurveState::construct(&file.emitters[0].color, defaults, &mut expected);
        let mut parent = emitter.evaluate(&file.emitters[0].color, 0.0, 0.0, &mut expected);
        let particle =
            VfxClientColorCurveState::construct(&file.particles[0].color, defaults, &mut expected);
        particle.evaluate(&file.particles[0].color, 0.0, 0.0, &mut expected);
        let mut child = particle.evaluate(&file.particles[0].color, 0.0, 0.0, &mut expected);
        let initial = expected;
        let initial_color: [f32; 4] = std::array::from_fn(|axis| parent[axis] * child[axis]);
        assert_eq!(value.client_binder_random_state(), Some(initial));
        assert_eq!(quads(&value)[0].color, initial_color);
        assert_eq!(quads(&value)[0].color, initial_color);
        assert_eq!(value.client_binder_random_state(), Some(initial));
        let independent = VfxPlayback::new(independent_runtime);
        assert_eq!(independent.client_binder_random_state(), Some(initial));
        assert_eq!(quads(&independent)[0].color, initial_color);
        for _ in 0..3 {
            step(&mut value, 0.0);
            parent = emitter.evaluate(&file.emitters[0].color, 0.0, 0.0, &mut expected);
            child = particle.evaluate(&file.particles[0].color, 0.0, 0.0, &mut expected);
            assert_eq!(value.client_binder_random_state(), Some(expected));
            assert_eq!(
                quads(&value)[0].color,
                std::array::from_fn(|axis| parent[axis] * child[axis])
            );
            assert_eq!(value.client_binder_random_state(), Some(expected));
            assert_eq!(independent.client_binder_random_state(), Some(initial));
        }
        value.reset();
        assert_eq!(value.client_binder_random_state(), Some(initial));
        assert_eq!(quads(&value)[0].color, initial_color);
    }

