    fn client_color_document_rest_keeps_stream_and_rebuilds_first() {
        let mut file = client_color_playback_file();
        file.timelines[0].clips.push(AvfxTimelineClip {
            clip_type: Some(AvfxTimelineClipType::Reset),
            raw_ints: Some([0; 4]),
            raw_floats: Some([0.0, -1.0, -1.0, -1.0]),
            ..Default::default()
        });
        let mut rest = file.timelines[0].items[0];
        rest.emitter_index = -1;
        rest.binder_index = -1;
        rest.clip_index = 0;
        rest.start_time = 1;
        file.timelines[0].items.push(rest);
        let mut value = VfxPlayback::new(
            client_color_runtime(&file)
                .with_binder_target_snapshot(&[])
                .unwrap(),
        );
        assert_eq!(value.fallback_reason(), None);
        let initial = value.client_binder_random_state().unwrap();
        step(&mut value, 1.0);
        assert!(value.state.as_ref().unwrap().document_reset_pending);
        let before_rest = value.client_binder_random_state().unwrap();
        let old_color = quads(&value)[0].color;
        assert_eq!(value.client_binder_random_state(), Some(before_rest));
        step(&mut value, 0.0);
        assert_eq!(value.document_generation(), Some(1));
        let mut expected = before_rest;
        // The replacement Timeline dispatches this new emitter in Prepare,
        // after its Time traversal. One emitter Always, particle First and
        // both particle constructor Always calls consume the retained stream.
        for _ in 0..4 {
            expected.next_u16();
        }
        assert_eq!(value.client_binder_random_state(), Some(expected));
        assert_ne!(quads(&value)[0].color, old_color);
        assert_eq!(value.client_binder_random_state(), Some(expected));
        value.reset();
        assert_eq!(value.document_generation(), Some(0));
        assert_eq!(value.client_binder_random_state(), Some(initial));
    }

    #[test]
    fn client_color_playback_requires_an_explicit_stream() {
        let file = client_color_playback_file();
        let value = VfxPlayback::new(VfxRuntime::new(&file).with_client_color_curve_defaults(
            super::super::VfxClientColorCurveDefaults {
                empty_random_type: 4,
                empty_rgba: [1.0; 4],
            },
        ));
        assert_eq!(
            value.fallback_reason(),
            Some("client Color replay requires an explicit shared random snapshot")
        );
    }

    #[test]
    fn shared_preview_stream_continues_constructors_and_runtime_clone_isolates_replay() {
        use super::super::{
            VfxClientColorCurveDefaults, VfxClientRandomState, VfxClientTrigMode,
            VfxSharedRandomStream,
        };
        let mut file = fixture();
        file.emitters[0].create_interval = curve(&[(0, 1000.0)]);
        file.emitters[0].particle_items[0].parent_influence_color = 2;
        let mut amplitude = curve(&[(0, 0.75)]);
        amplitude.random_type = 4;
        file.emitters[0].color.random[0] = Some(amplitude);
        let seed = VfxClientRandomState::from_words([1, 2, 3, 4]);
        let stream = VfxSharedRandomStream::new(seed);
        let source = || {
            VfxRuntime::new(&file)
                .with_shared_client_random_stream(&stream, VfxClientTrigMode::Sse2)
                .with_client_color_curve_defaults(VfxClientColorCurveDefaults {
                    empty_random_type: 6,
                    empty_rgba: [1.0; 4],
                })
        };
        let first = VfxPlayback::new(source());
        assert_eq!(first.fallback_reason(), None);
        let first_state = stream.snapshot();
        let second = VfxPlayback::new(source());
        assert_eq!(second.fallback_reason(), None);
        assert_ne!(
            stream.snapshot(),
            first_state,
            "second constructor must continue the first document's stream"
        );
        assert_eq!(first.client_binder_random_state(), Some(stream.snapshot()));
        assert_eq!(second.client_binder_random_state(), Some(stream.snapshot()));
        assert_ne!(quads(&first)[0].color, quads(&second)[0].color);
        let shared_state = stream.snapshot();
        let independent = VfxPlayback::new(first.runtime.clone());
        assert_eq!(
            quads(&independent),
            quads(&first),
            "isolated Clone retains owned seed reset"
        );
        assert_eq!(
            stream.snapshot(),
            shared_state,
            "independent replay cannot rewind the live group"
        );
        assert_eq!(independent.client_binder_random_state(), Some(first_state));
        let independent_second = VfxPlayback::new(second.runtime.clone());
        assert_eq!(
            quads(&independent_second),
            quads(&second),
            "each document clone retains its own constructor prefix"
        );
        assert_eq!(stream.snapshot(), shared_state);
    }

    #[test]
    fn shared_preview_document_rest_preserves_peer_stream_and_reset_rejects_invalid_sources() {
        use super::super::{
            VfxClientColorCurveDefaults, VfxClientRandomState, VfxClientTrigMode,
            VfxSharedRandomStream,
        };
        let mut file = rest_fixture(0.0);
        let mut amplitude = curve(&[(0, 0.5)]);
        amplitude.random_type = 1;
        file.particles[0].color.random[1] = Some(amplitude);
        let seed = VfxClientRandomState::from_words([123456789, 362436069, 521288629, 88675123]);
        let stream = VfxSharedRandomStream::new(seed);
        let source = || {
            VfxRuntime::new(&file)
                .with_shared_client_random_stream(&stream, VfxClientTrigMode::Sse2)
                .with_client_color_curve_defaults(VfxClientColorCurveDefaults {
                    empty_random_type: 0,
                    empty_rgba: [1.0; 4],
                })
                .with_binder_target_snapshot(&[])
                .unwrap()
        };
        let mut first = VfxPlayback::new(source());
        let mut peer = VfxPlayback::new(source());
        assert_eq!(first.fallback_reason(), None);
        assert!(first.update_to(0.125));
        assert!(peer.update_to(0.125));
        let before = stream.snapshot();
        let before_time = first.seconds;
        assert!(
            first
                .reset_preview_binder_sources(
                    None,
                    None,
                    Some(super::super::VfxBinderCameraSnapshot {
                        position: [f32::NAN, 0.0, 0.0],
                        basis: super::super::VFX_IDENTITY_BASIS,
                        parallel_direction: [0.0, 0.0, 1.0],
                    })
                )
                .is_err()
        );
        assert_eq!(stream.snapshot(), before);
        assert_eq!(first.seconds, before_time);
        assert!(first.trigger_document(0, 1).unwrap());
        first.advance(0.0).unwrap();
        let pending_state = stream.snapshot();
        assert!(first.state.as_ref().unwrap().document_reset_pending);
        first.advance(0.0).unwrap();
        assert_eq!(first.document_generation(), Some(1));
        assert_ne!(
            stream.snapshot(),
            pending_state,
            "new First bytes consume the continuing group stream"
        );
        assert_ne!(stream.snapshot(), seed);
        assert_eq!(peer.client_binder_random_state(), Some(stream.snapshot()));
        let before_read = stream.snapshot();
        peer.sample(&mut Vec::new(), &mut Vec::new());
        assert_eq!(stream.snapshot(), before_read);
    }

    fn modelskin_curve_runtime(file: &AvfxFile) -> VfxRuntime {
        client_color_runtime(file).with_client_model_skin_curve_defaults(
            super::super::VfxClientModelSkinCurveDefaults {
                vector_random_fallback: [0.0; 3],
            },
        )
    }

    fn modelskin_host_input(
        generation: u32,
        present: bool,
    ) -> super::super::VfxModelSkinTargetInput {
        use super::super::{
            VfxModelSkinCharacterTargets, VfxModelSkinSurface, VfxModelSkinTargetInput,
        };
        VfxModelSkinTargetInput {
            listener_present: present,
            character: Some(VfxModelSkinCharacterTargets {
                generation,
                surfaces: [
                    None,
                    Some(VfxModelSkinSurface {
                        identity: 2,
                        type_code: 3,
                    }),
                    None,
                    None,
                ],
            }),
            ..Default::default()
        }
    }

    fn modelskin_host_file() -> AvfxFile {
        let mut file = fixture();
        file.emitters[0].create_interval = curve(&[(0, 1000.0)]);
        let particle = &mut file.particles[0];
        particle.particle_type = Some(ParticleType::ModelSkin);
        particle.color.alpha = Some(curve(&[(0, 1.0), (20, 0.25)]));
        particle.data = AvfxParticleData::ModelSkin(AvfxParticleDataModelSkin {
            aura_target: 2,
            fresnel_type: 3,
            sem: curve(&[(0, 1.0), (20, 4.0)]),
            fresnel_curve: curve(&[(0, 0.1), (20, 0.9)]),
            fresnel_rotation: AvfxCurve3Axis {
                y: Some(curve(&[(0, 0.0), (20, 1.0)])),
                ..Default::default()
            },
            uv_point_density: AvfxCurve3Axis {
                x: Some(curve(&[(0, 1.0), (20, 3.0)])),
                ..Default::default()
            },
            ..Default::default()
        });
        particle.uv_sets = vec![AvfxUvSet {
            scale: AvfxCurve2Axis {
                x: Some(curve(&[(0, 1.0), (20, 2.0)])),
                ..Default::default()
            },
            ..Default::default()
        }];
        particle.texture_color2 = Some(AvfxParticleTexture {
            enabled: true,
            uv_set_index: 0,
            ..Default::default()
        });
        file
    }

    fn modelskin_host_runtime(file: &AvfxFile, present: bool) -> VfxRuntime {
        VfxRuntime::new(file).with_model_skin_target_snapshot(
            super::super::VfxModelSkinTargetSnapshot {
                selector: -1,
                input: modelskin_host_input(1, present),
            },
        )
    }

    #[test]
    fn modelskin_host_query_freezes_complete_packets_and_retries_once_at_the_same_time() {
        let file = modelskin_host_file();
        let mut value =
            VfxPlayback::new_with_model_skin(modelskin_host_runtime(&file, false), &[0]);
        assert_eq!(value.fallback_reason(), None);
        assert!(value.model_skin_instances().is_empty());
        assert!(value.update_to(0.0));
        assert!(value.model_skin_instances().is_empty());
        assert!(value.observed_model_skin_instances().is_empty());
        value
            .set_model_skin_target_input(modelskin_host_input(1, true))
            .unwrap();
        assert!(
            value.model_skin_instances().is_empty(),
            "setting a host is not an input update"
        );
        assert!(value.update_to(0.0));
        let first = value.model_skin_instances();
        assert_eq!(first.len(), 1);
        let update = value.state.as_ref().unwrap().instances.input_update();
        value
            .set_model_skin_target_input(modelskin_host_input(1, true))
            .unwrap();
        assert!(value.update_to(0.0));
        assert_eq!(
            value.state.as_ref().unwrap().instances.input_update(),
            update
        );
        assert_eq!(value.model_skin_instances(), first);

        value
            .set_model_skin_target_input(modelskin_host_input(1, false))
            .unwrap();
        assert!(!value.update_to(f32::NAN));
        assert!(
            value.model_skin_input_pending,
            "invalid time must not consume the queued input"
        );
        assert!(value.update_to(0.125));
        assert_eq!(
            value.model_skin_instances(),
            first,
            "including color, UV matrices, direction and metadata"
        );
        assert_eq!(value.observed_model_skin_instances(), first);
        let child = value
            .state
            .as_ref()
            .unwrap()
            .instances
            .common_tree_states(0)
            .pop()
            .unwrap();
        assert!(
            child.age > first[0].age,
            "base Time still advances when the query is missing"
        );
        value
            .set_model_skin_target_input(modelskin_host_input(1, true))
            .unwrap();
        assert!(value.update_to(0.125));
        let restored = value.model_skin_instances();
        assert_eq!(restored[0].instance_id, first[0].instance_id);
        assert_ne!(restored[0].color, first[0].color);
        assert_ne!(restored[0].aura_sem, first[0].aura_sem);
        assert_ne!(restored[0].aura_texture_uv, first[0].aura_texture_uv);
        assert_ne!(restored[0].aura_fresnel, first[0].aura_fresnel);
        assert_eq!(restored, value.model_skin_instances());
    }

    #[test]
    fn modelskin_host_generation_retires_old_callbacks_and_reset_accepts_current_host() {
        let file = modelskin_host_file();
        let runtime = modelskin_host_runtime(&file, true);
        let mut independent = VfxPlayback::new_with_model_skin(runtime.clone(), &[0]);
        let mut value = VfxPlayback::new_with_model_skin(runtime, &[0]);
        assert!(value.update_to(0.0));
        let first = value.model_skin_instances();
        value
            .set_model_skin_target_input(modelskin_host_input(2, true))
            .unwrap();
        assert!(value.update_to(0.125));
        assert_eq!(value.model_skin_instances(), first);
        let child = value
            .state
            .as_ref()
            .unwrap()
            .instances
            .common_tree_states(0)
            .pop()
            .unwrap();
        assert_eq!(child.flags & 0x3f00_0000, 0);
        assert_ne!(child.flags & 0x40000, 0);
        value
            .set_model_skin_target_input(modelskin_host_input(1, true))
            .unwrap();
        assert!(value.update_to(0.25));
        assert_eq!(
            value.model_skin_instances(),
            first,
            "cleared callbacks cannot revive the old instance"
        );
        assert!(independent.update_to(0.125));
        assert!(
            independent.model_skin_instances()[0].age > first[0].age,
            "cloning the runtime isolates host updates"
        );
        value
            .set_model_skin_target_input(modelskin_host_input(2, true))
            .unwrap();
        value.reset();
        assert!(value.model_skin_instances().is_empty());
        assert!(value.update_to(0.0));
        assert_eq!(value.model_skin_instances(), first);
        assert!(value.update_to(0.125));
        assert!(value.model_skin_instances()[0].age > first[0].age);
    }

    #[test]
    fn modelskin_host_query_skips_numeric_random_draws_but_preserves_property_updates() {
        let mut file = modelskin_host_file();
        let AvfxParticleData::ModelSkin(data) = &mut file.particles[0].data else {
            unreachable!()
        };
        data.fresnel_type = 1;
        data.sem_random = curve(&[(0, 1.0)]);
        data.sem_random.random_type = 4;
        let mut color_random = curve(&[(0, 0.5)]);
        color_random.random_type = 4;
        file.particles[0].color.random[0] = Some(color_random);
        let runtime = modelskin_host_runtime(&file, false)
            .with_client_binder_random_state(
                super::super::VfxClientRandomState::from_words([1, 2, 3, 4]),
                super::super::VfxClientTrigMode::Sse2,
            )
            .with_client_color_curve_defaults(super::super::VfxClientColorCurveDefaults {
                empty_random_type: 6,
                empty_rgba: [1.0; 4],
            })
            .with_client_model_skin_curve_defaults(super::super::VfxClientModelSkinCurveDefaults {
                vector_random_fallback: [0.0; 3],
            });
        let mut value = VfxPlayback::new_with_model_skin(runtime, &[0]);
        assert_eq!(value.fallback_reason(), None);
        let mut expected = value.client_binder_random_state().unwrap();
        assert!(value.update_to(0.0));
        expected.next_u16(); // Col properties run even on a zero input; Aura is skipped.
        assert_eq!(value.client_binder_random_state(), Some(expected));
        assert!(value.model_skin_instances().is_empty());
        value
            .set_model_skin_target_input(modelskin_host_input(1, true))
            .unwrap();
        assert!(value.update_to(0.0));
        let first = value.model_skin_instances();
        assert_eq!(first.len(), 1);
        expected.next_u16(); // Col property callback on this zero input.
        expected.next_u16(); // SEM's active Always channel in Aura Numeric.
        assert_eq!(value.client_binder_random_state(), Some(expected));
        let before = expected;
        value
            .set_model_skin_target_input(modelskin_host_input(1, false))
            .unwrap();
        assert!(value.update_to(0.125));
        expected.next_u16(); // Col property remains active; SEM Numeric is skipped.
        assert_eq!(value.client_binder_random_state(), Some(expected));
        assert_eq!(value.model_skin_instances(), first);
        assert_ne!(expected, before);
        assert_eq!(value.observed_model_skin_instances(), first);
        assert_eq!(
            value.client_binder_random_state(),
            Some(expected),
            "reads consume neither curve"
        );
        value
            .set_model_skin_target_input(modelskin_host_input(1, true))
            .unwrap();
        assert!(value.update_to(0.125));
        expected.next_u16(); // Col property callback.
        expected.next_u16(); // SEM Numeric after the query recovers.
        assert_eq!(value.client_binder_random_state(), Some(expected));
        assert!(value.model_skin_instances()[0].age > first[0].age);
        assert!(value.update_to(0.125));
        assert_eq!(
            value.client_binder_random_state(),
            Some(expected),
            "same host and time do not redraw Always"
        );
    }

    #[test]
    fn modelskin_shared_creation_order_continues_documents_and_isolates_clones() {
        let file = modelskin_host_file();
        let order = super::super::VfxModelSkinCreationOrder::new();
        let source =
            || modelskin_host_runtime(&file, true).with_shared_model_skin_creation_order(&order);
        let mut first = VfxPlayback::new_with_model_skin(source(), &[0]);
        let mut second = VfxPlayback::new_with_model_skin(source(), &[0]);
        assert!(first.update_to(0.0));
        assert!(second.update_to(0.0));
        assert_eq!(first.model_skin_instances()[0].aura_creation_order, Some(0));
        assert_eq!(
            second.model_skin_instances()[0].aura_creation_order,
            Some(1)
        );
        assert_eq!(order.snapshot(), 2);
        let mut independent = VfxPlayback::new_with_model_skin(second.runtime.clone(), &[0]);
        assert!(independent.update_to(0.0));
        assert_eq!(
            independent.model_skin_instances(),
            second.model_skin_instances()
        );
        assert_eq!(order.snapshot(), 2);
        independent.reset();
        assert!(independent.update_to(0.0));
        assert_eq!(
            independent.model_skin_instances(),
            second.model_skin_instances()
        );
        assert_eq!(order.snapshot(), 2);
        let old_time = first.seconds;
        assert!(
            first
                .reset_preview_binder_sources(
                    None,
                    None,
                    Some(super::super::VfxBinderCameraSnapshot {
                        position: [f32::NAN, 0.0, 0.0],
                        basis: super::super::VFX_IDENTITY_BASIS,
                        parallel_direction: [0.0, 0.0, 1.0],
                    })
                )
                .is_err()
        );
        assert_eq!(order.snapshot(), 2);
        assert_eq!(first.seconds, old_time);
        order.reset();
        first.reset();
        second.reset();
        assert!(first.update_to(0.0));
        assert!(second.update_to(0.0));
        assert_eq!(first.model_skin_instances()[0].aura_creation_order, Some(0));
        assert_eq!(
            second.model_skin_instances()[0].aura_creation_order,
            Some(1)
        );
        assert_eq!(order.snapshot(), 2);
    }

    #[test]
    fn modelskin_shared_creation_order_document_rest_preserves_peer_order() {
        let mut file = rest_fixture(0.0);
        file.particles[0] = modelskin_host_file().particles.remove(0);
        let order = super::super::VfxModelSkinCreationOrder::new();
        let source = || {
            modelskin_host_runtime(&file, true)
                .with_shared_model_skin_creation_order(&order)
                .with_binder_target_snapshot(&[])
                .unwrap()
        };
        let mut first = VfxPlayback::new_with_model_skin(source(), &[0]);
        let mut peer = VfxPlayback::new_with_model_skin(source(), &[0]);
        assert!(first.update_to(0.0));
        assert!(peer.update_to(0.0));
        let initial = first.model_skin_instances()[0];
        let peer_initial = peer.model_skin_instances()[0];
        assert_eq!(initial.aura_creation_order, Some(0));
        assert_eq!(peer_initial.aura_creation_order, Some(1));
        assert!(first.trigger_document(0, 1).unwrap());
        first.advance(0.0).unwrap();
        first.advance(0.0).unwrap();
        assert_eq!(first.document_generation(), Some(1));
        let new = first.model_skin_instances()[0];
        assert_eq!(new.aura_creation_order, Some(2));
        assert_ne!(new.instance_id, initial.instance_id);
        assert_eq!(peer.model_skin_instances(), vec![peer_initial]);
        assert_eq!(order.snapshot(), 3);
        assert_eq!(first.model_skin_instances(), vec![new]);
        assert_eq!(order.snapshot(), 3);
    }

    #[test]
    fn modelskin_host_document_rest_rebuilds_query_generation_and_discards_old_packets() {
        let mut file = rest_fixture(0.0);
        file.particles[0] = modelskin_host_file().particles.remove(0);
        let mut value = VfxPlayback::new_with_model_skin(
            modelskin_host_runtime(&file, true)
                .with_binder_target_snapshot(&[])
                .unwrap(),
            &[0],
        );
        assert_eq!(value.fallback_reason(), None);
        assert!(value.update_to(0.0));
        let first = value.model_skin_instances();
        value
            .set_model_skin_target_input(modelskin_host_input(2, true))
            .unwrap();
        assert!(value.update_to(0.125));
        assert_eq!(value.model_skin_instances(), first);
        assert!(value.trigger_document(0, 1).unwrap());
        value.advance(0.0).unwrap(); // deferred request
        assert_eq!(value.document_generation(), Some(0));
        value.advance(0.0).unwrap(); // replacement uses current generation 2
        assert_eq!(value.document_generation(), Some(1));
        let next = value.model_skin_instances();
        assert_eq!(next.len(), 1);
        assert_ne!(next[0].instance_id, first[0].instance_id);
        assert_eq!(value.observed_model_skin_instances(), next);
        assert_eq!(
            value
                .state
                .as_ref()
                .unwrap()
                .model_skin_packets
                .borrow()
                .len(),
            1
        );
        value.advance(0.125).unwrap();
        assert!(value.model_skin_instances()[0].age > next[0].age);
    }

    #[test]
    fn modelskin_curve_public_outputs_match_original_numeric_golden_and_reads_are_pure() {
        let original: serde_json::Value =
            serde_json::from_str(include_str!("fixtures/modelskin_curves_golden.json")).unwrap();
        for case in original["cases"].as_array().unwrap() {
            let mut file = trace::model_skin_phases_tests::file_for(case);
            file.timelines = fixture().timelines;
            file.particles[0].rotation_direction_base = crate::avfx::rotation_direction_base::NONE;
            let runtime = VfxRuntime::new(&file)
                .with_client_binder_random_state(
                    super::super::VfxClientRandomState::from_words(std::array::from_fn(|i| {
                        case["seed"][i].as_u64().unwrap() as u32
                    })),
                    super::super::VfxClientTrigMode::Sse2,
                )
                .with_client_color_curve_defaults(super::super::VfxClientColorCurveDefaults {
                    empty_random_type: case["emptyRandomType"].as_u64().unwrap() as u32,
                    empty_rgba: std::array::from_fn(|i| {
                        f32::from_bits(case["emptyRgba"][i].as_u64().unwrap() as u32)
                    }),
                })
                .with_client_model_skin_curve_defaults(
                    super::super::VfxClientModelSkinCurveDefaults {
                        vector_random_fallback: std::array::from_fn(|i| {
                            f32::from_bits(case["fallback"][i].as_u64().unwrap() as u32)
                        }),
                    },
                );
            let mut value = VfxPlayback::new_with_model_skin(runtime, &[0]);
            assert_eq!(value.fallback_reason(), None);
            // The constructor prepares curves, but Aura has no successful
            // numeric application until the first explicit input.
            assert!(value.model_skin_instances().is_empty());
            assert!(value.observed_model_skin_instances().is_empty());
            assert_eq!(
                value.client_binder_random_state().unwrap().words(),
                std::array::from_fn(|i| case["initialState"][i].as_u64().unwrap() as u32)
            );
            step(&mut value, 0.0);
            let snapshot = value.client_binder_random_state();
            assert_eq!(
                snapshot.unwrap().words(),
                std::array::from_fn(
                    |i| case["steps"][0]["afterNumericState"][i].as_u64().unwrap() as u32
                )
            );
            let output = value.model_skin_instances();
            assert_eq!(output.len(), 2);
            for (index, actual) in output.iter().enumerate() {
                let expected = &case["steps"][0]["afterNumeric"][index];
                let floats: Vec<f32> = expected["values"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|v| f32::from_bits(v.as_u64().unwrap() as u32))
                    .collect();
                let color: [f32; 4] = std::array::from_fn(|i| {
                    f32::from_bits(expected["color"][i].as_u64().unwrap() as u32)
                });
                assert_eq!(actual.color, color);
                for axis in 0..4 {
                    assert_eq!(
                        actual.aura_color_begin[axis].to_bits(),
                        (if axis < 3 {
                            color[axis] * floats[axis]
                        } else {
                            floats[axis]
                        })
                        .to_bits()
                    );
                    assert_eq!(
                        actual.aura_color_end[axis].to_bits(),
                        (if axis < 3 {
                            color[axis] * floats[4 + axis]
                        } else {
                            floats[4 + axis]
                        })
                        .to_bits()
                    );
                }
                assert_eq!(actual.aura_fresnel[3].to_bits(), floats[11].to_bits());
                assert_eq!(actual.aura_sem.to_bits(), floats[12].to_bits());
                assert_eq!(actual.aura_eem.to_bits(), floats[13].to_bits());
                for axis in 0..3 {
                    assert_eq!(
                        actual.aura_uv_point_density[axis].to_bits(),
                        floats[14 + axis].max(0.0).to_bits()
                    );
                }
            }
            let read_signature = serde_json::to_value(&output).unwrap();
            assert_eq!(
                serde_json::to_value(value.model_skin_instances()).unwrap(),
                read_signature
            );
            assert_eq!(value.client_binder_random_state(), snapshot);
            assert_eq!(value.observed_model_skin_instances().len(), 1);
            assert_eq!(value.client_binder_random_state(), snapshot);
            let mut independent = VfxPlayback::new_with_model_skin(value.runtime.clone(), &[0]);
            step(&mut independent, 0.0);
            assert_eq!(
                serde_json::to_value(independent.model_skin_instances()).unwrap(),
                read_signature
            );
            assert_eq!(value.client_binder_random_state(), snapshot);
            value.reset();
            assert!(value.model_skin_instances().is_empty());
            step(&mut value, 0.0);
            assert_eq!(value.client_binder_random_state(), snapshot);
            assert_eq!(
                serde_json::to_value(value.model_skin_instances()).unwrap(),
                read_signature
            );
        }
    }

    #[test]
    fn modelskin_curve_rest_keeps_compiled_pair_dispatch_and_stream() {
        let mut file = client_color_playback_file();
        file.particles[0].particle_type = Some(ParticleType::ModelSkin);
        file.particles[0].data = AvfxParticleData::ModelSkin(AvfxParticleDataModelSkin {
            fresnel_type: 1,
            ..Default::default()
        });
        file.timelines[0].clips.push(AvfxTimelineClip {
            clip_type: Some(AvfxTimelineClipType::Reset),
            raw_ints: Some([0; 4]),
            raw_floats: Some([0.0, -1.0, -1.0, -1.0]),
            ..Default::default()
        });
        let mut rest = file.timelines[0].items[0];
        rest.emitter_index = -1;
        rest.binder_index = -1;
        rest.clip_index = 0;
        rest.start_time = 1;
        file.timelines[0].items.push(rest);
        let mut value = VfxPlayback::new_with_model_skin(
            modelskin_curve_runtime(&file)
                .with_binder_target_snapshot(&[])
                .unwrap(),
            &[0],
        );
        assert_eq!(value.fallback_reason(), None);
        step(&mut value, 0.0);
        let after_first = value.client_binder_random_state().unwrap();
        assert_eq!(
            value
                .runtime
                .client_model_skin_curves
                .as_ref()
                .unwrap()
                .dispatch_codes(0),
            [4; 3]
        );
        step(&mut value, 1.0);
        assert!(value.state.as_ref().unwrap().document_reset_pending);
        let before_rest = value.client_binder_random_state().unwrap();
        step(&mut value, 0.0);
        let mut expected = before_rest;
        // Four Col constructor draws. All three empty scalar-pair dispatches
        // stay cached Empty across Document replacement, consuming no lazy draw.
        for _ in 0..4 {
            expected.next_u16();
        }
        assert_eq!(value.client_binder_random_state(), Some(expected));
        assert_eq!(value.document_generation(), Some(1));
        assert_eq!(value.model_skin_instances().len(), 1);
        assert_eq!(
            value
                .runtime
                .client_model_skin_curves
                .as_ref()
                .unwrap()
                .dispatch_codes(0),
            [4; 3]
        );
        value.reset();
        assert_eq!(
            value
                .runtime
                .client_model_skin_curves
                .as_ref()
                .unwrap()
                .dispatch_codes(0),
            [0; 3]
        );
        step(&mut value, 0.0);
        assert_eq!(value.client_binder_random_state(), Some(after_first));
    }

