    fn snapshot_spline_curve_state(
        runtime: &VfxRuntime,
        objects: &[SplineRootState],
    ) -> serde_json::Value {
        use serde_json::json;
        let matrix = |m: VfxBinderMatrix| {
            m.basis
                .into_iter()
                .flatten()
                .chain(m.position)
                .map(f32::to_bits)
                .collect::<Vec<_>>()
        };
        let children = objects.iter().map(|object| {
            let instance = &object.instance;
            let c = instance.lifecycle.clock;
            let s = &instance.state;
            json!({"targets":object.target_indices,"lifeEnabled":instance.lifecycle.life_limit_enabled,"initialized":instance.initialized,
                "clocks":([c.local_age,c.total_age,instance.lifecycle.scaled_delta,c.previous_age,c.nominal_life].map(f32::to_bits)),"life":[c.nominal_life.to_bits()],"delay":[c.delay.to_bits()],
                "main":matrix(s.common.matrix),"auxiliary":matrix(s.common.auxiliary_matrix),"scale":s.common.scale.map(f32::to_bits),
                "offsets":s.controls().into_iter().flat_map(|p|p.offset.map(f32::to_bits)).collect::<Vec<_>>(),"parameters":s.controls().map(|p|p.parameter.to_bits()),
                "knots":s.path().knots().iter().map(|p|json!({"parameter":p.parameter.to_bits(),"position":p.position.map(f32::to_bits)})).collect::<Vec<_>>()})
        }).collect::<Vec<_>>();
        json!({"factory":{"children":children,"randomState":runtime.client_binder_random_state().unwrap().words()},
            "factorDispatch":runtime.client_binder_curves.as_ref().unwrap().dispatch_code(0),
            "coefficients":objects.iter().map(|o|o.curves.unwrap().first_percentages()).collect::<Vec<_>>()})
    }
    fn compare_spline_authored_curves_with_owned_playback(animated: bool) {
        use super::super::binder_curves::tests::{canonicalize, scoped_expected};
        use serde_json::{Value, json};
        let folder =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target/weapon-vfx-audit");
        let prefix = if animated {
            "spline-animated-curves"
        } else {
            "spline-compiled-curves"
        };
        let original: Value = serde_json::from_slice(
            &std::fs::read(folder.join(format!("{prefix}-client-probe.json"))).unwrap(),
        )
        .unwrap();
        let cases = original["cases"].as_array().unwrap();
        let families = if animated { 6 } else { 1 };
        assert_eq!(cases.len(), 6912 * families);
        let mut boundaries = 0;
        let mut object_count = 0;
        let mut scheduler_tree_boundaries = 0;
        for (ordinal, case) in cases.iter().enumerate() {
            let owner = case["ownerKind"].as_u64().unwrap();
            let mut file = spline_curve_factory_file(
                owner,
                case["scenario"].as_u64().unwrap() as u32,
                case["startMode"].as_i64().unwrap() as i32,
                case["goalMode"].as_i64().unwrap() as i32,
                case["generateDelay"].as_i64().unwrap() as i32,
            );
            if animated {
                file.binders[0] = super::super::binder_curves::tests::authored_binder(case);
            }
            let count = case["targetCount"].as_u64().unwrap() as usize;
            let initial = case["initialSuccessMask"].as_u64().unwrap();
            let source = |x: f32, success: u64| {
                let mut s = linear_target_source(x);
                s.targets
                    .retain(|t| (t.id == 4 && success & 1 != 0) || (t.id == 7 && success & 2 != 0));
                s
            };
            let mode = if case["trigMode"] == 0 {
                super::super::VfxClientTrigMode::Sse2
            } else {
                super::super::VfxClientTrigMode::AvxFma
            };
            let mut runtime = VfxRuntime::new(&file)
                .with_binder_target_snapshot(&source(100.0, initial).targets)
                .unwrap()
                .with_binder_target_objects(
                    &(0..count)
                        .map(|i| source(i as f32 * 10.0, initial))
                        .collect::<Vec<_>>(),
                )
                .unwrap()
                .with_client_binder_random_state(
                    super::super::VfxClientRandomState::from_words(std::array::from_fn(|i| {
                        case["seed"][i].as_u64().unwrap() as u32
                    })),
                    mode,
                )
                .with_client_binder_curve_defaults(super::super::VfxClientBinderCurveDefaults {
                    empty_scalar_random_type: case["emptyRandomType"].as_u64().unwrap() as u32,
                    vector_random_fallback: [f32::from_bits(
                        case["fallback"].as_u64().unwrap() as u32
                    ); 3],
                });
            let mut scheduler_playback = (owner == 1).then(|| VfxPlayback::new(runtime.clone()));
            if let Some(value) = &scheduler_playback {
                assert_eq!(value.fallback_reason(), None, "Scheduler case {ordinal}");
            }
            let mut objects = Vec::new();
            if owner == 1 {
                let (mut roots, mut parents, mut loops, mut events) =
                    (Vec::new(), Vec::new(), Vec::new(), Vec::new());
                stage_timeline(
                    &runtime,
                    &HashSet::new(),
                    &file.timelines[0],
                    0,
                    0.0,
                    Some(0),
                    true,
                    false,
                    (0, -1),
                    false,
                    true,
                    &mut roots,
                    &mut parents,
                    &mut loops,
                    &mut events,
                )
                .unwrap();
                objects.extend(
                    construct_scheduler_definition(&runtime, &parents[0], 0.0)
                        .unwrap()
                        .into_iter()
                        .map(|p| p.spline.unwrap()),
                );
            } else {
                let mut staged = StagedPlayback::new(&runtime, &HashSet::new()).unwrap();
                let template = staged.timeline_parents[0].templates[0].clone();
                staged
                    .instances
                    .control_roots(&file, |preparation| {
                        for plan in item_factory_births(&runtime, 0) {
                            let mut root = template.clone();
                            root.linear_birth = plan.linear;
                            root.point_birth = None;
                            root.life = 30.0;
                            let index =
                                preparation.add_binder_root(root.index, root.life, root.seed)?;
                            root.construct_binder(&runtime, 0, 0.0, 0.0, index, preparation)?;
                            objects.push(root.spline_binder.unwrap());
                        }
                        Ok(())
                    })
                    .unwrap();
            }
            object_count += objects.len();
            let compare = |v: Value, objects: &[_], runtime: &VfxRuntime, boundary: usize| {
                let mut expected = scoped_expected(v);
                expected["factory"]
                    .as_object_mut()
                    .unwrap()
                    .remove("queryTargets");
                let mut actual = snapshot_spline_curve_state(runtime, objects);
                canonicalize(&mut expected);
                canonicalize(&mut actual);
                assert_eq!(actual, expected, "owned case {ordinal} boundary {boundary}");
            };
            compare(case["afterFactory"].clone(), &objects, &runtime, 0);
            boundaries += 1;
            if let Some(value) = &scheduler_playback {
                let owned = value
                    .state
                    .as_ref()
                    .unwrap()
                    .timeline_parents
                    .iter()
                    .filter_map(|p| p.spline.clone())
                    .collect::<Vec<_>>();
                compare(case["afterFactory"].clone(), &owned, &value.runtime, 0);
                scheduler_tree_boundaries += 1;
            }
            for (tick, input) in case["inputs"].as_array().unwrap().iter().enumerate() {
                if tick >= 2 {
                    runtime.binder_targets = Some(source(100.0, 3).targets);
                    runtime.binder_target_objects =
                        Some((0..count).map(|i| source(i as f32 * 10.0, 3)).collect());
                }
                let delta = f32::from_bits(input["delta"].as_u64().unwrap() as u32);
                for object in &mut objects {
                    object.instance.advance_time(delta);
                }
                for object in &mut objects {
                    let children = object.instance.lifecycle.registered_children();
                    object
                        .prepare_child(
                            &runtime,
                            &mut linear_base(
                                object.instance.state.common,
                                &runtime.file.binders[object.binder_index],
                            ),
                            tick + 1,
                            children,
                            |_, _| Ok(()),
                        )
                        .unwrap();
                }
                compare(input["afterPrepare"].clone(), &objects, &runtime, tick + 1);
                boundaries += 1;
                if let Some(value) = &mut scheduler_playback {
                    if tick >= 2 {
                        value.runtime.binder_targets = runtime.binder_targets.clone();
                        value.runtime.binder_target_objects = runtime.binder_target_objects.clone();
                    }
                    value
                        .state
                        .as_mut()
                        .unwrap()
                        .advance(&value.runtime, delta)
                        .unwrap();
                    let owned = value
                        .state
                        .as_ref()
                        .unwrap()
                        .timeline_parents
                        .iter()
                        .filter_map(|p| p.spline.clone())
                        .collect::<Vec<_>>();
                    compare(
                        input["afterPrepare"].clone(),
                        &owned,
                        &value.runtime,
                        tick + 1,
                    );
                    scheduler_tree_boundaries += 1;
                }
            }
        }
        assert_eq!(boundaries, 41472 * families);
        assert_eq!(object_count, 6336 * families);
        assert_eq!(scheduler_tree_boundaries, 20736 * families);
        let connection_pairs = if animated {
            let pairs = cases
                .iter()
                .flat_map(|c| c["connections"].as_array().unwrap())
                .map(|pair| {
                    (
                        pair[0].as_u64().unwrap() & 15,
                        pair[1].as_u64().unwrap() & 15,
                    )
                })
                .collect::<HashSet<_>>();
            assert_eq!(pairs.len(), 100);
            pairs.len()
        } else {
            1
        };
        std::fs::write(folder.join(format!("{prefix}-playback-comparison.json")),serde_json::to_vec_pretty(&json!({
            "cases":cases.len(),"boundaries":boundaries,"constructedObjects":object_count,"schedulerTreeBoundaries":scheduler_tree_boundaries,"differences":0,
            "animatedConnectedRawCurves":animated,
            "rawCurveInputsParsed":animated,
            "mainRandomConnectionPairs":connection_pairs,
            "schedulerTreeCases":3456*families,
            "scope":"Original raw scalar/XYZ block compilers followed by actual production Scheduler/Item constructors and owned Spline curve state, runtime-shared COF cache and RNG, followed by owned SplineRootState own Time/Prepare. Original factories plus five own phase inputs compared: ordered targets, initialization/life gates, clocks, matrix/scale, controls/knots, seven First bytes, dispatch cache and RNG words. The Scheduler half additionally runs complete production tree advance with active empty Emitter resources under the Timeline; only parent numerics and shared curve/RNG state compared. Native child resources/phases inert; independent owned Item follow-up child attachment callback controlled. Animation/connection coverage is indicated separately; constant probe does not prove animated readers. Does not prove native child phases/REST, complete Item tree advance, registry flags/pool, query counters, live compiled defaults, every RNG consumer or GPU. Finite/Inf/signed zeros bitwise, NaN classification."
        })).unwrap()).unwrap();
    }

    #[test]
    fn spline_scheduler_cartesian_instances_drive_actual_child_geometry() {
        let file = spline_factory_file(1, 1, 1, 0, 3);
        let mut value = spline_playback(
            &file,
            &[
                linear_target_source(0.0),
                linear_target_source(10.0),
                linear_target_source(20.0),
            ],
        );
        assert_eq!(value.fallback_reason(), None);
        step(&mut value, 0.0);
        let state = value.state.as_ref().unwrap();
        let identities = state
            .timeline_parents
            .iter()
            .map(|p| p.spline.as_ref().unwrap().target_indices)
            .collect::<Vec<_>>();
        assert_eq!(identities, [[0, 1], [0, 2], [1, 0], [1, 2], [2, 0], [2, 1]]);
        let visible = quads(&value);
        assert_eq!(visible.len(), 6);
        for (parent, quad) in state.timeline_parents.iter().zip(visible) {
            let instance = &parent.spline.as_ref().unwrap().instance;
            assert_eq!(instance.lifecycle.registered_children(), 1);
            for axis in 0..3 {
                near(
                    quad.position[axis],
                    instance.state.common.matrix.position[axis],
                );
            }
        }
    }

    #[test]
    fn spline_item_delayed_birth_consumes_shared_random_only_once() {
        let mut file = spline_factory_file(0, 0, 1, 2, 3);
        file.binders[0].life = 30;
        let mut value = spline_playback(
            &file,
            &[linear_target_source(0.0), linear_target_source(10.0)],
        );
        assert_eq!(value.fallback_reason(), None);
        step(&mut value, 0.0);
        let first_random = value.client_binder_random_state().unwrap();
        assert_eq!(value.state.as_ref().unwrap().roots.len(), 2);
        assert_eq!(quads(&value).len(), 1);
        step(&mut value, 0.0);
        assert_eq!(value.client_binder_random_state(), Some(first_random));
        step(&mut value, 2.5);
        assert_eq!(quads(&value).len(), 2);
        let root = &value.state.as_ref().unwrap().roots[1];
        let instance = &root.spline_binder.as_ref().unwrap().instance;
        assert!(instance.initialized);
        assert_eq!(instance.lifecycle.clock.local_age, 0.5);
        assert_eq!(instance.lifecycle.registered_children(), 1);
        let after_birth = value.client_binder_random_state();
        assert_ne!(after_birth, Some(first_random));
        value
            .advance_with_binder_target_objects(
                2.5 / 30.0,
                &[linear_target_source(5.0), linear_target_source(15.0)],
            )
            .unwrap();
        assert_eq!(value.client_binder_random_state(), after_birth);
        assert_eq!(
            value.state.as_ref().unwrap().roots[1]
                .spline_binder
                .as_ref()
                .unwrap()
                .instance
                .state
                .common
                .targets[1]
                .position[0],
            18.0
        );
    }

