    #[test]
    fn spline_reset_replays_snapshot_and_runtime_clones_are_independent() {
        fn send_sync<T: Send + Sync>() {}
        send_sync::<VfxRuntime>();
        let file = spline_factory_file(0, 0, 1, 0, 0);
        let mut value = spline_playback(
            &file,
            &[linear_target_source(0.0), linear_target_source(10.0)],
        );
        let mut clone = VfxPlayback::new(value.runtime.clone());
        step(&mut value, 0.0);
        let first = value.client_binder_random_state().unwrap();
        assert_eq!(
            first.words(),
            [495446302, 2377263435, 2579005291, 717252425]
        );
        step(&mut clone, 0.0);
        assert_eq!(clone.client_binder_random_state(), Some(first));
        value.reset();
        step(&mut value, 0.0);
        assert_eq!(value.client_binder_random_state(), Some(first));
        let mut legacy = ClientXorShift128::seeded(9);
        let mut expected = first;
        assert_eq!(legacy.next_for_runtime(&value.runtime), expected.next_u16());
        assert_eq!(value.client_binder_random_state(), Some(expected));
        assert_eq!(clone.client_binder_random_state(), Some(first));
    }

    #[test]
    fn spline_document_rest_keeps_stream_while_explicit_reset_restores_it() {
        let mut file = spline_factory_file(1, 0, 0, 0, 0);
        file.timelines[0].clips.push(AvfxTimelineClip {
            clip_type: Some(AvfxTimelineClipType::Reset),
            raw_ints: Some([0; 4]),
            raw_floats: Some([0.0, -1.0, -1.0, -1.0]),
            ..Default::default()
        });
        let mut rest = file.timelines[0].items[0];
        rest.emitter_index = -1;
        rest.binder_index = -1;
        rest.clip_index = 0;
        rest.start_time = 1;
        file.timelines[0].items.push(rest);
        let mut value = spline_playback(&file, &[]);
        let after_constructor = value.client_binder_random_state().unwrap();
        step(&mut value, 1.0);
        assert!(value.state.as_ref().unwrap().document_reset_pending);
        assert_eq!(value.client_binder_random_state(), Some(after_constructor));
        step(&mut value, 0.0);
        assert_eq!(value.document_generation(), Some(1));
        let mut expected = after_constructor;
        for _ in 0..4 {
            expected.next_u16();
        }
        assert_eq!(value.client_binder_random_state(), Some(expected));
        value.reset();
        assert_eq!(value.document_generation(), Some(0));
        assert_eq!(value.client_binder_random_state(), Some(after_constructor));
    }

