    #[test]
    fn spline_target_factory_rest_replaces_only_oldest_ready_parent() {
        let mut file = spline_factory_file(1, 1, 1, 0, 3);
        file.binders[0].life = 30;
        let mut rest = file.timelines[0].items[0];
        rest.emitter_index = -1;
        rest.clip_index = 0;
        file.timelines.push(AvfxTimeline {
            binder_index: -1,
            items: vec![rest],
            clips: vec![AvfxTimelineClip {
                clip_type: Some(AvfxTimelineClipType::Reset),
                raw_ints: Some([0, 1, 0, 0]),
                raw_floats: Some([-1.0, 0.0, 0.0, 0.0]),
                ..Default::default()
            }],
            ..Default::default()
        });
        file.schedulers[0].triggers = vec![AvfxSchedulerItem {
            enabled: true,
            start_time: 0,
            timeline_index: 1,
        }];
        let mut value = spline_playback(
            &file,
            &[linear_target_source(10.0), linear_target_source(20.0)],
        );
        step(&mut value, 0.0);
        let ids = [
            value.state.as_ref().unwrap().instances.root_id(0),
            value.state.as_ref().unwrap().instances.root_id(1),
        ];
        assert!(value.trigger_document(0, 1).unwrap());
        value
            .advance_with_binder_target_objects(
                0.0,
                &[
                    linear_target_source(11.0),
                    linear_target_source(22.0),
                    linear_target_source(33.0),
                ],
            )
            .unwrap();
        let state = value.state.as_ref().unwrap();
        let live = state
            .timeline_parents
            .iter()
            .filter(|p| p.spline.is_some())
            .collect::<Vec<_>>();
        assert_eq!(live.len(), 7);
        assert_eq!(
            live.iter()
                .min_by_key(|p| p.prepare_order)
                .unwrap()
                .spline
                .as_ref()
                .unwrap()
                .target_indices,
            [1, 0]
        );
        let new_ids = (0..state.roots.len())
            .filter_map(|i| state.instances.root_id(i))
            .collect::<Vec<_>>();
        assert!(!new_ids.contains(&ids[0].unwrap()));
        assert!(new_ids.contains(&ids[1].unwrap()));
        assert_eq!(quads(&value).len(), 7);
    }

    #[test]
    fn spline_target_factory_scheduler_unlock_reaches_pending_and_future_children() {
        for kind in [2] {
            let mut file = spline_factory_file(1, 0, 1, 2, 3);
            file.binders[0].life = 30;
            file.binders[0].binder_type = kind;
            file.timelines[0].loop_start = 0;
            file.timelines[0].loop_end = 3;
            file.emitters[0].loop_start = 0;
            file.emitters[0].loop_end = 3;
            file.particles[0].loop_start = 0;
            file.particles[0].loop_end = 3;
            let mut unlock = ullp_fixture(true).timelines.remove(0);
            unlock.items[0].start_time = 0;
            file.timelines.push(unlock);
            file.schedulers[0].triggers = vec![AvfxSchedulerItem {
                enabled: true,
                start_time: 0,
                timeline_index: 1,
            }];
            let mut value = spline_playback(
                &file,
                &[linear_target_source(10.0), linear_target_source(20.0)],
            );
            step(&mut value, 0.0);
            assert!(
                value.state.as_ref().unwrap().timeline_parents[1]
                    .child
                    .is_none()
            );
            assert!(value.trigger_document(0, 1).unwrap());
            step(&mut value, 0.0);
            let state = value.state.as_ref().unwrap();
            assert!(state.scheduler_unlocked.contains(&0));
            for parent in state.timeline_parents.iter().filter(|p| p.spline.is_some()) {
                assert!(parent.parent_disables_loop);
                assert_eq!(
                    parent.binder_lifecycle().unwrap().raw_flags() & 0x80c00000,
                    0x00800000
                );
            }
            step(&mut value, 2.0);
            let state = value.state.as_ref().unwrap();
            for parent in state.timeline_parents.iter().filter(|p| p.spline.is_some()) {
                assert_eq!(parent.child.unwrap().raw_flags() & 0x80c00000, 0x00800000);
            }
            for index in 0..state.roots.len() {
                assert!(
                    state
                        .instances
                        .common_tree_states(index)
                        .iter()
                        .all(|n| n.flags & 0x80c00000 == 0x00800000)
                );
            }
            step(&mut value, 3.0);
            let state = value.state.as_ref().unwrap();
            assert_eq!(
                state.roots.len(),
                2,
                "unlocked inner Timelines must not create loop generations"
            );
            assert!(
                state
                    .timeline_parents
                    .iter()
                    .filter_map(|p| p.child)
                    .all(|t| t.loop_generation() == 0)
            );
        }
    }

    #[test]
    fn spline_target_factory_end_retires_pending_owner_and_rejects_due_items() {
        for kind in [2] {
            let mut file = spline_factory_file(1, 1, 1, 2, 3);
            file.binders[0].life = 30;
            file.binders[0].binder_type = kind;
            file.timelines[0].clips.push(AvfxTimelineClip {
                clip_type: Some(AvfxTimelineClipType::End),
                ..Default::default()
            });
            file.timelines[0].clip_count = 1;
            let mut end = file.timelines[0].items[0];
            end.emitter_index = -1;
            end.clip_index = 0;
            file.timelines[0].items.insert(0, end);
            let mut value = spline_playback(
                &file,
                &[linear_target_source(10.0), linear_target_source(20.0)],
            );
            step(&mut value, 0.0);
            let state = value.state.as_ref().unwrap();
            assert!(state.document_ended);
            assert!(state.scheduler_ordinary[0].retired());
            assert!(state.roots.is_empty());
            assert!(quads(&value).is_empty());
            assert!(
                state
                    .timeline_parents
                    .iter()
                    .all(|p| p.binder_lifecycle().unwrap().retired())
            );
            assert!(state.timeline_parents[0].child.is_none());
            assert_eq!(
                state.timeline_parents[1].child.unwrap().consumed_mask(),
                u32::MAX
            );
            for delta in [2.0, 0.0, 0.0] {
                step(&mut value, delta);
                assert!(quads(&value).is_empty());
            }
            assert_eq!(
                scheduler_registered_children(&value.state.as_ref().unwrap().timeline_parents, 0),
                0
            );
        }
    }

    #[test]
    #[ignore = "CPU: requires original spline-target-factory observations"]
    fn compare_original_spline_factories_with_owned_playback_construction() {
        use serde_json::{Value, json};
        let folder =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target/weapon-vfx-audit");
        let original: Value = serde_json::from_slice(
            &std::fs::read(folder.join("spline-target-factory-client-probe.json")).unwrap(),
        )
        .unwrap();
        let (mut compared, mut excluded, mut objects) = (0usize, 0usize, 0usize);
        let matrix_bits = |m: VfxBinderMatrix| {
            m.basis
                .into_iter()
                .flatten()
                .chain(m.position)
                .map(f32::to_bits)
                .collect::<Vec<_>>()
        };
        let snapshot = |p: &SplineRootState, inner: Option<Value>| {
            let lifecycle = p.instance.lifecycle;
            let clock = lifecycle.clock;
            let state = &p.instance.state;
            json!({"targets":p.target_indices,"flags":lifecycle.raw_flags(),"lifeEnabled":lifecycle.life_limit_enabled,"initialized":p.instance.initialized,
                "clocks": ([clock.local_age,clock.total_age,lifecycle.scaled_delta,clock.previous_age,clock.nominal_life].map(f32::to_bits)),
                "life":[clock.nominal_life.to_bits()],"delay":[clock.delay.to_bits()],
                "main":matrix_bits(state.common.matrix),"auxiliary":matrix_bits(state.common.auxiliary_matrix),"scale":state.common.scale.map(f32::to_bits),
                "offsets":state.controls().iter().flat_map(|p|p.offset.map(f32::to_bits)).collect::<Vec<_>>(),"parameters":(*state.controls()).map(|p|p.parameter.to_bits()),
                "knots":state.path().knots().iter().map(|p|json!({"parameter":p.parameter.to_bits(),"position":p.position.map(f32::to_bits)})).collect::<Vec<_>>(),"inner":inner})
        };
        for (ordinal, case) in original["cases"].as_array().unwrap().iter().enumerate() {
            let owner = case["ownerKind"].as_u64().unwrap();
            let start = case["startMode"].as_u64().unwrap() as i32;
            let goal = case["goalMode"].as_u64().unwrap() as i32;
            let count = case["targetCount"].as_i64().unwrap().max(0) as usize;
            let expected_children = case["afterFactory"]["children"].as_array().unwrap();
            let requested = match (start & 3, goal & 3) {
                (0, 0) => 1,
                (0, 1) | (1, 0) => count,
                (1, 1) => count * count.saturating_sub(1),
                _ => 0,
            };
            if case["retired"] == false
                && (expected_children.len() != requested
                    || (case["querySuccessMask"] == 3
                        && expected_children
                            .iter()
                            .any(|p| p["initialized"] == true && p["inner"].is_null())))
            {
                excluded += 1;
                continue;
            }
            let mut file = spline_factory_file(
                owner,
                start,
                goal,
                case["generateDelay"].as_i64().unwrap() as i32,
                case["mask"].as_u64().unwrap(),
            );
            file.timelines[0].items[0].end_time = 30;
            file.emitters[0].particle_items.clear();
            file.emitters[0].emitter_items.clear();
            let success = case["querySuccessMask"].as_u64().unwrap();
            let source = |x| {
                let mut source = linear_target_source(x);
                source
                    .targets
                    .retain(|t| (t.id == 4 && success & 1 != 0) || (t.id == 7 && success & 2 != 0));
                source
            };
            let mode = if case["trigMode"] == 0 {
                super::super::VfxClientTrigMode::Sse2
            } else {
                super::super::VfxClientTrigMode::AvxFma
            };
            let runtime = VfxRuntime::new(&file)
                .with_binder_target_snapshot(&source(100.0).targets)
                .unwrap()
                .with_binder_target_objects(
                    &(0..count)
                        .map(|i| source(i as f32 * 10.0))
                        .collect::<Vec<_>>(),
                )
                .unwrap()
                .with_client_binder_random_state(
                    super::super::VfxClientRandomState::from_words(std::array::from_fn(|i| {
                        case["seed"][i].as_u64().unwrap() as u32
                    })),
                    mode,
                );
            let age = f32::from_bits(case["inputAge"].as_u64().unwrap() as u32);
            let mut children = Vec::new();
            if owner == 1 {
                let (mut roots, mut parents, mut loops, mut events) =
                    (Vec::new(), Vec::new(), Vec::new(), Vec::new());
                stage_timeline(
                    &runtime,
                    &HashSet::new(),
                    &file.timelines[0],
                    0,
                    0.0,
                    Some(0),
                    true,
                    false,
                    (0, -1),
                    false,
                    true,
                    &mut roots,
                    &mut parents,
                    &mut loops,
                    &mut events,
                )
                .unwrap();
                let created = construct_scheduler_definition(&runtime, &parents[0], age).unwrap();
                objects += created.len();
                if case["retired"] == false {
                    let core = super::super::scheduler_ordinary::SchedulerOrdinaryState::new(
                        &file.schedulers[0],
                    );
                    for (index, parent) in created.into_iter().enumerate() {
                        install_scheduler_definition(
                            parent,
                            index,
                            &core,
                            &roots,
                            &mut parents,
                            None,
                        );
                        let parent = &parents[index];
                        let inner=parent.child.map(|child|json!({"flags":child.raw_flags(),"clocks": ([child.clock.local_age,child.clock.total_age,0.0,child.clock.previous_age,child.clock.nominal_life].map(f32::to_bits)),"life":[child.clock.nominal_life.to_bits()]}));
                        children.push(snapshot(parent.spline.as_ref().unwrap(), inner));
                    }
                }
            } else {
                let mut staged = StagedPlayback::new(&runtime, &HashSet::new()).unwrap();
                let template = staged.timeline_parents[0].templates[0].clone();
                let mut born = Vec::new();
                staged
                    .instances
                    .control_roots(&file, |preparation| {
                        for plan in item_factory_births(&runtime, 0) {
                            let mut root = template.clone();
                            root.linear_birth = plan.linear;
                            root.point_birth = None;
                            root.life = 30.0;
                            let index =
                                preparation.add_binder_root(root.index, root.life, root.seed)?;
                            root.construct_binder(&runtime, 0, age, 0.0, index, preparation)?;
                            objects += 1;
                            if case["retired"] == true {
                                preparation.destroy_root(index)?;
                            } else {
                                born.push((index, root));
                            }
                        }
                        Ok(())
                    })
                    .unwrap();
                for (index, root) in born {
                    let common = staged.instances.common_tree_states(index);
                    let inner=common.first().map(|c|json!({"flags":c.flags,"age":c.age.to_bits(),"total":c.total.to_bits(),"delta":c.delta.to_bits()}));
                    children.push(snapshot(root.spline_binder.as_ref().unwrap(), inner));
                }
            }
            let mut expected = case["afterFactory"].clone();
            for field in [
                "countGetters",
                "allocatorFunctionCalls",
                "tlsGetterCalls",
                "queryTargets",
            ] {
                expected.as_object_mut().unwrap().remove(field);
            }
            for p in expected["children"].as_array_mut().unwrap() {
                if let Some(inner) = p["inner"].as_object_mut() {
                    inner.remove("main");
                    if owner == 0 {
                        let clock = inner.remove("clocks").unwrap();
                        inner.remove("life");
                        inner.insert("age".into(), clock[0].clone());
                        inner.insert("total".into(), clock[1].clone());
                        inner.insert("delta".into(), clock[2].clone());
                    }
                }
            }
            let occupancy =
                children.len() + children.iter().filter(|p| !p["inner"].is_null()).count();
            let actual = json!({"parentFlags":if case["retired"]==true {0x40001u32}else{0x3f000001u32|((children.len() as u32)<<9)},"freeCount":8-occupancy,"children":children,"randomState":runtime.client_binder_random_state().unwrap().words()});
            assert_eq!(actual, expected, "owned Spline factory case {ordinal}");
            compared += 1;
        }
        std::fs::write(folder.join("spline-playback-factory-rust-comparison.json"),serde_json::to_vec_pretty(&json!({"cases":compared,"capacityCasesExcluded":excluded,"constructedSplineObjects":objects,"differences":0,"productionOwnedFactoryBoundariesCompared":true,"scope":"Actual production Scheduler/Item Spline constructors, persistent instances, registry attachment, numerical caches and shared explicit random snapshot versus original factories. All parent clocks/flags/matrices/controls/knots; Scheduler child clocks/life/flags and Item child age/total/delta/flags compared. Original artificial capacity8 exhaustion excluded here and covered by previous numerical/oracle comparison. Query/getter counters and original child stored matrix omitted; Item previous/life not exposed by trace. No complete child resources/phases, shared ordering of every client RNG consumer, live host, GPU or client pixels."})).unwrap()).unwrap();
    }

    #[test]
    fn spline_empty_timeline_death_retires_parent_before_next_time_reclaim() {
        let mut file = spline_factory_file(1, 0, 0, 0, 3);
        file.timelines[0].items.clear();
        let mut value = spline_playback(&file, &[]);
        let after_constructor = value.client_binder_random_state();
        step(&mut value, 0.0);
        step(&mut value, 0.5);
        step(&mut value, 2.0);
        let parent = &value.state.as_ref().unwrap().timeline_parents[0];
        let child = parent.child.unwrap();
        // Original joint probe: child clamps local age to 1, keeps total 2.5,
        // and remains registered until the following Common Time walk.
        assert!(child.retired());
        assert_eq!((child.clock.local_age, child.clock.total_age), (1.0, 2.5));
        assert!(!parent.binder_lifecycle().unwrap().retired());
        assert_eq!(parent.binder_lifecycle().unwrap().registered_children(), 1);
        step(&mut value, 0.0);
        let parent = &value.state.as_ref().unwrap().timeline_parents[0];
        assert!(parent.child.is_none());
        assert!(parent.binder_lifecycle().unwrap().retired());
        assert_eq!(parent.binder_lifecycle().unwrap().clock.local_age, 2.5);
        step(&mut value, 3.0);
        assert!(value.state.as_ref().unwrap().timeline_parents.is_empty());
        assert_eq!(value.client_binder_random_state(), after_constructor);
    }

    #[test]
    fn spline_empty_looping_timeline_keeps_parent_and_initial_random_snapshot() {
        let mut file = spline_factory_file(1, 0, 0, 0, 3);
        file.timelines[0].items.clear();
        file.timelines[0].loop_end = 3;
        let mut value = spline_playback(&file, &[]);
        let after_constructor = value.client_binder_random_state();
        for delta in [0.0, 0.5, 2.0, 0.0, 3.0, 2.0, 0.0] {
            step(&mut value, delta);
        }
        let parent = &value.state.as_ref().unwrap().timeline_parents[0];
        let child = parent.child.unwrap();
        assert!(!parent.binder_lifecycle().unwrap().retired());
        assert_eq!(parent.binder_lifecycle().unwrap().clock.local_age, 7.5);
        // Original Timeline loop-reset callback preserves accumulated time.
        assert_eq!((child.clock.local_age, child.clock.total_age), (1.5, 7.5));
        assert_eq!(child.loop_generation(), 2);
        assert_eq!(parent.binder_lifecycle().unwrap().registered_children(), 1);
        assert_eq!(value.client_binder_random_state(), after_constructor);
    }

