    fn compare_spline_real_child_with_owned_playback(connected: bool, golden: bool) {
        use serde_json::{Value, json};
        let folder =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target/weapon-vfx-audit");
        let prefix = if connected {
            "spline-animated-child"
        } else {
            "spline-child-lifecycle"
        };
        let original: Value = if golden {
            serde_json::from_str(include_str!("fixtures/spline_animated_child_golden.json"))
                .unwrap()
        } else {
            serde_json::from_slice(
                &std::fs::read(folder.join(format!("{prefix}-client-probe.json"))).unwrap(),
            )
            .unwrap()
        };
        assert_eq!(
            original["cases"].as_array().unwrap().len(),
            if golden { 2 } else { 6912 }
        );
        fn clock(
            flags: u32,
            life_enabled: bool,
            c: super::super::VfxBinderBirthClock,
            delta: f32,
        ) -> Value {
            json!({"flags":flags,"lifeEnabled":life_enabled,"clocks":([c.local_age,c.total_age,delta,c.previous_age,c.nominal_life].map(f32::to_bits)),"life":[c.nominal_life.to_bits()]})
        }
        fn snapshot(value: &VfxPlayback, connected: bool) -> Value {
            let mut occupancy = 0;
            let parents = value.state.as_ref().unwrap().timeline_parents.iter().filter(|p| p.spline.is_some() && !p.retired_empty_before_time).map(|p| {
                occupancy += 1 + usize::from(p.child.is_some());
                let s = p.spline.as_ref().unwrap();
                let life = s.instance.lifecycle;
                let matrix = s.instance.state.common.matrix;
                let child = p.child.map(|c| json!({"clock":clock(c.raw_flags(),c.life_limit_enabled(),c.clock,c.scaled_delta),"consumed":c.consumed_mask(),"active":c.dispatch_active()}));
                json!({"targets":s.target_indices,"clock":clock(life.raw_flags(),life.life_limit_enabled,life.clock,life.scaled_delta),"initialized":s.instance.initialized,"delay":[life.clock.delay.to_bits()],"main":matrix.basis.into_iter().flatten().chain(matrix.position).map(f32::to_bits).collect::<Vec<_>>(),"child":child})
            }).collect::<Vec<_>>();
            let mut result = json!({"freeCount":8-occupancy,"parents":parents,"randomState":value.client_binder_random_state().unwrap().words()});
            if connected {
                let objects = value
                    .state
                    .as_ref()
                    .unwrap()
                    .timeline_parents
                    .iter()
                    .filter(|p| !p.retired_empty_before_time)
                    .filter_map(|p| p.spline.clone())
                    .collect::<Vec<_>>();
                result["curveState"] = snapshot_spline_curve_state(&value.runtime, &objects);
            }
            result
        }
        use super::super::binder_curves::tests::{canonicalize, scoped_expected};
        let scoped = |mut v: Value| {
            if connected {
                let mut curves = scoped_expected(v["curveState"].take());
                curves["factory"]
                    .as_object_mut()
                    .unwrap()
                    .remove("queryTargets");
                v["curveState"] = curves;
            }
            v
        };
        let mut boundaries = 0;
        for (ordinal, case) in original["cases"].as_array().unwrap().iter().enumerate() {
            let mut file = spline_factory_file(
                1,
                case["startMode"].as_i64().unwrap() as i32,
                case["goalMode"].as_i64().unwrap() as i32,
                case["generateDelay"].as_i64().unwrap() as i32,
                3,
            );
            if connected {
                file.binders[0] = super::super::binder_curves::tests::authored_binder(case);
                file.binders[0].properties_1.as_mut().unwrap().ring_enabled = true;
                file.binders[0].properties_2.as_mut().unwrap().ring_enabled = true;
            }
            file.binders[0].life = case["binderLife"].as_i64().unwrap() as i32;
            let mut disabled = file.timelines[0].items[0];
            disabled.enabled = false;
            disabled.start_time = 0;
            disabled.end_time = 8;
            file.timelines[0].items.clear();
            match case["timelineKind"].as_i64().unwrap() {
                0 => {}
                1 => file.timelines[0].items.push(disabled),
                2 => file.timelines[0].loop_end = 3,
                _ => unreachable!(),
            }
            let source = |x: f32, success: u64| {
                let mut s = linear_target_source(x);
                s.targets
                    .retain(|t| (t.id == 4 && success & 1 != 0) || (t.id == 7 && success & 2 != 0));
                s
            };
            let count = case["targetCount"].as_u64().unwrap() as usize;
            let initial = case["initialSuccessMask"].as_u64().unwrap();
            let mode = if case["trigMode"] == 0 {
                super::super::VfxClientTrigMode::Sse2
            } else {
                super::super::VfxClientTrigMode::AvxFma
            };
            let mut runtime = VfxRuntime::new(&file)
                .with_binder_target_snapshot(&source(100.0, initial).targets)
                .unwrap()
                .with_binder_target_objects(
                    &(0..count)
                        .map(|i| source(i as f32 * 10.0, initial))
                        .collect::<Vec<_>>(),
                )
                .unwrap()
                .with_client_binder_random_state(
                    super::super::VfxClientRandomState::from_words(std::array::from_fn(|i| {
                        case["seed"][i].as_u64().unwrap() as u32
                    })),
                    mode,
                );
            if connected {
                runtime = runtime.with_client_binder_curve_defaults(
                    super::super::VfxClientBinderCurveDefaults {
                        empty_scalar_random_type: case["emptyRandomType"].as_u64().unwrap() as u32,
                        vector_random_fallback: [f32::from_bits(
                            case["fallback"].as_u64().unwrap() as u32
                        ); 3],
                    },
                );
            }
            let mut value = VfxPlayback::new(runtime);
            assert_eq!(value.fallback_reason(), None, "case {ordinal}");
            let mut expected = scoped(case["afterFactory"].clone());
            let mut actual = snapshot(&value, connected);
            canonicalize(&mut actual);
            canonicalize(&mut expected);
            assert_eq!(actual, expected, "case {ordinal} factory");
            boundaries += 1;
            for (tick, input) in case["inputs"].as_array().unwrap().iter().enumerate() {
                if tick >= 2 {
                    value.runtime.binder_targets = Some(source(100.0, 3).targets);
                    value.runtime.binder_target_objects =
                        Some((0..count).map(|i| source(i as f32 * 10.0, 3)).collect());
                }
                if case["endAt"] == tick as i64 {
                    for p in &mut value.state.as_mut().unwrap().timeline_parents {
                        p.ended = true;
                        if let Some(life) = p.binder_lifecycle_mut() {
                            life.retire();
                        }
                        if let Some(child) = &mut p.child {
                            child.retire();
                        }
                    }
                }
                let delta = f32::from_bits(input["delta"].as_u64().unwrap() as u32);
                value
                    .state
                    .as_mut()
                    .unwrap()
                    .advance(&value.runtime, delta)
                    .unwrap();
                let mut actual = snapshot(&value, connected);
                let mut expected = scoped(input["afterPrepare"].clone());
                canonicalize(&mut actual);
                canonicalize(&mut expected);
                assert_eq!(actual, expected, "case {ordinal} input {tick}");
                boundaries += 1;
            }
        }
        if !golden {
            std::fs::write(folder.join(format!("{prefix}-rust-comparison.json")),serde_json::to_vec_pretty(&json!({"cases":6912,"boundaries":boundaries,"differences":0,"rawAnimatedCurvesAndFirst":connected,"scope":"Actual production Spline owned Scheduler-child lifecycle and real native Timeline Time/Prepare/loop/retirement and pool deletion. Factory plus seven full input boundaries compared, including numerical parent matrix and explicit shared RNG, and remaining pool occupancy. Empty/disabled Timeline definitions, queries, parent phase routing and TLS/CRT inputs controlled. Rust normal Numeric runs but native Numeric/REST, Emitter resources, full Document, global RNG, live host/GPU/client pixels are not proved. Raw animated curves and First are compared only when indicated by the mode field; the historical probe uses controlled constant curves and zero First. Finite/Inf bitwise; NaN classification."})).unwrap()).unwrap();
        }
    }

    #[test]
    fn linear_target_factory_single_and_cartesian_branches_keep_delays_and_direction() {
        for kind in [1, 4] {
            for (start, goal, indices, delays, positions) in [
                (4, 4, vec![[-1, -1]], vec![0.0], vec![101.5]),
                (
                    4,
                    5,
                    vec![[-1, 0], [-1, 1]],
                    vec![0.0, 2.0],
                    vec![56.5, 61.5],
                ),
                (
                    5,
                    4,
                    vec![[0, -1], [1, -1]],
                    vec![0.0, 2.0],
                    vec![56.5, 61.5],
                ),
                (5, 5, vec![[0, 1], [1, 0]], vec![2.0, 0.0], vec![16.5, 16.5]),
            ] {
                let mut file = linear_scheduler_file(start, goal, 2);
                file.binders[0].binder_type = kind;
                let mut value = linear_target_playback(
                    &file,
                    &[linear_target_source(10.0), linear_target_source(20.0)],
                );
                let state = value.state.as_ref().unwrap();
                assert_eq!(
                    state
                        .timeline_parents
                        .iter()
                        .map(|p| p.linear.as_ref().unwrap().target_indices)
                        .collect::<Vec<_>>(),
                    indices
                );
                assert_eq!(
                    state
                        .timeline_parents
                        .iter()
                        .map(|p| p.linear.as_ref().unwrap().instance.lifecycle.clock.delay)
                        .collect::<Vec<_>>(),
                    delays
                );
                assert_eq!(state.scheduler_ordinary[0].flags & 0x1ff, 0);
                assert_eq!(
                    state.scheduler_ordinary[0].flags >> 9 & 0x1ff,
                    indices.len() as u32
                );
                step(&mut value, 0.0);
                assert_eq!(quads(&value).len(), 1);
                step(&mut value, 2.0);
                let state = value.state.as_ref().unwrap();
                assert_eq!(quads(&value).len(), indices.len());
                for (parent, expected) in state.timeline_parents.iter().zip(positions) {
                    near(parent.base.position[0], expected);
                }
                for root in &state.roots {
                    let parent = &state.timeline_parents[root.timeline_parent.unwrap().0];
                    assert_eq!(root.direction, parent.direction);
                    assert_ne!(root.direction, [0.0; 3]);
                }
            }
        }
    }

    #[test]
    fn linear_target_factory_empty_lists_consume_without_point_caster_fallback() {
        for (start, goal, sources) in [
            (0, 1, vec![]),
            (1, 0, vec![]),
            (1, 1, vec![]),
            (1, 1, vec![linear_target_source(10.0)]),
        ] {
            let file = linear_scheduler_file(start, goal, 2);
            let mut value = linear_target_playback(&file, &sources);
            step(&mut value, 0.0);
            let state = value.state.as_ref().unwrap();
            assert!(state.timeline_parents.is_empty());
            assert_eq!(state.scheduler_ordinary[0].consumed, u32::MAX);
            assert_eq!(state.scheduler_ordinary[0].flags & 0x3ffff, 0);
            value
                .advance_with_binder_target_objects(
                    1.0 / 30.0,
                    &[linear_target_source(20.0), linear_target_source(30.0)],
                )
                .unwrap();
            assert!(value.state.as_ref().unwrap().timeline_parents.is_empty());
            assert!(quads(&value).is_empty());
        }
    }

    #[test]
    fn linear_target_factory_due_input_uses_current_count_and_preserves_overshoot() {
        let mut file = linear_scheduler_file(0, 1, 65533);
        file.schedulers[0].items[0].start_time = 3;
        let mut value = linear_target_playback(&file, &[]);
        step(&mut value, 0.0);
        value
            .advance_with_binder_target_objects(
                4.5 / 30.0,
                &[linear_target_source(10.0), linear_target_source(20.0)],
            )
            .unwrap();
        let state = value.state.as_ref().unwrap();
        assert_eq!(state.timeline_parents.len(), 2);
        for (index, parent) in state.timeline_parents.iter().enumerate() {
            let linear = &parent.linear.as_ref().unwrap().instance;
            assert_eq!(linear.lifecycle.clock.delay, -3.0 * index as f32);
            assert_eq!(linear.lifecycle.clock.total_age, 1.5);
            assert_eq!(parent.child.unwrap().clock.total_age, 1.5);
        }
        assert_eq!(quads(&value).len(), 2);
        assert_eq!(state.scheduler_ordinary[0].consumed, u32::MAX);
    }

    #[test]
    fn linear_target_factory_missing_ordinals_keep_cache_and_do_not_retry_timeline_birth() {
        let file = linear_scheduler_file(1, 1, 2);
        let mut value = linear_target_playback(
            &file,
            &[
                linear_target_source(10.0),
                linear_target_source(20.0),
                linear_target_source(30.0),
            ],
        );
        step(&mut value, 0.0);
        value
            .advance_with_binder_target_objects(
                2.0 / 30.0,
                &[linear_target_source(11.0), linear_target_source(22.0)],
            )
            .unwrap();
        let state = value.state.as_ref().unwrap();
        assert_eq!(
            state.timeline_parents[4]
                .linear
                .as_ref()
                .unwrap()
                .instance
                .state
                .targets
                .map(|t| t.position[0]),
            [30.0, 14.0]
        );
        assert!(state.timeline_parents[5].child.is_none());
        value
            .advance_with_binder_target_objects(2.0 / 30.0, &[linear_target_source(12.0)])
            .unwrap();
        let state = value.state.as_ref().unwrap();
        assert_eq!(
            state.timeline_parents[0]
                .linear
                .as_ref()
                .unwrap()
                .instance
                .state
                .targets
                .map(|t| t.position[0]),
            [12.0, 25.0]
        );
        for index in [1, 3, 5] {
            assert!(state.timeline_parents[index].child.is_none());
        }
        value
            .advance_with_binder_target_objects(
                0.0,
                &[
                    linear_target_source(13.0),
                    linear_target_source(23.0),
                    linear_target_source(33.0),
                ],
            )
            .unwrap();
        for index in [1, 3, 5] {
            assert!(
                value.state.as_ref().unwrap().timeline_parents[index]
                    .child
                    .is_none()
            );
        }
        assert_eq!(value.state.as_ref().unwrap().timeline_parents.len(), 6);
    }

    #[test]
    fn linear_target_factory_pending_life_gate_and_fade_reach_delayed_timeline() {
        let mut file = linear_scheduler_file(0, 1, 2);
        file.binders[0].life = 0;
        let mut value = linear_target_playback(
            &file,
            &[linear_target_source(10.0), linear_target_source(20.0)],
        );
        step(&mut value, 0.0);
        assert!(value.configure_scheduler_fade(0, 4, 1, false).unwrap());
        step(&mut value, 0.5);
        step(&mut value, 1.5);
        let state = value.state.as_ref().unwrap();
        let parent = &state.timeline_parents[1];
        let linear = parent.linear.as_ref().unwrap().instance.lifecycle;
        let child = parent.child.unwrap();
        assert!(!linear.retired());
        assert_eq!(linear.raw_flags() & 0x1ff, 0);
        assert!(linear.life_limit_enabled);
        assert_eq!(linear.numeric.fade.age, 2.0);
        assert_eq!(child.numeric.fade.duration, 4.0);
        assert_eq!(child.numeric.fade.age, 0.5);
        assert_eq!(child.clock.local_age, 0.0);
        step(&mut value, 1.0);
        assert!(
            value.state.as_ref().unwrap().timeline_parents[1]
                .linear
                .as_ref()
                .unwrap()
                .instance
                .lifecycle
                .retired()
        );
    }

