    #[test]
    fn linear_target_factory_rest_replaces_only_oldest_ready_parent() {
        let mut file = linear_scheduler_file(1, 1, 0);
        let mut rest = file.timelines[0].items[0];
        rest.emitter_index = -1;
        rest.clip_index = 0;
        file.timelines.push(AvfxTimeline {
            binder_index: -1,
            items: vec![rest],
            clips: vec![AvfxTimelineClip {
                clip_type: Some(AvfxTimelineClipType::Reset),
                raw_ints: Some([0, 1, 0, 0]),
                raw_floats: Some([-1.0, 0.0, 0.0, 0.0]),
                ..Default::default()
            }],
            ..Default::default()
        });
        file.schedulers[0].triggers = vec![AvfxSchedulerItem {
            enabled: true,
            start_time: 0,
            timeline_index: 1,
        }];
        let mut value = linear_target_playback(
            &file,
            &[linear_target_source(10.0), linear_target_source(20.0)],
        );
        step(&mut value, 0.0);
        let ids = [
            value.state.as_ref().unwrap().instances.root_id(0),
            value.state.as_ref().unwrap().instances.root_id(1),
        ];
        assert!(value.trigger_document(0, 1).unwrap());
        value
            .advance_with_binder_target_objects(
                0.0,
                &[
                    linear_target_source(11.0),
                    linear_target_source(22.0),
                    linear_target_source(33.0),
                ],
            )
            .unwrap();
        let state = value.state.as_ref().unwrap();
        let live = state
            .timeline_parents
            .iter()
            .filter(|p| p.linear.is_some())
            .collect::<Vec<_>>();
        assert_eq!(live.len(), 7);
        assert_eq!(
            live.iter()
                .min_by_key(|p| p.prepare_order)
                .unwrap()
                .linear
                .as_ref()
                .unwrap()
                .target_indices,
            [1, 0]
        );
        let new_ids = (0..state.roots.len())
            .filter_map(|i| state.instances.root_id(i))
            .collect::<Vec<_>>();
        assert!(!new_ids.contains(&ids[0].unwrap()));
        assert!(new_ids.contains(&ids[1].unwrap()));
        assert_eq!(quads(&value).len(), 7);
    }

    #[test]
    fn linear_target_factory_unused_modes_skip_curves_and_missing_sources() {
        for start in 0..8 {
            for goal in 0..8 {
                if start & 3 < 2 && goal & 3 < 2 {
                    continue;
                }
                let mut file = linear_scheduler_file(start, goal, 2);
                file.binders[0].data = None;
                file.binders[0]
                    .properties_start
                    .as_mut()
                    .unwrap()
                    .bind_target_point_type = 99;
                let mut value = VfxPlayback::new(
                    VfxRuntime::new(&file)
                        .with_binder_target_snapshot(&[])
                        .unwrap(),
                );
                assert_eq!(value.fallback_reason(), None);
                step(&mut value, 0.0);
                let state = value.state.as_ref().unwrap();
                assert!(state.timeline_parents.is_empty());
                assert_eq!(state.scheduler_ordinary[0].flags & 0x3ffff, 0);
                assert_eq!(state.scheduler_ordinary[0].consumed, u32::MAX);
            }
        }
    }

