    fn linear_item_factory_retains_ordinals_caches_and_failed_birth_gate() {
        let file = linear_item_file(1, 1, 2);
        let mut value = linear_target_playback(
            &file,
            &[
                linear_target_source(10.0),
                linear_target_source(20.0),
                linear_target_source(30.0),
            ],
        );
        step(&mut value, 0.0);
        value
            .advance_with_binder_target_objects(
                2.0 / 30.0,
                &[linear_target_source(11.0), linear_target_source(22.0)],
            )
            .unwrap();
        let state = value.state.as_ref().unwrap();
        let missing_start = &state.roots[4]
            .linear_binder
            .as_ref()
            .unwrap()
            .instance
            .state;
        assert_eq!(missing_start.targets.map(|t| t.position[0]), [30.0, 14.0]);
        assert_eq!(
            state.roots[0]
                .linear_binder
                .as_ref()
                .unwrap()
                .instance
                .state
                .targets
                .map(|t| t.position[0]),
            [11.0, 25.0]
        );
        assert_eq!(
            state.instances.root_id(5),
            None,
            "missing start at delayed birth"
        );
        value
            .advance_with_binder_target_objects(2.0 / 30.0, &[linear_target_source(12.0)])
            .unwrap();
        let state = value.state.as_ref().unwrap();
        assert_eq!(
            state.roots[0]
                .linear_binder
                .as_ref()
                .unwrap()
                .instance
                .state
                .targets
                .map(|t| t.position[0]),
            [12.0, 25.0]
        );
        assert_eq!(
            state.instances.root_id(1),
            None,
            "missing goal at delayed birth"
        );
        value
            .advance_with_binder_target_objects(
                0.0,
                &[
                    linear_target_source(13.0),
                    linear_target_source(23.0),
                    linear_target_source(33.0),
                ],
            )
            .unwrap();
        let state = value.state.as_ref().unwrap();
        for i in [1, 3, 5] {
            assert!(
                state.roots[i]
                    .linear_binder
                    .as_ref()
                    .unwrap()
                    .instance
                    .initialized
            );
            assert_eq!(state.instances.root_id(i), None, "no delayed birth retry");
        }
        assert_eq!(state.roots.len(), 6);
    }

