    #[test]
    fn linear_item_factory_pending_birth_defers_life_check_and_consumes_gate_on_failure() {
        for query_success in [false, true] {
            let mut file = linear_item_file(0, 1, 5);
            file.binders[0].life = 0;
            let mut source = linear_target_source(20.0);
            if !query_success {
                source.targets.retain(|t| t.id != 7);
            }
            let mut value = linear_target_playback(&file, &[linear_target_source(10.0), source]);
            step(&mut value, 0.0);
            let waiting = &value.state.as_ref().unwrap().roots[1]
                .linear_binder
                .as_ref()
                .unwrap()
                .instance;
            assert_eq!(waiting.lifecycle.raw_flags() & 0x1ff, 1);
            assert!(!waiting.lifecycle.life_limit_enabled);
            step(&mut value, 5.0);
            let root = value
                .state
                .as_ref()
                .unwrap()
                .roots
                .iter()
                .find(|r| r.linear_binder.as_ref().unwrap().target_indices == [-1, 1])
                .unwrap();
            let born = &root.linear_binder.as_ref().unwrap().instance;
            assert!(born.initialized);
            assert!(!born.lifecycle.retired());
            assert!(born.lifecycle.life_limit_enabled);
            assert_eq!(born.lifecycle.raw_flags() & 0x1ff, 0);
            assert_eq!(
                born.lifecycle.clock.local_age.to_bits(),
                (-0.0f32).to_bits()
            );
            assert_eq!(
                born.lifecycle.registered_children(),
                u16::from(query_success)
            );
            step(&mut value, 1.0);
            assert!(
                value
                    .state
                    .as_ref()
                    .unwrap()
                    .roots
                    .iter()
                    .filter_map(|r| r.linear_binder.as_ref())
                    .all(|r| r.instance.lifecycle.retired())
            );
        }
    }

