    #[test]
    #[ignore = "CPU: requires probe-linear-item-factory.py original Item Linear factory observations"]
    fn compare_original_linear_item_factory_with_owned_construction() {
        use serde_json::{Value, json};
        let output =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target/weapon-vfx-audit");
        let original: Value = serde_json::from_slice(
            &std::fs::read(output.join("linear-item-factory-client-probe.json")).unwrap(),
        )
        .unwrap();
        let (mut compared, mut excluded, mut objects) = (0, 0, 0);
        for (ordinal, case) in original["cases"].as_array().unwrap().iter().enumerate() {
            let start = case["startMode"].as_i64().unwrap() as i32;
            let goal = case["goalMode"].as_i64().unwrap() as i32;
            let count = case["targetCount"].as_i64().unwrap().max(0) as usize;
            let expected_children = case["afterFactory"]["children"].as_array().unwrap();
            let requested = match (start & 3, goal & 3) {
                (0, 0) => 1,
                (0, 1) | (1, 0) => count,
                (1, 1) => count * count.saturating_sub(1),
                _ => 0,
            };
            if case["retired"] == false
                && (expected_children.len() != requested
                    || (case["querySuccessMask"] == 3
                        && expected_children
                            .iter()
                            .any(|n| n["initialized"] == true && n["inner"].is_null())))
            {
                excluded += 1;
                continue;
            }
            let mut file =
                linear_item_file(start, goal, case["generateDelay"].as_i64().unwrap() as i32);
            file.binders[0].binder_type = case["binderType"].as_u64().unwrap() as u32;
            file.binders[0].life = -1;
            file.timelines[0].items[0].end_time = 30;
            file.emitters[0].particle_items.clear();
            file.emitters[0].emitter_items.clear();
            let mut source = linear_target_source(0.0);
            let success = case["querySuccessMask"].as_u64().unwrap();
            source
                .targets
                .retain(|t| (t.id == 4 && success & 1 != 0) || (t.id == 7 && success & 2 != 0));
            let runtime = VfxRuntime::new(&file)
                .with_binder_target_snapshot(&source.targets)
                .unwrap()
                .with_binder_target_objects(&vec![source; count])
                .unwrap();
            let mut state = StagedPlayback::new(&runtime, &HashSet::new()).unwrap();
            let template = state.timeline_parents[0].templates[0].clone();
            let age = f32::from_bits(case["inputAge"].as_u64().unwrap() as u32);
            let mut roots = Vec::new();
            state
                .instances
                .control_roots(&file, |preparation| {
                    for plan in item_factory_births(&runtime, 0) {
                        let mut root = template.clone();
                        root.point_birth = plan.point;
                        root.linear_birth = plan.linear;
                        root.life = 30.0;
                        let index =
                            preparation.add_binder_root(root.index, root.life, root.seed)?;
                        root.construct_binder(&runtime, 0, age, 0.0, index, preparation)?;
                        if case["retired"] == true {
                            preparation.destroy_root(index)?;
                        } else {
                            roots.push((index, root));
                        }
                    }
                    Ok(())
                })
                .unwrap();
            let mut children = Vec::new();
            for (index, root) in roots {
                let linear = root.linear_binder.as_ref().unwrap();
                let clock = linear.instance.lifecycle.clock;
                let common = state.instances.common_tree_states(index);
                let inner = common.first().map(
                    |n| json!({"age":n.age.to_bits(),"total":n.total.to_bits(),"flags":n.flags}),
                );
                children.push(json!({"targets":linear.target_indices,"clock":{"age":clock.local_age.to_bits(),"total":clock.total_age.to_bits(),"previous":clock.previous_age.to_bits(),"delay":clock.delay.to_bits(),"flags":linear.instance.lifecycle.raw_flags(),"lifeEnabled":linear.instance.lifecycle.life_limit_enabled},"initialized":linear.instance.initialized,"inner":inner}));
            }
            let occupancy =
                children.len() + children.iter().filter(|n| !n["inner"].is_null()).count();
            let flags = if case["retired"] == true {
                0x40001u32
            } else {
                0x3f000001u32
            };
            let actual = json!({"parentFlags":flags|(children.len() as u32)<<9,"children":children,"freeCount":8-occupancy});
            let mut expected = case["afterFactory"].clone();
            for field in ["countGetters", "queryTargets", "emitterCalls"] {
                expected.as_object_mut().unwrap().remove(field);
            }
            for child in expected["children"].as_array_mut().unwrap() {
                if let Some(inner) = child["inner"].as_object_mut() {
                    for field in ["previous", "life"] {
                        inner.remove(field);
                    }
                }
            }
            assert_eq!(actual, expected, "case {ordinal}");
            compared += 1;
            objects += occupancy;
        }
        std::fs::write(output.join("linear-item-factory-rust-comparison.json"), serde_json::to_vec_pretty(&json!({"cases":compared,"nativeCapacityCasesExcluded":excluded,"semanticObjects":objects,"differences":0,"productionOwnedConstructionCompared":true,"fullStagedPhasesCompared":false,"scope":"Production Item Linear/LinearAdjust expansion, selected endpoint Root/Linear constructor and actual trace Emitter construction/free versus original factory boundary. Ordered endpoint identities, complete Linear clocks/flags/gates/delay/initialized and child age/total/flags plus logical occupancy compared. Native artificial capacity8 exhaustion excluded; independent oracle covers all61440. Parent fixture/mode0, queries/matrix/curves and Emitter resources controlled. Native getter/query counts, matrices/numeric/direction and child previous/life omitted. No complete Time/Prepare/Numeric/resources/live host/shared RNG/GPU."})).unwrap()).unwrap();
    }

