    #[test]
    #[ignore = "CPU: requires probe-point-item-factory.py original Item Point factory observations"]
    fn compare_original_point_item_factory_with_owned_construction() {
        use serde_json::{Value, json};
        let output =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target/weapon-vfx-audit");
        let original: Value = serde_json::from_slice(
            &std::fs::read(output.join("point-item-factory-client-probe.json")).unwrap(),
        )
        .unwrap();
        let mut compared = 0;
        let mut excluded = 0;
        let mut objects = 0;
        for (ordinal, case) in original["cases"].as_array().unwrap().iter().enumerate() {
            let mode = case["binding"].as_i64().unwrap() as i32;
            let count = case["targetCount"].as_i64().unwrap() as i32;
            let delay = case["generateDelay"].as_i64().unwrap() as i32;
            let expected_children = case["afterFactory"]["children"].as_array().unwrap();
            let requested = match mode & 3 {
                0 => 1,
                1 => count.max(0) as usize,
                _ => 0,
            };
            if case["retired"] == false
                && (expected_children.len() != requested
                    || (case["querySuccess"] == true
                        && expected_children
                            .iter()
                            .any(|n| n["initialized"] == true && n["inner"].is_null())))
            {
                excluded += 1;
                continue;
            }
            let mut file = point_item_file(delay);
            file.binders[0].life = -1;
            file.binders[0]
                .properties_start
                .as_mut()
                .unwrap()
                .bind_point_type = mode;
            file.timelines[0].items[0].end_time = 30;
            file.emitters[0].particle_items.clear();
            file.emitters[0].emitter_items.clear();
            let mut source = target_object_source(0.0);
            if case["querySuccess"] == false {
                source.targets.clear();
            }
            let runtime = VfxRuntime::new(&file)
                .with_binder_target_snapshot(&source.targets)
                .unwrap()
                .with_binder_target_objects(&vec![source; count.max(0) as usize])
                .unwrap();
            let mut state = StagedPlayback::new(&runtime, &HashSet::new()).unwrap();
            let template = state.timeline_parents[0].templates[0].clone();
            let age = f32::from_bits(case["inputAge"].as_u64().unwrap() as u32);
            let mut roots = Vec::new();
            state
                .instances
                .control_roots(&file, |preparation| {
                    for plan in item_factory_point_births(&runtime, 0) {
                        let mut root = template.clone();
                        root.point_birth = plan;
                        root.life = 30.0;
                        let index =
                            preparation.add_binder_root(root.index, root.life, root.seed)?;
                        root.construct_binder(&runtime, 0, age, 0.0, index, preparation)?;
                        if case["retired"] == true {
                            preparation.destroy_root(index)?;
                        } else {
                            roots.push((index, root));
                        }
                    }
                    Ok(())
                })
                .unwrap();
            let mut children = Vec::new();
            for (index, root) in roots {
                let point = root.point_binder.as_ref().unwrap();
                let clock = point.instance.lifecycle.clock;
                let common = state.instances.common_tree_states(index);
                let inner = common.first().map(
                    |n| json!({"age":n.age.to_bits(),"total":n.total.to_bits(),"flags":n.flags}),
                );
                children.push(json!({"target":point.target_index,"clock":{"age":clock.local_age.to_bits(),"total":clock.total_age.to_bits(),"previous":clock.previous_age.to_bits(),"delay":clock.delay.to_bits(),"flags":point.instance.lifecycle.raw_flags(),"lifeEnabled":point.instance.lifecycle.life_limit_enabled},"initialized":point.instance.initialized,"inner":inner}));
            }
            let occupancy =
                children.len() + children.iter().filter(|n| !n["inner"].is_null()).count();
            let flags = if case["retired"] == true {
                0x40001u32
            } else {
                0x3f000001u32
            };
            let actual = json!({"parentFlags":flags|(children.len() as u32)<<9,"children":children,"freeCount":8-occupancy});
            let mut expected = case["afterFactory"].clone();
            for field in ["countGetters", "queryTargets", "emitterCalls"] {
                expected.as_object_mut().unwrap().remove(field);
            }
            for child in expected["children"].as_array_mut().unwrap() {
                if let Some(inner) = child["inner"].as_object_mut() {
                    for field in ["previous", "life", "loopStart", "loopEnd"] {
                        inner.remove(field);
                    }
                }
            }
            assert_eq!(actual, expected, "case {ordinal}");
            compared += 1;
            objects += occupancy;
        }
        std::fs::write(output.join("point-item-factory-rust-comparison.json"),serde_json::to_vec_pretty(&json!({"cases":compared,"nativeCapacityCasesExcluded":excluded,"semanticObjects":objects,"differences":0,"productionOwnedConstructionCompared":true,"fullStagedPhasesCompared":false,"scope":"Production Item Point expansion, selected target Root/Point constructor and actual trace Emitter construction/free versus original factory boundary. Ordered target identities, complete Point clocks/flags/gates/delay/initialized and child age/total/flags plus logical occupancy compared. Native artificial capacity8 exhaustion excluded; independent oracle covers all2560. Parent fixture/mode0 and query/matrix/curve/Emitter resources controlled. Native getter/query counts and child previous/life/loop clocks omitted. No complete Time/Prepare/Numeric/resources/live host/RNG/GPU."})).unwrap()).unwrap();
    }

    #[test]
    fn point_item_factory_retired_timeline_rejects_all_due_objects() {
        let mut file = point_item_file(0);
        file.timelines[0].clips.push(crate::avfx::AvfxTimelineClip {
            clip_type: Some(AvfxTimelineClipType::End),
            ..Default::default()
        });
        file.timelines[0].clip_count = 1;
        let mut end = file.timelines[0].items[0];
        end.binder_index = -1;
        end.emitter_index = -1;
        end.clip_index = 0;
        file.timelines[0].items.insert(0, end);
        let mut value = point_target_playback(
            &file,
            &[target_object_source(10.0), target_object_source(20.0)],
        );
        step(&mut value, 0.0);
        let state = value.state.as_ref().unwrap();
        assert!(state.document_ended);
        assert!(state.roots.is_empty());
        assert!(quads(&value).is_empty());
        let parent = &state.timeline_parents[0];
        assert!(parent.child.unwrap().retired());
        assert_eq!(
            parent.child.unwrap().registered_children(),
            1,
            "only the END Clip stays linked"
        );
        assert_eq!(parent.child.unwrap().consumed_mask(), u32::MAX);
    }

    #[test]
    fn point_target_factory_independent_delays_positions_and_same_input_preparation() {
        let file = point_target_file(2);
        let sources = [
            target_object_source(10.0),
            target_object_source(20.0),
            target_object_source(30.0),
        ];
        let mut value = point_target_playback(&file, &sources);
        let state = value.state.as_ref().unwrap();
        assert_eq!(state.timeline_parents.len(), 3);
        assert_eq!(state.scheduler_ordinary[0].flags & 511, 0);
        assert_eq!(state.scheduler_ordinary[0].flags >> 9 & 511, 3);
        assert_eq!(state.scheduler_ordinary[0].consumed, u32::MAX);
        assert_eq!(
            state
                .timeline_parents
                .iter()
                .filter(|p| p.child.is_some())
                .count(),
            1
        );
        assert_eq!(
            state
                .timeline_parents
                .iter()
                .map(|p| p.point.as_ref().unwrap().instance.lifecycle.clock.delay)
                .collect::<Vec<_>>(),
            vec![0.0, 2.0, 4.0]
        );
        value.advance(0.0).unwrap();
        assert_eq!(quads(&value).len(), 1);
        assert_eq!(quads(&value)[0].position[0], 10.0);
        value
            .advance_with_binder_target_objects(2.0 / 30.0, &sources)
            .unwrap();
        assert_eq!(quads(&value).len(), 2);
        value
            .advance_with_binder_target_objects(2.0 / 30.0, &sources)
            .unwrap();
        assert_eq!(
            quads(&value)
                .iter()
                .map(|p| p.position[0])
                .collect::<Vec<_>>(),
            vec![10.0, 20.0, 30.0]
        );
        let state = value.state.as_ref().unwrap();
        assert_eq!(state.roots.len(), 3);
        let ids = (0..3)
            .map(|i| state.instances.root_id(i).unwrap())
            .collect::<HashSet<_>>();
        assert_eq!(ids.len(), 3);
        for (index, p) in state.timeline_parents.iter().enumerate() {
            assert_eq!(p.scheduler_identity, (0, -1));
            assert_eq!(p.point.as_ref().unwrap().target_index, index as i32);
            assert_eq!(p.child.unwrap().consumed_mask(), u32::MAX);
            assert_eq!(p.children.len(), 1);
        }
    }

