    #[test]
    fn point_target_rest_deletes_only_oldest_ready_point_and_appends_current_list() {
        let mut file = point_target_file(0);
        let target = file.timelines[0].items[0];
        let mut rest = target;
        rest.emitter_index = -1;
        rest.clip_index = 0;
        file.timelines.push(AvfxTimeline {
            binder_index: -1,
            items: vec![rest],
            clips: vec![AvfxTimelineClip {
                clip_type: Some(AvfxTimelineClipType::Reset),
                raw_ints: Some([0, 1, 0, 0]),
                raw_floats: Some([-1.0, 0.0, 0.0, 0.0]),
                ..Default::default()
            }],
            ..Default::default()
        });
        file.schedulers[0].triggers = vec![crate::avfx::AvfxSchedulerItem {
            enabled: true,
            start_time: 0,
            timeline_index: 1,
        }];
        let mut value = point_target_playback(
            &file,
            &[
                target_object_source(10.0),
                target_object_source(20.0),
                target_object_source(30.0),
            ],
        );
        value.advance(0.0).unwrap();
        assert_eq!(quads(&value).len(), 3);
        let old = (0..3)
            .map(|i| value.state.as_ref().unwrap().instances.root_id(i).unwrap())
            .collect::<Vec<_>>();
        value.trigger_document(0, 1).unwrap();
        value
            .advance_with_binder_target_objects(0.0, &[target_object_source(70.0)])
            .unwrap();
        assert_eq!(value.fallback_reason(), None);
        let state = value.state.as_ref().unwrap();
        let ordinary = state
            .timeline_parents
            .iter()
            .filter(|p| p.scheduler_identity == (0, -1))
            .collect::<Vec<_>>();
        assert_eq!(ordinary.len(), 3);
        let mut points = ordinary
            .iter()
            .map(|p| (p.prepare_order, p.point.as_ref().unwrap().target_index))
            .collect::<Vec<_>>();
        points.sort();
        assert_eq!(
            points.iter().map(|p| p.1).collect::<Vec<_>>(),
            vec![1, 2, 0]
        );
        assert_eq!(state.roots.len(), 3);
        let ids = (0..3)
            .map(|i| state.instances.root_id(i).unwrap())
            .collect::<HashSet<_>>();
        assert!(!ids.contains(&old[0]));
        assert!(ids.contains(&old[1]));
        assert!(ids.contains(&old[2]));
        assert_eq!(state.scheduler_ordinary[0].flags >> 9 & 511, 4);
        assert!(!state.document_ended);
        assert!(!state.document_reset_pending);
    }

