    #[test]
    fn camera_factory_both_owners_create_one_child_without_target_success_or_delay() {
        for timeline in [false, true] {
            for count in [0, 1, 3] {
                let file = camera_factory_file(timeline);
                let runtime = VfxRuntime::new(&file)
                    .with_document_scale([2.0, 3.0, 4.0])
                    .unwrap()
                    .with_camera_binder_snapshot(camera_factory_input())
                    .unwrap()
                    .with_binder_target_objects(&vec![linear_target_source(100.0); count])
                    .unwrap();
                let mut value = VfxPlayback::new(runtime);
                assert_eq!(value.fallback_reason(), None);
                step(&mut value, 0.0);
                let state = value.state.as_ref().unwrap();
                assert_eq!(state.roots.len(), 1);
                assert_eq!(quads(&value).len(), 1);
                // PICd=0 consumes auxiliary translation at Emitter and particle birth.
                assert_eq!(quads(&value)[0].position, [9.0, 12.0, 17.0]);
                let camera = if timeline {
                    state.timeline_parents[0].camera.as_ref().unwrap()
                } else {
                    state.roots[0].camera_binder.as_ref().unwrap()
                };
                assert_eq!(camera.instance.lifecycle.clock.delay, 0.0);
                assert_eq!(camera.instance.lifecycle.registered_children(), 1);
                assert_eq!(
                    camera.instance.state.scale,
                    if timeline { [1.0; 3] } else { [2.0, 3.0, 4.0] }
                );
                assert_eq!(camera.instance.state.auxiliary.position, [4.0, 5.0, 6.0]);
                assert_eq!(
                    camera.instance.state.auxiliary.basis,
                    if timeline {
                        [[0.5, 0.0, 0.0], [0.0, 2.0, 0.0], [0.0, 0.0, -1.25]]
                    } else {
                        [[2.0, 0.0, 0.0], [0.0, 3.0, 0.0], [0.0, 0.0, 4.0]]
                    }
                );
            }
        }
    }

