    #[test]
    fn camera_factory_same_timestamp_updates_once_and_seek_rebuilds_auxiliary() {
        let file = camera_factory_file(false);
        let mut input = camera_factory_input();
        let mut value = camera_factory_playback(&file, input.clone());
        value
            .update_preview_camera_binder_to(0.0, input.clone())
            .unwrap();
        let first = value.state.as_ref().unwrap().instances.input_update();
        let old_aux = value.state.as_ref().unwrap().roots[0].base.auxiliary_matrix;
        value
            .update_preview_camera_binder_to(0.0, input.clone())
            .unwrap();
        assert_eq!(
            value.state.as_ref().unwrap().instances.input_update(),
            first
        );
        input.inverse_view.position = [8.0, 9.0, 10.0];
        input.root_position = [11.0, 12.0, 13.0];
        value
            .update_preview_camera_binder_to(0.0, input.clone())
            .unwrap();
        assert_eq!(
            value.state.as_ref().unwrap().instances.input_update(),
            first + 1
        );
        assert_eq!(
            value.state.as_ref().unwrap().roots[0].base.position,
            [8.0, 9.0, 12.0]
        );
        assert_eq!(
            value.state.as_ref().unwrap().roots[0].base.auxiliary_matrix,
            old_aux
        );
        value
            .update_preview_camera_binder_to(3.0 / 30.0, input.clone())
            .unwrap();
        value.update_preview_camera_binder_to(0.0, input).unwrap();
        assert_eq!(quads(&value)[0].position, [30.0, 33.0, 38.0]);
        assert_eq!(
            value.state.as_ref().unwrap().roots[0]
                .base
                .auxiliary_matrix
                .position,
            [11.0, 12.0, 13.0]
        );
    }

