    #[test]
    fn camera_factory_invalid_input_is_atomic_and_incomplete_camera_updates_rejected() {
        let file = camera_factory_file(true);
        let input = camera_factory_input();
        let mut value = camera_factory_playback(&file, input.clone());
        step(&mut value, 0.0);
        let before = quads(&value);
        let updates = value.state.as_ref().unwrap().instances.input_update();
        for variant in 0..6 {
            let mut invalid = input.clone();
            let mut delta = 1.0 / 30.0;
            match variant {
                0 => invalid.inverse_view.position[0] = f32::NAN,
                1 => invalid.samples.clear(),
                2 => invalid.timeline = None,
                3 => invalid.samples.push(invalid.samples[0].clone()),
                4 => invalid.samples[0].binder_index = 99,
                _ => delta = -1.0,
            }
            assert!(
                value
                    .advance_with_camera_binder_snapshot(delta, invalid)
                    .is_err()
            );
            assert_eq!(value.runtime.camera_binder.as_ref(), Some(&input));
            assert_eq!(
                value.state.as_ref().unwrap().instances.input_update(),
                updates
            );
            assert_eq!(value.seconds, 0.0);
            assert_eq!(quads(&value), before);
        }
        let mut orientation = input.camera;
        orientation.position[0] = 99.0;
        assert!(
            value
                .update_preview_camera_to(0.0, None, orientation)
                .is_err()
        );
        assert_eq!(value.runtime.camera_binder.as_ref(), Some(&input));
    }

