    #[test]
    #[ignore = "requires pinned original Camera factory/constructor CPU probe"]
    fn compare_original_camera_playback_factory_births() {
        compare_camera_factory_probe("camera-binder-construction", false);
    }

    #[test]
    #[ignore = "requires pinned original Camera factory CPU probe without Common storage overrides"]
    fn compare_original_camera_playback_fresh_storage_factories() {
        compare_camera_factory_probe("camera-storage-source", true);
    }

    fn compare_camera_factory_probe(prefix: &str, fresh_storage: bool) {
        use super::super::{
            VfxCameraBinderSample, VfxCameraBinderScaleNode, VfxCameraBinderTimelineSnapshot,
        };
        use serde_json::{Value, json};
        fn float(value: &Value) -> f32 {
            f32::from_bits(value.as_u64().unwrap() as u32)
        }
        fn vector(value: &Value) -> [f32; 3] {
            std::array::from_fn(|axis| float(&value[axis]))
        }
        fn matrix(value: &Value) -> VfxBinderMatrix {
            VfxBinderMatrix {
                basis: std::array::from_fn(|column| {
                    std::array::from_fn(|row| float(&value[column * 3 + row]))
                }),
                position: std::array::from_fn(|row| float(&value[9 + row])),
            }
        }
        let output =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target/weapon-vfx-audit");
        let original: Value = serde_json::from_slice(
            &std::fs::read(output.join(format!("{prefix}-client-probe.json"))).unwrap(),
        )
        .unwrap();
        let cases = original["cases"].as_array().unwrap();
        assert_eq!(cases.len(), 7200);
        let mut components = 0;
        let mut owners = [0; 2];
        for (index, case) in cases.iter().enumerate() {
            let timeline = case["ownerKind"] == 1;
            let mut file = camera_factory_file(timeline);
            file.global.ags_enabled = case["rootF4"].as_bool().unwrap();
            let flags = case["flags"].as_u64().unwrap();
            let binder = &mut file.binders[0];
            binder.life = case["life"].as_i64().unwrap() as i32;
            binder.rotation_type = case["rotation"].as_i64().unwrap() as i32;
            binder.document_scale_enabled = flags & 1 != 0;
            binder.adjust_to_screen_enabled = flags & 2 != 0;
            binder.ify = flags & 4 != 0;
            binder.properties_start.as_mut().unwrap().coord_update_frame =
                case["deadline"].as_i64().unwrap() as i32;
            binder.properties_start.as_mut().unwrap().generate_delay =
                if case["chain"] == 0 { -32768 } else { 32767 };
            binder.properties_start.as_mut().unwrap().bind_point_type =
                case["chain"].as_i64().unwrap() as i32 % 4;
            let inputs = &case["inputs"];
            let chain: Vec<_> = case["scaleChain"]
                .as_array()
                .unwrap()
                .iter()
                .map(|node| VfxCameraBinderScaleNode {
                    inherits_scale: node["inherit"].as_bool().unwrap(),
                    is_timeline: node["kind"] == 3,
                    scale: vector(&node["scale"]),
                    timeline_scale: vector(&node["timelineScale"]),
                })
                .collect();
            let mut snapshot = camera_factory_input();
            snapshot.root_flag_f4 = case["rootF4"].as_bool().unwrap();
            snapshot.screen_height = case["screenHeight"].as_u64().unwrap() as u32;
            snapshot.ify_scale = Some(float(&case["ifyScale"]));
            snapshot.inverse_view = matrix(&inputs["inverseView"]);
            snapshot.document_rotation = matrix(&inputs["rotationMatrix"]);
            snapshot.root_position = vector(&inputs["rootPosition"]);
            snapshot.camera.basis = std::array::from_fn(|column| {
                std::array::from_fn(|row| float(&inputs["cameraBasis"][column * 3 + row]))
            });
            snapshot.camera.position = vector(&inputs["cameraPosition"]);
            snapshot.camera.parallel_direction = vector(&inputs["parallelDirection"]);
            snapshot.timeline = Some(if fresh_storage {
                let defaults =
                    VfxCameraBinderTimelineSnapshot::for_new_object(snapshot.document_rotation);
                assert_eq!(
                    chain,
                    vec![defaults.local],
                    "case {index}: native fresh storage"
                );
                assert_eq!(
                    vector(&case["scaleChain"][0]["scale"]),
                    defaults.storage_scale
                );
                assert_eq!(case["scaleChain"][0]["kind"], 0);
                defaults
            } else {
                VfxCameraBinderTimelineSnapshot {
                    rotation: snapshot.document_rotation,
                    storage_scale: chain[0].scale,
                    local: chain[0],
                    ancestors: chain[1..].to_vec(),
                }
            });
            let writes = case["queryMode"].as_u64().unwrap() >= 2;
            snapshot.samples = vec![VfxCameraBinderSample {
                binder_index: 0,
                query_succeeded: case["queryMode"] == 3,
                query_scale: writes.then_some([2.0, 0.25, -1.0]),
                query_vfx_scale: writes.then_some(0.25),
                query_depth_scale: writes.then_some(2.0),
                distance: Some(float(&case["distance"])),
            }];
            let runtime = VfxRuntime::new(&file)
                .with_document_scale(vector(&inputs["documentScale"]))
                .unwrap()
                .with_camera_binder_snapshot(snapshot)
                .unwrap()
                .with_binder_target_objects(&vec![
                    linear_target_source(100.0);
                    if case["chain"] == 0 { 0 } else { 12 }
                ])
                .unwrap();
            let age = float(&case["inputAge"]);
            let (camera, base) = if timeline {
                let pending = TimelineRootState::new_pending(
                    &runtime,
                    &file.timelines[0],
                    Some(0),
                    Some(0),
                    0.0,
                    0,
                    false,
                )
                .unwrap();
                let mut births = construct_scheduler_definition(&runtime, &pending, age).unwrap();
                assert_eq!(
                    births.len(),
                    1,
                    "case {index}: Camera must not expand targets"
                );
                let parent = births.pop().unwrap();
                assert!(parent.child.is_some());
                (parent.camera.unwrap(), parent.base)
            } else {
                let mut state = StagedPlayback::new(&runtime, &HashSet::new()).unwrap();
                let mut root = state.timeline_parents[0].templates[0].clone();
                let plans = item_factory_births(&runtime, 0);
                assert_eq!(
                    plans.len(),
                    1,
                    "case {index}: Camera must not expand targets"
                );
                state
                    .instances
                    .control_roots(&file, |preparation| {
                        let root_index =
                            preparation.add_binder_root(root.index, -1.0, root.seed)?;
                        root.construct_binder(&runtime, 0, age, age, root_index, preparation)?;
                        assert_eq!(preparation.registered_children(root_index), 1);
                        Ok(())
                    })
                    .unwrap();
                (root.camera_binder.unwrap(), root.base)
            };
            let native = &case["afterFactory"];
            let state = camera.instance.state;
            let clock = camera.instance.lifecycle.clock;
            for (component, (actual, expected)) in state
                .primary
                .basis
                .into_iter()
                .flatten()
                .chain(state.primary.position)
                .chain(state.auxiliary.basis.into_iter().flatten())
                .chain(state.auxiliary.position)
                .chain(state.scale)
                .chain([
                    state.query_vfx_scale,
                    state.transform_depth_scale,
                    clock.local_age,
                    clock.total_age,
                    clock.previous_age,
                    clock.delay,
                    clock.nominal_life,
                ])
                .zip(
                    native["primary"]
                        .as_array()
                        .unwrap()
                        .iter()
                        .chain(native["auxiliary"].as_array().unwrap())
                        .chain(native["scale"].as_array().unwrap())
                        .chain([
                            &native["vfx"],
                            &native["depth"],
                            &native["age"],
                            &native["total"],
                            &native["previous"],
                            &native["delay"],
                            &native["life"],
                        ]),
                )
                .enumerate()
            {
                assert_eq!(
                    actual.to_bits(),
                    expected.as_u64().unwrap() as u32,
                    "case {index} component {component}"
                );
                components += 1;
            }
            assert_eq!(
                camera.instance.lifecycle.raw_flags(),
                native["flags"].as_u64().unwrap() as u32
            );
            assert_eq!(
                camera.instance.lifecycle.life_limit_enabled,
                native["lifeEnabled"].as_bool().unwrap()
            );
            assert_eq!(
                camera.instance.lifecycle.registered_children(),
                native["children"].as_u64().unwrap() as u16
            );
            assert_eq!(base.position, state.primary.position);
            assert_eq!(base.linear, state.primary.basis);
            assert_eq!(base.auxiliary_matrix, state.auxiliary);
            assert_eq!(base.scale, state.scale);
            owners[usize::from(timeline)] += 1;
        }
        let report = if fresh_storage {
            "camera-storage-source-rust-comparison.json"
        } else {
            "camera-playback-factory-rust-comparison.json"
        };
        std::fs::write(output.join(report),serde_json::to_vec_pretty(&json!({
            "cases":cases.len(),"emitterOwnerFactories":owners[0],"timelineOwnerFactories":owners[1],
            "finiteComponentsCompared":components,"differences":0,"productionFactoriesCompared":true,
            "fullOwnedOriginalTraceCompared":false,
            "nativeCommonStorageUntouched":fresh_storage,
            "scope":"Original Camera Item/Scheduler birth snapshots vs actual production Root::construct_binder and construct_scheduler_definition. Production creates one Emitter or Timeline child with resolved Camera sources despite query failure, target counts and GenD. Both matrices, scale/query caches, own clocks/flags/life gate/registered child count and getter bases compared. Original child phases, resource allocation/pool addresses, live source producers/shared RNG/CRT trig and GPU are not compared."
        })).unwrap()).unwrap();
    }

    #[test]
    fn camera_factory_end_retires_both_owners_and_collects_complete_tree() {
        let mut file = trigger_fixture(AvfxTimelineClipType::End, [0; 4], 3);
        file.binders = camera_factory_file(false).binders;
        file.global.ags_enabled = true;
        file.timelines[1].binder_index = 0;
        file.timelines[1].items[0].binder_index = 0;
        file.schedulers[0].items.insert(
            0,
            AvfxSchedulerItem {
                enabled: true,
                start_time: 0,
                timeline_index: 1,
            },
        );
        let mut value = camera_factory_playback(&file, camera_factory_input());
        step(&mut value, 0.0);
        assert_eq!(quads(&value).len(), 1);
        step(&mut value, 3.0);
        let state = value.state.as_ref().unwrap();
        assert!(
            state.timeline_parents[0]
                .camera
                .as_ref()
                .unwrap()
                .instance
                .lifecycle
                .retired()
        );
        assert!(
            state.roots[0]
                .camera_binder
                .as_ref()
                .unwrap()
                .instance
                .lifecycle
                .retired()
        );
        assert!(quads(&value).is_empty());
        for _ in 0..5 {
            step(&mut value, 0.0);
        }
        let state = value.state.as_ref().unwrap();
        assert!(state.roots.is_empty());
        assert!(state.timeline_parents.is_empty());
    }

    #[test]
    fn camera_factory_scheduler_unlock_reaches_both_owners_and_children() {
        let mut file = ullp_fixture(true);
        file.binders = camera_factory_file(false).binders;
        file.global.ags_enabled = true;
        file.timelines[1].binder_index = 0;
        file.timelines[1].items[0].binder_index = 0;
        let mut value = camera_factory_playback(&file, camera_factory_input());
        for delta in [0.0, 2.0, 2.0] {
            step(&mut value, delta);
        }
        let state = value.state.as_ref().unwrap();
        let parent = state
            .timeline_parents
            .iter()
            .find(|p| p.camera.is_some())
            .unwrap();
        for life in [
            parent.camera.as_ref().unwrap().instance.lifecycle,
            state.roots[0]
                .camera_binder
                .as_ref()
                .unwrap()
                .instance
                .lifecycle,
        ] {
            assert_eq!(life.raw_flags() & 0x80c00000, 0x00800000);
        }
        assert_eq!(parent.child.unwrap().loop_generation(), 0);
        assert_eq!(state.roots.len(), 1);
        assert!(
            state
                .instances
                .common_tree_states(0)
                .iter()
                .all(|n| n.flags & 0x80c00000 == 0x00800000)
        );
    }

