    #[test]
    fn camera_factory_rest_self_rebuilds_current_constructor_sources_without_retention_growth() {
        let mut file = rest_self_fixture();
        file.binders = camera_factory_file(false).binders;
        file.global.ags_enabled = true;
        file.timelines[0].binder_index = 0;
        file.timelines[0].items[1].binder_index = 0;
        let mut input = camera_factory_input();
        let mut value = camera_factory_playback(&file, input.clone());
        let mut previous_id = None;
        for turn in 0..8 {
            input.root_position = [turn as f32 + 10.0, 20.0, 30.0];
            value
                .advance_with_camera_binder_snapshot(2.5 / 30.0, input.clone())
                .unwrap();
            assert_eq!(value.fallback_reason(), None);
            let state = value.state.as_ref().unwrap();
            assert_eq!(state.timeline_parents.len(), 1);
            assert_eq!(state.roots.len(), 1);
            let parent = &state.timeline_parents[0];
            assert_eq!(
                parent
                    .camera
                    .as_ref()
                    .unwrap()
                    .instance
                    .state
                    .auxiliary
                    .position,
                input.root_position
            );
            assert_eq!(
                state.roots[0]
                    .camera_binder
                    .as_ref()
                    .unwrap()
                    .instance
                    .state
                    .auxiliary
                    .position,
                input.root_position
            );
            let id = state.instances.root_id(0).unwrap();
            assert!(previous_id.is_none_or(|old| id > old));
            previous_id = Some(id);
            assert_eq!(quads(&value).len(), 1);
        }
    }

