    #[test]
    fn binder_factory_finite_parent_freezes_matrix_but_child_and_particle_tails_advance() {
        for point in [false, true] {
            let file = binder_factory_fixture(point, 1, 0, 2);
            let mut value = dynamic_linear_playback(&file);
            value
                .advance_with_binder_target_snapshot(1.0 / 30.0, &dynamic_linear_targets(true))
                .unwrap();
            let state = value.state.as_ref().unwrap();
            assert!(!binder_lifecycle(&state.roots[0]).retired());
            let frozen = state.roots[0].base;
            value
                .advance_with_binder_target_snapshot(1.0 / 30.0, &dynamic_linear_targets(false))
                .unwrap();
            let state = value.state.as_ref().unwrap();
            assert!(binder_lifecycle(&state.roots[0]).retired());
            assert_eq!(state.roots[0].base, frozen);
            near(state.instances.curve_ages(0).local, 1.0);
            near(state.instances.particles(0).next().unwrap().age, 2.0);
            value
                .advance_with_binder_target_snapshot(1.0 / 30.0, &[])
                .unwrap();
            near(
                value
                    .state
                    .as_ref()
                    .unwrap()
                    .instances
                    .particles(0)
                    .next()
                    .unwrap()
                    .age,
                3.0,
            );
            assert_eq!(quads(&value).len(), 1);
            // Particle retirement at >4, removal next Time, then the empty
            // emitter is removed from the Binder at the following Time pass.
            for _ in 0..3 {
                value
                    .advance_with_binder_target_snapshot(1.0 / 30.0, &[])
                    .unwrap();
            }
            assert_eq!(value.state.as_ref().unwrap().roots.len(), 1);
            assert!(quads(&value).is_empty());
            value
                .advance_with_binder_target_snapshot(1.0 / 30.0, &[])
                .unwrap();
            // Common's owner removes a retired empty Binder at the next Time.
            assert_eq!(value.state.as_ref().unwrap().roots.len(), 1);
            assert!(binder_lifecycle(&value.state.as_ref().unwrap().roots[0]).retired());
            assert_eq!(
                binder_lifecycle(&value.state.as_ref().unwrap().roots[0]).registered_children(),
                0
            );
            value
                .advance_with_binder_target_snapshot(0.0, &dynamic_linear_targets(true))
                .unwrap();
            assert!(value.state.as_ref().unwrap().roots.is_empty());
        }
    }

    #[test]
    fn point_factory_pending_birth_precedes_short_parent_life_check() {
        let file = binder_factory_fixture(true, 1, 3, 10);
        let mut value = dynamic_linear_playback(&file);
        value
            .advance_with_binder_target_snapshot(2.0 / 30.0, &dynamic_linear_targets(true))
            .unwrap();
        let state = value.state.as_ref().unwrap();
        assert_eq!(state.roots.len(), 1);
        let point = binder_lifecycle(&state.roots[0]);
        assert!(!point.retired());
        assert!(!point.life_limit_enabled);
        assert_eq!(point.raw_flags() & 511, 1);
        assert_eq!(state.instances.root_id(0), None);
        value
            .advance_with_binder_target_snapshot(0.0, &dynamic_linear_targets(true))
            .unwrap();
        assert_eq!(value.state.as_ref().unwrap().roots.len(), 1);
        value
            .advance_with_binder_target_snapshot(1.0 / 30.0, &dynamic_linear_targets(true))
            .unwrap();
        let state = value.state.as_ref().unwrap();
        let point = binder_lifecycle(&state.roots[0]);
        assert!(!point.retired());
        assert!(point.life_limit_enabled);
        assert_eq!(point.raw_flags() & 511, 0);
        let born = state.instances.root_id(0).unwrap();
        assert_eq!(quads(&value).len(), 1);
        value
            .advance_with_binder_target_snapshot(2.0 / 30.0, &dynamic_linear_targets(false))
            .unwrap();
        let state = value.state.as_ref().unwrap();
        assert!(binder_lifecycle(&state.roots[0]).retired());
        assert_eq!(state.instances.root_id(0), Some(born));
        assert_eq!(binder_lifecycle(&state.roots[0]).registered_children(), 1);
    }

