    #[test]
    fn point_factory_multiple_delayed_roots_start_before_short_parent_retires() {
        let mut file = binder_factory_fixture(true, 1, 3, 10);
        let mut second = file.binders[0].clone();
        second.life = 20;
        file.binders.push(second);
        let mut item = file.timelines[0].items[0];
        item.binder_index = 1;
        file.timelines[0].items.push(item);
        let mut value = dynamic_linear_playback(&file);
        value
            .advance_with_binder_target_snapshot(2.0 / 30.0, &dynamic_linear_targets(true))
            .unwrap();
        let state = value.state.as_ref().unwrap();
        assert_eq!(state.roots.len(), 2);
        assert!(
            state
                .roots
                .iter()
                .all(|r| !binder_lifecycle(r).retired() && !binder_lifecycle(r).life_limit_enabled)
        );
        value
            .advance_with_binder_target_snapshot(0.0, &dynamic_linear_targets(true))
            .unwrap();
        assert_eq!(value.state.as_ref().unwrap().roots.len(), 2);
        value
            .advance_with_binder_target_snapshot(2.0 / 30.0, &dynamic_linear_targets(true))
            .unwrap();
        let state = value.state.as_ref().unwrap();
        assert_eq!(state.roots.len(), 2);
        for index in 0..2 {
            assert!(state.instances.root_id(index).is_some());
            assert_eq!(
                binder_lifecycle(&state.roots[index]).registered_children(),
                1
            );
            near(state.instances.curve_ages(index).local, 1.0);
        }
        assert_eq!(quads(&value).len(), 2);
        value
            .advance_with_binder_target_snapshot(1.0 / 30.0, &dynamic_linear_targets(false))
            .unwrap();
        let state = value.state.as_ref().unwrap();
        assert_eq!(state.roots.len(), 2);
        assert!(binder_lifecycle(&state.roots[0]).retired());
        assert!(!binder_lifecycle(&state.roots[1]).retired());
        assert!(
            state
                .roots
                .iter()
                .all(|r| binder_lifecycle(r).registered_children() == 1)
        );
    }

