    #[test]
    fn dynamic_point_deadline_is_inclusive_and_late_failure_keeps_offset_updates() {
        let mut file = dynamic_point_fixture(2);
        file.binders[0]
            .properties_start
            .as_mut()
            .unwrap()
            .coord_update_frame = 1;
        let mut value = dynamic_linear_playback(&file);
        value
            .advance_with_binder_target_snapshot(1.0 / 30.0, &dynamic_linear_targets(true))
            .unwrap();
        let before = quads(&value);
        value
            .advance_with_binder_target_snapshot(1.0 / 30.0, &dynamic_linear_targets(false))
            .unwrap();
        assert_eq!(before, quads(&value));
        // Negative signed-word aliases keep querying. A missing provider keeps
        // the last target, but Pos is still applied to the evolving matrix.
        file.binders[0]
            .properties_start
            .as_mut()
            .unwrap()
            .coord_update_frame = 65535;
        file.binders[0]
            .properties_start
            .as_mut()
            .unwrap()
            .position
            .x = Some(curve(&[(0, 0.25)]));
        file.binders[0].data.as_mut().unwrap().spring_strength = Some(curve(&[(0, 0.5)]));
        let mut value = dynamic_linear_playback(&file);
        near(
            value.state.as_ref().unwrap().roots[0].base.position[0],
            0.25,
        );
        value
            .advance_with_binder_target_snapshot(1.0 / 30.0, &[])
            .unwrap();
        near(
            value.state.as_ref().unwrap().roots[0].base.position[0],
            0.375,
        );
        assert_eq!(value.fallback_reason(), None);
    }

