    #[test]
    fn scheduled_binders_query_at_birth_and_keep_timeline_overshoot() {
        for binder_type in [0, 1, 4] {
            for mode in 0..=3 {
                let mut file = if binder_type == 0 {
                    dynamic_point_fixture(mode)
                } else {
                    dynamic_linear_fixture(mode)
                };
                file.binders[0].binder_type = binder_type;
                file.binders[0].life = 20;
                file.binders[0]
                    .properties_start
                    .as_mut()
                    .unwrap()
                    .position
                    .x = Some(curve(&[(0, 0.0), (2, 2.0)]));
                if binder_type != 0 {
                    file.binders[0].data.as_mut().unwrap().carry_over_factor =
                        Some(curve(&[(0, 0.25), (2, 0.75)]));
                }
                file.timelines[0].items[0].start_time = 2;
                file.timelines[0].items[0].end_time = 12;
                file.emitters[0].position = Default::default();
                file.particles[0].position = Default::default();
                let mut value = dynamic_linear_playback(&file);
                assert!(quads(&value).is_empty());
                assert!(
                    value.state.as_ref().unwrap().roots[0]
                        .pending_binder
                        .is_some()
                );
                value
                    .advance_with_binder_target_snapshot(1.0 / 30.0, &[])
                    .unwrap();
                assert!(quads(&value).is_empty());
                let root = &value.state.as_ref().unwrap().roots[0];
                assert!(root.point_binder.is_none() && root.linear_binder.is_none());
                value
                    .advance_with_binder_target_snapshot(2.0 / 30.0, &dynamic_linear_targets(true))
                    .unwrap();
                let root = &value.state.as_ref().unwrap().roots[0];
                near(binder_lifecycle(root).clock.local_age, 1.0);
                let expected = if binder_type == 0 {
                    [4.0, 0.0, 0.0]
                } else {
                    [5.0, -0.5, 0.0]
                };
                let first = quads(&value);
                assert_eq!(first.len(), 1);
                for a in 0..3 {
                    near(first[0].position[a], expected[a]);
                }
                let id = value.state.as_ref().unwrap().instances.root_id(0);
                assert_eq!(first, quads(&value));
                value
                    .advance_with_binder_target_snapshot(1.0 / 30.0, &dynamic_linear_targets(false))
                    .unwrap();
                assert_eq!(value.state.as_ref().unwrap().instances.root_id(0), id);
                let expected = if mode == 2 { [2.0, 0.0, 0.0] } else { expected };
                for a in 0..3 {
                    near(quads(&value)[0].position[a], expected[a]);
                }
                near(
                    binder_lifecycle(&value.state.as_ref().unwrap().roots[0])
                        .clock
                        .local_age,
                    2.0,
                );
            }
        }
    }

