    #[test]
    fn regular_linear_item_ignores_generation_delay_and_keeps_scheduled_age() {
        for binder_type in [1, 4] {
            for delay in [0, 2, 65535, 65536, 32768] {
                for start in [0, 2] {
                    let mut file = binder_factory_fixture(false, 20, delay, 10);
                    file.binders[0].binder_type = binder_type;
                    file.timelines[0].items[0].start_time = start;
                    file.timelines[0].items[0].end_time += start;
                    let mut value = dynamic_linear_playback(&file);
                    assert_eq!(quads(&value).is_empty(), start != 0);
                    if start != 0 {
                        value
                            .advance_with_binder_target_snapshot(
                                5.0 / 30.0,
                                &dynamic_linear_targets(true),
                            )
                            .unwrap();
                    }
                    assert_eq!(quads(&value).len(), 1);
                    let state = value.state.as_ref().unwrap();
                    let clock = binder_lifecycle(&state.roots[0]).clock;
                    near(clock.delay, 0.0);
                    near(clock.local_age, if start == 0 { 0.0 } else { 3.0 });
                    near(state.instances.curve_ages(0).local, clock.local_age);
                    near(state.instances.particles(0).next().unwrap().age, 0.0);
                }
            }
        }
    }

