    #[test]
    fn dynamic_linear_failed_birth_never_falls_back_to_static_points_or_spawns_on_recovery() {
        let file = dynamic_linear_fixture(2);
        let points = [VfxBindPoint {
            parent_bone: None,
            id: 4,
            translate: [10.0; 3],
            rotate: [0.0; 3],
        }];
        let runtime = VfxRuntime::with_bind_points(&file, &points)
            .with_binder_target_snapshot(&[])
            .unwrap();
        let mut value = VfxPlayback::new(runtime);
        assert_eq!(value.fallback_reason(), None);
        assert!(quads(&value).is_empty());
        value
            .advance_with_binder_target_snapshot(1.0 / 30.0, &dynamic_linear_targets(true))
            .unwrap();
        assert!(quads(&value).is_empty());
        // Common's owner removes a retired empty Binder at the next Time.
        assert_eq!(value.state.as_ref().unwrap().roots.len(), 1);
        assert!(binder_lifecycle(&value.state.as_ref().unwrap().roots[0]).retired());
        assert_eq!(
            binder_lifecycle(&value.state.as_ref().unwrap().roots[0]).registered_children(),
            0
        );
        value
            .advance_with_binder_target_snapshot(0.0, &dynamic_linear_targets(true))
            .unwrap();
        assert!(value.state.as_ref().unwrap().roots.is_empty());
    }

    #[test]
    fn dynamic_linear_snapshot_and_time_validation_are_atomic() {
        let file = dynamic_linear_fixture(2);
        let mut value = dynamic_linear_playback(&file);
        let before = quads(&value);
        let generation = value.state.as_ref().unwrap().instances.input_update();
        let targets = value.runtime.binder_targets.clone();
        let mut invalid = dynamic_linear_targets(true);
        invalid[0].matrix.basis[0][0] = f32::NAN;
        assert!(
            value
                .advance_with_binder_target_snapshot(1.0 / 30.0, &invalid)
                .is_err()
        );
        let mut duplicate = dynamic_linear_targets(true);
        duplicate[1].id = duplicate[0].id;
        assert!(
            value
                .advance_with_binder_target_snapshot(0.0, &duplicate)
                .is_err()
        );
        for seconds in [-1.0, f32::NAN, f32::MAX] {
            assert!(
                value
                    .advance_with_binder_target_snapshot(seconds, &dynamic_linear_targets(true))
                    .is_err()
            );
        }
        assert_eq!(value.runtime.binder_targets, targets);
        assert_eq!(
            value.state.as_ref().unwrap().instances.input_update(),
            generation
        );
        assert_eq!(value.seconds, 0.0);
        assert_eq!(before, quads(&value));
        let mut static_value = VfxPlayback::new(VfxRuntime::new(&document_history_fixture(2)));
        assert!(
            static_value
                .advance_with_binder_target_snapshot(0.0, &[])
                .is_err()
        );
    }

