    #[test]
    fn dynamic_linear_delayed_nested_birth_keeps_finished_parent_source() {
        for finished in [false, true] {
            let mut file = dynamic_linear_fixture(3);
            file.particles[0].life.enabled = true;
            file.particles[0].life.value = 10.0;
            let mut child = file.emitters[0].clone();
            child.life.enabled = true;
            child.life.value = 20.0;
            child.particle_items[0].create_time = 1;
            child.particle_items[0].generate_delay = 3;
            file.emitters[0].particle_items.clear();
            file.emitters[0].emitter_items = vec![AvfxEmitterItem {
                enabled: true,
                target_index: 1,
                parameter_link: -1,
                create_probability: 100,
                create_count: 1,
                parent_influence_coord: 3,
                ..Default::default()
            }];
            file.emitters.push(child);
            if finished {
                file.timelines[0].items[0].end_time = 1;
            }
            let mut value = dynamic_linear_playback(&file);
            assert!(quads(&value).is_empty());
            let root_id = value.state.as_ref().unwrap().instances.root_id(0);
            for _ in 0..4 {
                value
                    .advance_with_binder_target_snapshot(1.0 / 30.0, &dynamic_linear_targets(true))
                    .unwrap();
            }
            assert_eq!(value.fallback_reason(), None);
            let actual = quads(&value);
            assert_eq!(actual.len(), 1, "finished={finished}");
            // Whole initial parent chain: endpoint midpoint 1 plus
            // diag(2,1,1) * (root .125 + child .125 + particle .25).
            near(actual[0].position[0], 2.0);
            near(actual[0].position[1], 0.0);
            near(actual[0].parent_basis[0][0], 2.0);
            assert_eq!(value.state.as_ref().unwrap().instances.root_id(0), root_id);
            assert_eq!(
                value.state.as_ref().unwrap().roots[0].history[0].input_update,
                0
            );
            // Keep the retired ancestor until its last delayed child tail dies.
            for _ in 0..30 {
                value
                    .advance_with_binder_target_snapshot(1.0 / 30.0, &dynamic_linear_targets(true))
                    .unwrap();
            }
            if finished {
                assert!(value.state.as_ref().unwrap().roots.is_empty());
                assert!(quads(&value).is_empty());
            }
        }
    }

