    #[test]
    fn document_history_rejects_invalid_updates_without_changing_source_or_playback() {
        let [initial, mut invalid] = document_history_hosts();
        let file = document_history_fixture(2);
        let mut value = VfxPlayback::new(
            VfxRuntime::new(&file)
                .with_document_matrix(initial)
                .unwrap(),
        );
        let before = quads(&value);
        invalid.basis[0][1] = f32::NAN;
        assert!(value.advance_with_document_matrix(0.0, invalid).is_err());
        assert!(
            value
                .advance_with_document_matrix(-1.0, VfxBinderMatrix::IDENTITY)
                .is_err()
        );
        assert!(
            value
                .advance_with_document_matrix(f32::MAX, VfxBinderMatrix::IDENTITY)
                .is_err()
        );
        assert_eq!(
            value.runtime.document_transform.auxiliary_matrix.basis,
            initial.basis
        );
        assert_eq!(value.state.as_ref().unwrap().instances.input_update(), 0);
        assert_eq!(before, quads(&value));
        let mut unsupported = file.clone();
        unsupported.emitters[0].emitter_type = None;
        let mut unsupported = VfxPlayback::new(VfxRuntime::new(&unsupported));
        assert!(unsupported.fallback_reason().is_some());
        assert!(
            unsupported
                .advance_with_document_matrix(0.0, initial)
                .is_err()
        );
        let mut bound = dynamic_point_offset_fixture(false, false);
        bound.binders[1]
            .properties_start
            .as_mut()
            .unwrap()
            .position
            .x = None;
        let mut bound = VfxPlayback::new(VfxRuntime::new(&bound));
        assert!(bound.advance_with_document_matrix(0.0, initial).is_err());
    }

    #[test]
    fn point_auxiliary_reaches_root_and_particle_once_in_both_playback_paths() {
        for ags in [false, true] {
            for coord in 0..=3 {
                let mut file = fixture();
                file.global.ags_enabled = ags;
                file.global.revised_position = if ags { [0.125, -0.125, 0.25] } else { [0.0; 3] };
                file.timelines[0].items[0].binder_index = 0;
                file.binders.push(AvfxBinder {
                    bind_point_id: 3,
                    life: -1,
                    ..Default::default()
                });
                file.emitters[0].position.x = Some(curve(&[(0, 0.125)]));
                file.emitters[0].create_interval = curve(&[(0, 1000.0)]);
                file.emitters[0].particle_items[0].parent_influence_coord = coord;
                file.particles[0].position.x = Some(curve(&[(0, 0.25)]));
                file.particles[0].rotation_direction_base = rotation_direction_base::NONE;
                let points = [VfxBindPoint {
                    id: 3,
                    parent_bone: None,
                    translate: [-0.25, 0.0, 0.0],
                    rotate: [0.0; 3],
                }];
                let runtime = VfxRuntime::with_bind_points(&file, &points)
                    .with_document_scale([-2.0, 0.5, 1.0])
                    .unwrap();
                let mut staged = VfxPlayback::new(runtime.clone());
                assert!(
                    staged.fallback_reason().is_none(),
                    "{:?}",
                    staged.fallback_reason()
                );
                step(&mut staged, 1.0);
                let staged_quads = quads(&staged);
                let mut continuous = Vec::new();
                runtime.sample(1.0 / 30.0, &mut continuous);
                for values in [&staged_quads, &continuous] {
                    assert_eq!(values.len(), 1, "PICd={coord}");
                    // Root: -0.25 + (-2 * 0.125) = -0.5.
                    // Child: -0.5 + (-2 * 0.25) = -1, using its
                    // auxiliary getter for 0/1 and parent matrix for 2/3.
                    // Zero-Euler bAGS also caches root revision translation.
                    // PICd 0/1 consumes it locally as well; 2/3 inherits it once.
                    let revisions = if ags {
                        if coord < 2 { 2.0 } else { 1.0 }
                    } else {
                        0.0
                    };
                    near(values[0].position[0], -1.0 + revisions * 0.125);
                    near(values[0].position[1], revisions * -0.125);
                    near(values[0].position[2], revisions * 0.25);
                    assert_eq!(
                        values[0].parent_basis,
                        [[-2.0, 0.0, 0.0], [0.0, 0.5, 0.0], [0.0, 0.0, 1.0]]
                    );
                }
            }
        }
    }

