    #[test]
    fn scheduled_direct_root_constructs_at_overshoot_without_allocating_early() {
        let mut file = fixture();
        file.timelines[0].items[0].start_time = 2;
        file.timelines[0].items[0].end_time = 12;
        file.emitters[0].create_interval = curve(&[(0, 1000.0)]);
        file.emitters[0].particle_items[0].create_time = 1;
        file.particles[0].rotation_direction_base = rotation_direction_base::NONE;
        let mut second = file.timelines[0].items[0].clone();
        second.start_time = 0;
        file.timelines[0].items.push(second);
        let mut value = playback(&file);
        assert_eq!(value.state.as_ref().unwrap().instances.root_id(0), None);
        assert_eq!(quads(&value).len(), 1);
        let immediate_id = value.state.as_ref().unwrap().instances.root_id(1).unwrap();
        step(&mut value, 1.0);
        assert_eq!(value.state.as_ref().unwrap().instances.root_id(0), None);
        step(&mut value, 2.0);
        let state = value.state.as_ref().unwrap();
        assert!(state.instances.root_id(0).unwrap() > immediate_id);
        near(state.instances.curve_ages(0).local, 1.0);
        let particle = state.instances.particles(0).next().unwrap();
        near(particle.age, 0.0);
        near(particle.input_delta, 0.0);
        near(particle.parent_curve_age, 1.0);
        let output = quads(&value);
        assert!(output.iter().any(|q| (q.position[0] - 1.0).abs() < 1e-5));
        assert_eq!(output, quads(&value));
        step(&mut value, 0.0);
        near(
            value.state.as_ref().unwrap().instances.curve_ages(0).local,
            1.0,
        );
    }

    #[test]
    fn scheduled_direct_root_keeps_accumulated_f32_timeline_age_bits() {
        for start in [1, 2, 3, 10] {
            let mut file = fixture();
            file.timelines[0].items[0].start_time = start;
            file.emitters[0].create_interval = curve(&[(0, 1000.0)]);
            let mut value = playback(&file);
            for _ in 0..200 {
                step(&mut value, 0.1);
                let state = value.state.as_ref().unwrap();
                if state.elapsed_frames < start as f32 {
                    assert_eq!(state.instances.root_id(0), None);
                } else {
                    assert_eq!(
                        state.instances.curve_ages(0).local.to_bits(),
                        (state.elapsed_frames - start as f32).to_bits(),
                        "Timeline overshoot at StTm={start}",
                    );
                    break;
                }
            }
            assert!(value.state.as_ref().unwrap().instances.root_id(0).is_some());
        }
    }

