    #[test]
    fn staged_timeline_rejection_identifies_unmodeled_timing() {
        let mut file = fixture();
        file.timelines[0].items[0].start_time = -1;
        assert_eq!(
            VfxPlayback::new(VfxRuntime::new(&file)).fallback_reason(),
            Some("staged playback: Timeline negative Item start")
        );

        file.timelines[0].items[0].start_time = 0;
        file.schedulers.push(AvfxScheduler {
            items: vec![AvfxSchedulerItem {
                enabled: true,
                start_time: -1,
                timeline_index: 0,
            }],
            ..Default::default()
        });
        assert_eq!(
            VfxPlayback::new(VfxRuntime::new(&file)).fallback_reason(),
            Some("staged playback: Timeline negative Scheduler start")
        );

        file.schedulers.clear();
        file.timelines[0].loop_start = -1;
        file.timelines[0].loop_end = 10;
        assert_eq!(
            VfxPlayback::new(VfxRuntime::new(&file)).fallback_reason(),
            Some("staged playback: Timeline negative loop start")
        );

        file.timelines[0].loop_start = 0;
        file.timelines[0].binder_index = 0;
        assert_eq!(
            VfxPlayback::new(VfxRuntime::new(&file)).fallback_reason(),
            Some("staged playback: Timeline loop Binder")
        );
    }

    #[test]
    fn static_point_timeline_binder_keeps_bound_loop_tails() {
        let mut file = fixture();
        file.timelines[0].loop_end = 10;
        file.timelines[0].binder_index = 0;
        file.timelines[0].items[0].end_time = 15;
        file.emitters[0].create_interval = curve(&[(0, 100.0)]);
        file.emitters[0].position.x = Some(curve(&[(0, 1.0)]));
        file.particles[0].life = AvfxLife {
            enabled: true,
            value: 40.0,
            ..Default::default()
        };
        file.binders.push(AvfxBinder {
            bind_point_id: 4,
            life: -1,
            transform_scale: 255,
            properties_start: Some(AvfxBinderProperties {
                bind_target_point_type: 3,
                bind_point_id: 4,
                coord_update_frame: -1,
                ..Default::default()
            }),
            data: Some(AvfxBinderData {
                spring_strength: Some(curve(&[(0, 1.0)])),
                ..Default::default()
            }),
            ..Default::default()
        });
        let points = [VfxBindPoint {
            parent_bone: None,
            id: 4,
            translate: [10.0, 2.0, 3.0],
            rotate: [0.0, 0.0, std::f32::consts::FRAC_PI_2],
        }];
        let runtime = VfxRuntime::with_bind_points(&file, &points);
        let mut value = VfxPlayback::new(runtime.clone());
        assert_eq!(value.fallback_reason(), None);
        for (delta, count) in [(0.0, 1), (10.0, 2), (10.0, 3)] {
            if delta > 0.0 {
                step(&mut value, delta);
            }
            let staged = quads(&value);
            assert_eq!(staged.len(), count);
            for quad in &staged {
                near(quad.position[0], 11.0);
                near(quad.position[1], 2.0);
                near(quad.position[2], 3.0);
            }
            let mut continuous = Vec::new();
            runtime.sample(
                value.state.as_ref().unwrap().elapsed_frames / 30.0,
                &mut continuous,
            );
            assert_eq!(continuous.len(), count);
            assert!(
                continuous
                    .iter()
                    .all(|quad| quad.position == [11.0, 2.0, 3.0])
            );
        }

        file.binders[0]
            .properties_start
            .as_mut()
            .unwrap()
            .position
            .x = Some(curve(&[(0, 2.0)]));
        let offset_runtime = VfxRuntime::with_bind_points(&file, &points);
        let mut offset_playback = VfxPlayback::new(offset_runtime.clone());
        assert_eq!(offset_playback.fallback_reason(), None);
        for (delta, count) in [(0.0, 1), (10.0, 2), (10.0, 3)] {
            if delta > 0.0 {
                step(&mut offset_playback, delta);
            }
            let staged = quads(&offset_playback);
            assert_eq!(staged.len(), count);
            assert!(staged.iter().all(|quad| quad.position == [13.0, 2.0, 3.0]));
            let mut continuous = Vec::new();
            offset_runtime.sample(
                offset_playback.state.as_ref().unwrap().elapsed_frames / 30.0,
                &mut continuous,
            );
            assert_eq!(continuous.len(), count);
            assert!(
                continuous
                    .iter()
                    .all(|quad| quad.position == [13.0, 2.0, 3.0])
            );
        }

        file.timelines[0].items[0].binder_index = 0;
        let doubled = VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points));
        assert_eq!(doubled.fallback_reason(), None);
        assert_eq!(quads(&doubled)[0].position, [13.0, 2.0, 3.0]);
        file.timelines[0].items[0].binder_index = -1;
        file.timelines[0].binder_index = 256;
        assert_eq!(
            VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points)).fallback_reason(),
            None
        );
        file.timelines[0].binder_index = 0;
        file.binders[0].data.as_mut().unwrap().spring_strength = Some(curve(&[(0, 0.5)]));
        assert_eq!(
            VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points)).fallback_reason(),
            Some("staged playback: Timeline loop Binder")
        );
        file.binders[0].data.as_mut().unwrap().spring_strength = Some(curve(&[(0, 1.0)]));
        file.binders[0]
            .properties_start
            .as_mut()
            .unwrap()
            .position
            .x = Some(curve(&[(0, 0.0), (10, 1.0)]));
        assert_eq!(
            VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points)).fallback_reason(),
            Some("staged playback: Timeline loop Binder")
        );
        file.binders[0]
            .properties_start
            .as_mut()
            .unwrap()
            .position
            .x = None;
        file.binders[0]
            .properties_start
            .as_mut()
            .unwrap()
            .binder_name = "j_kao".into();
        assert_eq!(
            VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points)).fallback_reason(),
            Some("staged playback: Timeline loop Binder")
        );
    }

    #[test]
    fn nonloop_timeline_binder_is_inherited_by_unbound_items() {
        let mut file = fixture();
        file.global.revised_position = [-7.0, 0.0, 0.0];
        file.timelines[0].binder_index = 0;
        file.binders.push(AvfxBinder {
            bind_point_id: 4,
            life: -1,
            ..Default::default()
        });
        let points = [VfxBindPoint {
            parent_bone: None,
            id: 4,
            translate: [10.0, 2.0, 3.0],
            rotate: [0.0, 0.0, std::f32::consts::FRAC_PI_2],
        }];

        for timeline_binder in [0, 256] {
            file.timelines[0].binder_index = timeline_binder;
            for item_binder in [-1, -2, 255, 254] {
                file.timelines[0].items[0].binder_index = item_binder;
                let runtime = VfxRuntime::with_bind_points(&file, &points);
                let mut continuous = Vec::new();
                runtime.sample(0.0, &mut continuous);
                assert_eq!(continuous.len(), 1);
                assert_eq!(continuous[0].position, [10.0, 2.0, 3.0]);

                let value = VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points));
                assert_eq!(value.fallback_reason(), None);
                assert_eq!(quads(&value)[0].position, [10.0, 2.0, 3.0]);
                let root = &value.state.as_ref().unwrap().roots[0];
                assert_eq!(root.base.position, [10.0, 2.0, 3.0]);
                let transformed = root.base.transform_point([1.0, 0.0, 0.0]);
                near(transformed[0], 11.0);
                near(transformed[1], 2.0);
                assert_eq!(root.direction, [0.0; 3]);
            }
        }

        file.timelines[0].binder_index = 255;
        file.timelines[0].items[0].binder_index = 255;
        assert_eq!(quads(&playback(&file))[0].position, [-7.0, 0.0, 0.0]);
    }

    #[test]
    fn static_double_point_binder_uses_inner_target_without_compounding_outer() {
        let mut file = fixture();
        file.timelines[0].binder_index = 0;
        file.timelines[0].items[0].binder_index = 1;
        file.emitters[0].position.x = Some(curve(&[(0, 1.0)]));
        let point_binder = |id, offset| AvfxBinder {
            bind_point_id: id,
            life: -1,
            transform_scale: 255,
            properties_start: Some(AvfxBinderProperties {
                bind_target_point_type: 3,
                bind_point_id: id,
                coord_update_frame: -1,
                position: AvfxCurve3Axis {
                    x: Some(curve(&[(0, offset)])),
                    ..Default::default()
                },
                ..Default::default()
            }),
            data: Some(AvfxBinderData {
                spring_strength: Some(curve(&[(0, 1.0)])),
                ..Default::default()
            }),
            ..Default::default()
        };
        file.binders = vec![point_binder(4, 3.0), point_binder(7, 2.0)];
        let points = [
            VfxBindPoint {
                parent_bone: None,
                id: 4,
                translate: [50.0, 0.0, 0.0],
                rotate: [0.0, 0.0, std::f32::consts::FRAC_PI_2],
            },
            VfxBindPoint {
                parent_bone: None,
                id: 7,
                translate: [1.0, 10.0, 0.0],
                rotate: [0.0, 0.0, -std::f32::consts::FRAC_PI_2],
            },
        ];
        let runtime = VfxRuntime::with_bind_points(&file, &points);
        let mut playback = VfxPlayback::new(runtime.clone());
        assert_eq!(playback.fallback_reason(), None);
        for seconds in [0.0, 1.0 / super::super::AVFX_FPS] {
            if seconds > 0.0 {
                playback.advance(seconds).unwrap();
            }
            for quad in quads(&playback) {
                near(quad.position[0], 4.0);
                near(quad.position[1], 10.0);
            }
            let mut continuous = Vec::new();
            runtime.sample(seconds, &mut continuous);
            assert!(!continuous.is_empty());
            for quad in continuous {
                near(quad.position[0], 4.0);
                near(quad.position[1], 10.0);
            }
        }

        for (outer_scale, inner_scale) in [(1, 255), (255, 1), (1, 1), (257, 257)] {
            file.binders[0].transform_scale = outer_scale;
            file.binders[1].transform_scale = inner_scale;
            let playback = VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points));
            assert_eq!(
                playback.fallback_reason(),
                None,
                "bTSc={outer_scale}/{inner_scale}"
            );
            let position = quads(&playback)[0].position;
            near(position[0], 4.0);
            near(position[1], 10.0);
            near(position[2], 0.0);
        }
        file.binders[0].transform_scale = 256;
        assert_eq!(
            VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points)).fallback_reason(),
            Some("staged playback: unsupported Timeline Binder")
        );
        file.binders[0].transform_scale = 255;
        file.binders[1].transform_scale = 0;
        assert_eq!(
            VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points)).fallback_reason(),
            Some("staged playback: Timeline and Item Binder combination")
        );
        file.binders[1].transform_scale = 255;

        file.binders[1].data.as_mut().unwrap().spring_strength = Some(curve(&[(0, 1.0), (6, 0.5)]));
        assert_eq!(
            VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points)).fallback_reason(),
            Some("staged playback: Timeline and Item Binder combination")
        );

        file.binders[0]
            .properties_start
            .as_mut()
            .unwrap()
            .position
            .x = None;
        file.binders[1] = file.binders[0].clone();
        file.binders[1].data.as_mut().unwrap().spring_strength = Some(curve(&[(2, 1.0), (6, 0.1)]));
        let mut baseline = file.clone();
        baseline.binders[1].data.as_mut().unwrap().spring_strength = Some(curve(&[(0, 1.0)]));
        let mut spring = VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points));
        let mut static_target = VfxPlayback::new(VfxRuntime::with_bind_points(&baseline, &points));
        assert_eq!(spring.fallback_reason(), None);
        for delta in [0.0, 1.0, 1.0, 3.0, 0.0, 6.0] {
            if delta > 0.0 {
                step(&mut spring, delta);
                step(&mut static_target, delta);
            }
            assert_eq!(quads(&spring), quads(&static_target));
        }

        file.binders[1]
            .properties_start
            .as_mut()
            .unwrap()
            .bind_point_id = 7;
        file.binders[1].bind_point_id = 7;
        let mut other_target_baseline = baseline.clone();
        other_target_baseline.binders[1]
            .properties_start
            .as_mut()
            .unwrap()
            .bind_point_id = 7;
        other_target_baseline.binders[1].bind_point_id = 7;
        let mut spring = VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points));
        let mut static_target = VfxPlayback::new(VfxRuntime::with_bind_points(
            &other_target_baseline,
            &points,
        ));
        assert_eq!(spring.fallback_reason(), None);
        assert_eq!(
            spring.state.as_ref().unwrap().roots[0].base.position,
            [1.0, 10.0, 0.0]
        );
        for delta in [0.0, 1.0, 1.0, 3.0, 0.0, 6.0] {
            if delta > 0.0 {
                step(&mut spring, delta);
                step(&mut static_target, delta);
            }
            assert_eq!(quads(&spring), quads(&static_target));
        }

        file.binders[1]
            .properties_start
            .as_mut()
            .unwrap()
            .bind_point_id = 4;
        assert_eq!(
            VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points)).fallback_reason(),
            Some("staged playback: Timeline and Item Binder combination")
        );
        file.binders[1] = baseline.binders[0].clone();
        file.binders[1].data.as_mut().unwrap().spring_strength = Some(curve(&[(2, 1.0), (6, 0.1)]));
        file.binders[1]
            .properties_start
            .as_mut()
            .unwrap()
            .position
            .x = Some(curve(&[(0, -0.01)]));
        assert_eq!(
            VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points)).fallback_reason(),
            Some("staged playback: unsupported dynamic Point parent history")
        );
        file.binders[1]
            .properties_start
            .as_mut()
            .unwrap()
            .position
            .x = None;
        file.binders[1]
            .data
            .as_mut()
            .unwrap()
            .spring_strength
            .as_mut()
            .unwrap()
            .keys[0]
            .z = 0.5;
        assert_eq!(
            VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points)).fallback_reason(),
            Some("staged playback: Timeline and Item Binder combination")
        );
    }

