    #[test]
    fn dynamic_point_offset_uses_each_input_spring_without_disabled_target_rotation() {
        let mut file = dynamic_point_offset_fixture(false, false);
        let points = [VfxBindPoint {
            parent_bone: None,
            id: 4,
            translate: [5.0, 10.0, 0.0],
            rotate: [0.0, 0.0, std::f32::consts::FRAC_PI_2],
        }];
        let mut value = VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points));
        assert_eq!(value.fallback_reason(), None);
        for (frame, expected_x) in [(0.0, 4.0), (1.0, 3.5), (2.0, 3.25)] {
            if frame > 0.0 {
                step(&mut value, 1.0);
            }
            let root = &value.state.as_ref().unwrap().roots[0];
            near(root.base.position[1], 10.0);
            near(root.base.position[0], expected_x);
            near(quads(&value)[0].position[0], expected_x);
        }
        file.emitters[0].particle_items[0].parent_influence_coord = 3;
        assert_eq!(
            VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points)).fallback_reason(),
            Some("staged playback: unsupported dynamic Point parent history")
        );
        file.emitters[0].particle_items[0].parent_influence_coord = 2;
        file.emitters[0].particle_items[0].influence_coord_unstickiness = 0.25;
        assert_eq!(
            VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points)).fallback_reason(),
            Some("staged playback: unsupported dynamic Point parent history")
        );
        file.emitters[0].particle_items[0].influence_coord_unstickiness = 0.0;
        file.timelines[0].items[0].end_time = 10;
        assert_eq!(
            VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points)).fallback_reason(),
            Some("staged playback: unsupported dynamic Point parent history")
        );
        file.timelines[0].items[0].end_time = -1;
        file.particles[0].particle_type = Some(ParticleType::Laser);
        assert_eq!(
            VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points)).fallback_reason(),
            Some("staged playback: unsupported dynamic Point parent history")
        );
        file.particles[0].particle_type = Some(ParticleType::Quad);
        file.binders[1]
            .properties_start
            .as_mut()
            .unwrap()
            .position
            .x = Some(curve(&[(0, -1.0), (1, -2.0)]));
        assert_eq!(
            VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points)).fallback_reason(),
            Some("staged playback: Timeline and Item Binder combination")
        );
    }

    #[test]
    fn dynamic_point_powder_uses_birth_or_current_root_position_by_binding() {
        let points = [VfxBindPoint {
            parent_bone: None,
            id: 4,
            translate: [5.0, 10.0, 0.0],
            rotate: [0.0, 0.0, std::f32::consts::FRAC_PI_2],
        }];
        for bind_parent in [false, true] {
            let file = dynamic_point_offset_fixture(true, bind_parent);
            let mut value = VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points));
            assert_eq!(value.fallback_reason(), None);
            assert!(quads(&value).is_empty());
            step(&mut value, 1.0);
            let initial = quads(&value);
            assert_eq!(initial.len(), 1);
            near(initial[0].position[0], 3.5);
            step(&mut value, 1.0);
            let later = quads(&value);
            assert_eq!(later.len(), 2);
            near(later[0].position[0], if bind_parent { 3.25 } else { 3.5 });
            step(&mut value, 2.0);
            step(&mut value, 1.0);
            let after_second_birth = quads(&value);
            assert_eq!(after_second_birth.len(), 2);
            near(
                after_second_birth[0].position[0],
                if bind_parent { 3.0625 } else { 3.5 },
            );
            near(
                after_second_birth[1].position[0],
                if bind_parent { 3.0625 } else { 3.25 },
            );
            for _ in 0..40 {
                step(&mut value, 1.0);
            }
            assert_eq!(value.state.as_ref().unwrap().roots[0].history.len(), 1);
        }

        let mut infinite_powder = dynamic_point_offset_fixture(true, false);
        infinite_powder.particles[0].life.value = -1.0;
        assert_eq!(
            VfxPlayback::new(VfxRuntime::with_bind_points(&infinite_powder, &points))
                .fallback_reason(),
            Some("staged playback: unsupported dynamic Point parent history")
        );
    }

    #[test]
    fn fixed_linear_initial_query_failure_never_creates_phantom_root_children() {
        let mut file = fixture();
        file.timelines[0].items[0].binder_index = 0;
        let properties = |id| AvfxBinderProperties {
            bind_target_point_type: 3,
            bind_point_id: id,
            coord_update_frame: -1,
            ..Default::default()
        };
        file.binders.push(AvfxBinder {
            binder_type: 1,
            bind_point_id: 4,
            life: -1,
            transform_scale: 255,
            properties_start: Some(properties(4)),
            properties_goal: Some(properties(7)),
            data: Some(AvfxBinderData {
                carry_over_factor: Some(curve(&[(0, 0.5)])),
                ..Default::default()
            }),
            ..Default::default()
        });
        let points = [
            VfxBindPoint {
                parent_bone: None,
                id: 4,
                translate: [10.0, 0.0, 0.0],
                rotate: [0.0; 3],
            },
            VfxBindPoint {
                parent_bone: None,
                id: 7,
                translate: [0.0, 10.0, 0.0],
                rotate: [0.0; 3],
            },
        ];
        for mask in 0..4 {
            let selected: Vec<_> = points
                .iter()
                .enumerate()
                .filter(|(i, _)| mask & (1 << i) != 0)
                .map(|(_, p)| p.clone())
                .collect();
            let runtime = VfxRuntime::with_bind_points(&file, &selected);
            let ready = mask == 3;
            assert_eq!(runtime.fixed_linear_child_ready(0), ready);
            let mut staged = VfxPlayback::new(runtime.clone());
            assert_eq!(staged.fallback_reason(), None);
            assert_eq!(
                staged.state.as_ref().unwrap().roots.len(),
                usize::from(ready)
            );
            let mut time = 0.0;
            for delta in [0.0, 0.1, 0.2] {
                time += delta;
                step(&mut staged, delta);
                let mut continuous = Vec::new();
                runtime.sample(time, &mut continuous);
                assert_eq!(!continuous.is_empty(), ready, "continuous mask {mask}");
                assert_eq!(!quads(&staged).is_empty(), ready, "staged mask {mask}");
            }
        }
    }

    #[test]
    fn static_linear_item_binder_uses_local_blend_and_direction() {
        let mut file = fixture();
        file.timelines[0].items[0].binder_index = 0;
        file.binders.push(AvfxBinder {
            binder_type: 1,
            bind_point_id: 4,
            life: -1,
            transform_scale: 255,
            properties_start: Some(AvfxBinderProperties {
                bind_target_point_type: 3,
                bind_point_id: 4,
                coord_update_frame: -1,
                ..Default::default()
            }),
            properties_goal: Some(AvfxBinderProperties {
                bind_target_point_type: 3,
                bind_point_id: 7,
                coord_update_frame: -1,
                ..Default::default()
            }),
            data: Some(AvfxBinderData {
                carry_over_factor: Some(curve(&[(0, 0.5)])),
                ..Default::default()
            }),
            ..Default::default()
        });
        let points = [
            VfxBindPoint {
                parent_bone: None,
                id: 4,
                translate: [10.0, 0.0, 0.0],
                rotate: [0.0; 3],
            },
            VfxBindPoint {
                parent_bone: None,
                id: 7,
                translate: [0.0, 10.0, 0.0],
                rotate: [0.0, 0.0, std::f32::consts::FRAC_PI_2],
            },
        ];
        let mut blended = VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points));
        assert_eq!(blended.fallback_reason(), None);
        let root = &blended.state.as_ref().unwrap().roots[0];
        assert_eq!(root.base.position, [5.0, 5.0, 0.0]);
        assert_eq!(root.direction, [-10.0, 10.0, 0.0]);
        near(root.base.transform_point([1.0, 0.0, 0.0])[0], 6.0);
        near(root.base.transform_point([1.0, 0.0, 0.0])[1], 5.0);

        let mut at_start = file.clone();
        at_start.binders[0]
            .data
            .as_mut()
            .unwrap()
            .carry_over_factor
            .as_mut()
            .unwrap()
            .keys[0]
            .z = 0.0;
        let mut start = VfxPlayback::new(VfxRuntime::with_bind_points(&at_start, &points));
        let mut observed_shift = false;
        for delta in [0.0, 0.1, 0.0, 0.2] {
            step(&mut blended, delta);
            step(&mut start, delta);
            observed_shift |= quads(&blended) != quads(&start);
            assert_eq!(blended.fallback_reason(), None);
            assert_eq!(start.fallback_reason(), None);
        }
        assert!(observed_shift);

        file.binders[0].data.as_mut().unwrap().carry_over_factor =
            Some(curve(&[(0, 0.5), (6, 0.2)]));
        assert_eq!(
            VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points)).fallback_reason(),
            Some("staged playback: unsupported Item Binder")
        );
        file.binders[0].data.as_mut().unwrap().carry_over_factor = Some(curve(&[(0, 0.5)]));
        file.binders[0]
            .properties_start
            .as_mut()
            .unwrap()
            .position
            .x = Some(curve(&[(0, 0.1)]));
        assert_eq!(
            VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points)).fallback_reason(),
            Some("staged playback: unsupported Item Binder")
        );
        file.binders[0]
            .properties_start
            .as_mut()
            .unwrap()
            .position
            .x = None;
        file.timelines[0].binder_index = 0;
        assert_eq!(
            VfxPlayback::new(VfxRuntime::with_bind_points(&file, &points)).fallback_reason(),
            Some("staged playback: unsupported Timeline Binder")
        );
    }

