    #[test]
    fn timeline_item_targets_use_signed_low_byte() {
        let mut file = fixture();
        let item = &mut file.timelines[0].items[0];
        item.emitter_index = 256;
        item.effector_index = 254;
        item.clip_index = 253;

        let mut continuous = Vec::new();
        VfxRuntime::new(&file).sample(0.0, &mut continuous);
        assert_eq!(continuous.len(), 1);
        let value = VfxPlayback::new(VfxRuntime::new(&file));
        assert_eq!(value.fallback_reason(), None);
        assert_eq!(quads(&value).len(), 1);

        file.timelines[0].items[0].emitter_index = 254;
        let value = VfxPlayback::new(VfxRuntime::new(&file));
        assert_eq!(value.fallback_reason(), None);
        assert!(quads(&value).is_empty());

        file.timelines[0].items[0].emitter_index = 256;
        file.timelines[0].items[0].clip_index = 256;
        let value = VfxPlayback::new(VfxRuntime::new(&file));
        assert_eq!(value.fallback_reason(), None);
        assert_eq!(quads(&value).len(), 1);
        file.timelines[0].items[0].emitter_index = 255;
        assert_eq!(
            VfxPlayback::new(VfxRuntime::new(&file)).fallback_reason(),
            Some("staged playback: Timeline Clip reference")
        );
        file.timelines[0].items[0].clip_index = 255;
        file.timelines[0].items[0].effector_index = 256;
        assert_eq!(
            VfxPlayback::new(VfxRuntime::new(&file)).fallback_reason(),
            Some("Timeline[0]: invalid effector reference")
        );

        file.effectors.push(AvfxEffector::default());
        let value = VfxPlayback::new(VfxRuntime::new(&file));
        assert_eq!(value.fallback_reason(), None);
        assert!(quads(&value).is_empty());
        let mut continuous = Vec::new();
        VfxRuntime::new(&file).sample(0.0, &mut continuous);
        assert!(continuous.is_empty());
        file.effectors.push(AvfxEffector {
            affect_other_vfx: true,
            ..Default::default()
        });
        file.timelines[0].items[0].effector_index = 257;
        assert_eq!(
            VfxPlayback::new(VfxRuntime::new(&file)).fallback_reason(),
            Some("Timeline[0]: staged playback excludes VFX-affecting effector")
        );
    }

