    #[test]
    fn kill_targets_repeated_trigger_slots_and_keeps_scheduler_boundaries() {
        let mut file = kill_fixture(4, 2, true, false);
        file.schedulers[0].items[0].enabled = false;
        file.schedulers[0].triggers[3].timeline_index = 1;
        file.schedulers[0].triggers[4].timeline_index = 1;
        file.timelines[0].clips[0].raw_ints = Some([4, -4, 0, 0]);
        let mut other = file.schedulers[0].clone();
        other.items.clear();
        file.schedulers.push(other);
        let mut value = shared_trigger_playback(&file);
        for (scheduler, number) in [(0, 4), (0, 4), (0, 5), (1, 4)] {
            assert!(value.trigger_document(scheduler, number).unwrap());
        }
        value
            .state
            .as_mut()
            .unwrap()
            .advance(&value.runtime, 0.0)
            .unwrap();
        let state = value.state.as_ref().unwrap();
        for parent in state
            .timeline_parents
            .iter()
            .filter(|p| p.scheduler_identity.1 >= 0)
        {
            let selected = parent.scheduler_index == Some(0) && parent.scheduler_identity.1 == 3;
            let timeline = parent.child.unwrap();
            assert_eq!(
                timeline.numeric.fade.duration,
                if selected { 4.0 } else { 0.0 }
            );
            assert_eq!(
                timeline.raw_flags() & 0x40380000,
                if selected { 0x40300000 } else { 0 }
            );
        }
        assert_eq!(state.timeline_parents.len(), 5);
    }

    #[test]
    fn kill_selects_timeline_under_outer_point_and_delayed_item_inherits_self_only() {
        let mut file = kill_fixture(4, 2, true, false);
        file.binders = binder_factory_fixture(true, 50, 3, 100).binders;
        let mut outer = file.binders[0].clone();
        outer.properties_start.as_mut().unwrap().generate_delay = 0;
        file.binders.push(outer);
        file.timelines[1].binder_index = 1;
        file.timelines[1].items[0].binder_index = 0;
        let mut value = shared_trigger_playback(&file);
        for delta in [0.0, 2.0] {
            value
                .state
                .as_mut()
                .unwrap()
                .advance(&value.runtime, delta)
                .unwrap();
        }
        let state = value.state.as_ref().unwrap();
        let parent = state
            .timeline_parents
            .iter()
            .find(|p| p.scheduler_identity == (0, -1))
            .unwrap();
        assert_eq!(
            parent
                .point
                .as_ref()
                .unwrap()
                .instance
                .lifecycle
                .numeric
                .fade
                .duration,
            0.0,
            "selection starts at Timeline below Scheduler Point"
        );
        assert_eq!(parent.child.unwrap().numeric.fade.age, 2.0);
        assert_eq!(binder_lifecycle(&state.roots[0]).numeric.fade.age, 2.0);
        assert_eq!(state.instances.root_id(0), None);
        value
            .state
            .as_mut()
            .unwrap()
            .advance(&value.runtime, 1.0)
            .unwrap();
        let state = value.state.as_ref().unwrap();
        let nodes = state.instances.common_tree_states(0);
        assert_eq!(nodes.len(), 2);
        assert_eq!(nodes[0].numeric.fade.duration, 4.0);
        assert_eq!(
            nodes[0].numeric.fade.age, 2.0,
            "new emitter copies Point before parent's separate Numeric"
        );
        assert_eq!(nodes[0].numeric.alpha, 0.4);
        assert_eq!(
            nodes[1].flags & 0x40380000,
            0,
            "grandchild initialized before parent inheritance"
        );
        assert_eq!(nodes[1].numeric.alpha, 0.6);
        assert_eq!(binder_lifecycle(&state.roots[0]).numeric.fade.age, 3.0);
    }

