    #[test]
    fn rest_document_request_is_deferred_and_creates_no_clip() {
        for value in [-0.0, 0.0, 2.0] {
            let file = rest_fixture(value);
            let mut playback = shared_trigger_playback(&file);
            playback
                .state
                .as_mut()
                .unwrap()
                .advance(&playback.runtime, 7.0)
                .unwrap();
            let old_id = playback
                .state
                .as_ref()
                .unwrap()
                .instances
                .root_id(0)
                .unwrap();
            assert!(playback.trigger_document(0, 1).unwrap());
            playback
                .state
                .as_mut()
                .unwrap()
                .advance(&playback.runtime, 1.5)
                .unwrap();
            let state = playback.state.as_ref().unwrap();
            assert!(state.document_reset_pending);
            assert_eq!(state.document_generation, 0);
            assert_eq!(state.elapsed_frames, 8.5);
            assert_eq!(state.instances.root_id(0), Some(old_id));
            assert!(state.timeline_parents.iter().all(|p| p.clips.is_empty()));
            assert!(
                !quads(&playback).is_empty(),
                "request does not retire the old tree"
            );
            playback
                .state
                .as_mut()
                .unwrap()
                .advance(&playback.runtime, 0.0)
                .unwrap();
            let state = playback.state.as_ref().unwrap();
            assert_eq!(state.document_generation, 1);
            assert_eq!(state.elapsed_frames, 0.0);
            assert!(!state.document_reset_pending);
            assert_eq!(
                state.timeline_parents.len(),
                1,
                "external target is destroyed"
            );
            assert!(state.instances.root_id(0).unwrap() > old_id);
        }
    }

    #[test]
    fn rest_document_preserves_framework_remainder_and_process_random_state() {
        let file = rest_fixture(-0.0);
        let mut playback = shared_trigger_playback(&file);
        playback.advance(0.0).unwrap();
        playback
            .state
            .as_mut()
            .unwrap()
            .client_random
            .get_mut()
            .state = [1, 2, 3, 4];
        playback
            .state
            .as_mut()
            .unwrap()
            .client_random
            .get_mut()
            .next_u16();
        assert!(playback.trigger_document(0, 1).unwrap());
        playback.advance(0.003).unwrap();
        assert!(playback.state.as_ref().unwrap().document_reset_pending);
        let random = playback
            .state
            .as_ref()
            .unwrap()
            .client_random
            .borrow()
            .state;
        let old_update = playback.state.as_ref().unwrap().instances.input_update();
        let mut expected_clock = FrameworkClock {
            remainder: playback.clock.remainder,
        };
        let frames = expected_clock.advance(0.001).unwrap();
        playback.advance(0.001).unwrap();
        assert_eq!(
            playback.clock.remainder.to_bits(),
            expected_clock.remainder.to_bits()
        );
        assert_eq!(playback.seconds, f64::from(0.003f32) + f64::from(0.001f32));
        assert_eq!(
            playback.state.as_ref().unwrap().elapsed_frames.to_bits(),
            frames.to_bits()
        );
        assert_eq!(
            playback.state.as_ref().unwrap().instances.input_update(),
            old_update + 1
        );
        assert_eq!(
            playback
                .state
                .as_ref()
                .unwrap()
                .client_random
                .borrow()
                .state,
            random
        );
        assert_eq!(playback.document_generation(), Some(1));
        playback.sample(&mut Vec::new(), &mut Vec::new());
        assert!(playback.update_to(playback.seconds as f32));
        assert_eq!(playback.document_generation(), Some(1));
        playback.reset();
        assert_eq!(playback.document_generation(), Some(0));
    }

    #[test]
    fn rest_coalesces_requests_and_discards_old_external_targets_and_unlocks() {
        let file = rest_fixture(0.0);
        let mut playback = shared_trigger_playback(&file);
        playback
            .state
            .as_mut()
            .unwrap()
            .advance(&playback.runtime, 0.0)
            .unwrap();
        assert!(playback.trigger_document(0, 1).unwrap());
        assert!(playback.trigger_document(0, 1).unwrap());
        playback
            .state
            .as_mut()
            .unwrap()
            .advance(&playback.runtime, 1.0)
            .unwrap();
        let state = playback.state.as_mut().unwrap();
        state.scheduler_unlocked.insert(0);
        let serial = state.external_trigger_serial;
        assert!(
            playback.trigger_document(0, 1).unwrap(),
            "old tree still accepts input"
        );
        playback
            .state
            .as_mut()
            .unwrap()
            .advance(&playback.runtime, 0.0)
            .unwrap();
        let state = playback.state.as_ref().unwrap();
        assert_eq!(state.document_generation, 1);
        assert!(!state.document_reset_pending);
        assert_eq!(state.timeline_parents.len(), 1);
        assert!(state.scheduler_unlocked.is_empty());
        assert_eq!(state.external_trigger_serial, serial + 1);
        assert!(playback.trigger_document(0, 1).unwrap());
        playback
            .state
            .as_mut()
            .unwrap()
            .advance(&playback.runtime, 0.0)
            .unwrap();
        assert!(playback.state.as_ref().unwrap().document_reset_pending);
    }

