    #[test]
    fn rest_ordinary_restarts_release_old_instances_and_do_not_accumulate_roots() {
        let mut file = rest_fixture(0.0);
        file.schedulers[0].items.push(AvfxSchedulerItem {
            enabled: true,
            start_time: 0,
            timeline_index: 0,
        });
        let mut playback = shared_trigger_playback(&file);
        let mut previous_id = None;
        for generation in 0..64 {
            playback.advance(1.0 / 30.0).unwrap();
            assert_eq!(playback.fallback_reason(), None);
            let state = playback.state.as_ref().unwrap();
            assert_eq!(state.document_generation, generation);
            assert!(state.document_reset_pending);
            assert_eq!(state.timeline_parents.len(), 2);
            assert_eq!(state.roots.len(), 1);
            assert_eq!(state.instances.common_tree_states(0).len(), 2);
            let id = state.instances.root_id(0).unwrap();
            assert!(previous_id.is_none_or(|previous| id > previous));
            previous_id = Some(id);
        }
    }

