    #[test]
    fn rest_invalid_storage_diagnostics_precede_deletion_and_counter_mutation() {
        for retired in [false, true] {
            let mut file = retired_rest_fixture(if retired { 1 } else { 0 }, 1, 2);
            if retired {
                let source = &mut file.timelines[0];
                let mut end = source.items[0];
                end.clip_index = 1;
                source.items.insert(0, end);
                source.clips.push(AvfxTimelineClip {
                    clip_type: Some(AvfxTimelineClipType::End),
                    ..Default::default()
                });
            }
            let mut value = shared_trigger_playback(&file);
            if !retired {
                value.runtime.file.schedulers[0].item_count = Some(0);
            }
            let error = value
                .state
                .as_mut()
                .unwrap()
                .advance(&value.runtime, 0.0)
                .unwrap_err();
            assert_eq!(
                error,
                if retired {
                    "staged playback: REST retired Scheduler retains freed registered storage"
                } else {
                    "staged playback: REST self-deletion leaves freed Timeline storage"
                }
            );
            let state = value.state.as_ref().unwrap();
            assert_eq!(scheduler_registered_children(&state.timeline_parents, 0), 3);
            assert!(state.timeline_parents.iter().all(|p| p.child.is_some()));
            assert_eq!(state.scheduler_ordinary[0].flags & 511, 0);
            // The public adapter reports this through its whole-file fallback,
            // rather than returning a partially mutated tree to sampling.
            value = shared_trigger_playback(&file);
            if !retired {
                value.runtime.file.schedulers[0].item_count = Some(0);
            }
            value.advance(0.0).unwrap();
            assert_eq!(value.fallback_reason(), Some(error.as_str()));
            assert!(value.state.is_none());
        }
    }

