    #[test]
    fn rest_replacement_inherits_scheduler_cached_fade_before_numeric() {
        let mut file = retired_rest_fixture(1, 2, 1);
        file.timelines[0].items[0].start_time = 3;
        let mut value = shared_trigger_playback(&file);
        value.advance(0.0).unwrap();
        value.configure_scheduler_fade(0, 4, 2, false).unwrap();
        value.advance(1.0 / 30.0).unwrap();
        assert_eq!(
            value.state.as_ref().unwrap().scheduler_ordinary[0]
                .numeric
                .fade
                .age,
            1.0
        );
        value.runtime.file.schedulers[0].items[1].timeline_index = 1;
        value.advance(2.0 / 30.0).unwrap();
        assert_eq!(value.fallback_reason(), None);
        let state = value.state.as_ref().unwrap();
        let child = state
            .timeline_parents
            .iter()
            .find(|p| p.scheduler_identity == (1, -1))
            .unwrap()
            .child
            .unwrap();
        assert_eq!(state.scheduler_ordinary[0].numeric.fade.age, 3.0);
        assert_eq!(child.raw_flags() & 0x180000, 0x100000);
        assert_eq!(child.numeric.fade.age, 1.0);
        assert_eq!(child.scaled_delta, 0.0);
        assert_eq!(child.numeric.alpha, 0.75);
        assert_eq!(child.consumed_mask(), u32::MAX);
    }

