    #[test]
    #[ignore = "CPU: requires scripts/probe-item-rest-walk.py exact-client Scheduler observations"]
    fn compare_original_item_rest_with_actual_owned_playback() {
        use serde_json::json;
        let output =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target/weapon-vfx-audit");
        let original: serde_json::Value = serde_json::from_slice(
            &std::fs::read(output.join("item-rest-walk-client-probe.json")).unwrap(),
        )
        .unwrap();
        let cases = original["cases"].as_array().unwrap();
        assert_eq!(cases.len(), 270);
        let mut node_states = 0;
        for (ordinal, case) in cases.iter().enumerate() {
            let item = AvfxTimelineItem {
                enabled: true,
                start_time: 0,
                end_time: 30,
                emitter_index: -1,
                effector_index: 0,
                binder_index: -1,
                clip_index: -1,
                platform: 0,
            };
            let mut source = AvfxTimeline {
                binder_index: -1,
                items: vec![item; 2],
                ..Default::default()
            };
            source.items[0].effector_index = -1;
            source.items[0].clip_index = 0;
            source.clip_count = 1;
            let target = case["target"].as_i64().unwrap() as i32;
            source.clips.push(AvfxTimelineClip {
                clip_type: Some(AvfxTimelineClipType::Reset),
                raw_ints: Some([
                    0,
                    target.wrapping_add(1),
                    if case["repeats"] == 2 {
                        target.wrapping_add(1)
                    } else {
                        0
                    },
                    0,
                ]),
                raw_floats: Some([-1.0, 0.0, 0.0, 0.0]),
                ..Default::default()
            });
            let fresh = AvfxTimeline {
                binder_index: -1,
                items: vec![item; case["newCount"].as_u64().unwrap() as usize],
                ..Default::default()
            };
            let sibling = AvfxTimeline {
                binder_index: -1,
                items: vec![item],
                ..Default::default()
            };
            let file = AvfxFile {
                timelines: vec![source, fresh, sibling],
                effectors: vec![AvfxEffector {
                    affect_other_vfx: false,
                    affect_game: true,
                    ..Default::default()
                }],
                schedulers: vec![AvfxScheduler {
                    items: (0..3)
                        .map(|i| AvfxSchedulerItem {
                            enabled: true,
                            start_time: 0,
                            timeline_index: if i == 0 { 0 } else { 2 },
                        })
                        .collect(),
                    ..Default::default()
                }],
                ..Default::default()
            };
            let mut value = shared_trigger_playback(&file);
            // Like the native fixture, retain constructed old definitions but
            // point all compiled mappings at definition 1, disabled/late.
            for mapping in &mut value.runtime.file.schedulers[0].items {
                mapping.timeline_index = 1;
                mapping.enabled = false;
                mapping.start_time = 80;
            }
            let age = f32::from_bits(case["inputAge"].as_u64().unwrap() as u32);
            let order = [[0, 1, 2], [1, 0, 2], [1, 2, 0]][case["order"].as_u64().unwrap() as usize];
            for (position, slot) in order.into_iter().enumerate() {
                let parent = &mut value.state.as_mut().unwrap().timeline_parents[slot];
                parent.prepare_order = position;
                let clock = &mut parent.child.as_mut().unwrap().clock;
                clock.local_age = age;
                clock.total_age = age;
                clock.previous_age = age;
                clock.nominal_life = 31.0;
            }
            value
                .state
                .as_mut()
                .unwrap()
                .advance(&value.runtime, 0.0)
                .unwrap();
            let state = value.state.as_ref().unwrap();
            let mut parents = state.timeline_parents.iter().collect::<Vec<_>>();
            parents.sort_by_key(|p| p.prepare_order);
            let observed = parents
                .iter()
                .enumerate()
                .map(|(i, p)| {
                    let slot = p.scheduler_identity.0;
                    let source = if p
                        .definition
                        .items
                        .first()
                        .is_some_and(|i| i.clip_index == 0)
                    {
                        0
                    } else if slot == target && (0..3).contains(&target) {
                        1
                    } else {
                        2
                    };
                    json!({"slot":slot, "age":p.child.unwrap().clock.local_age.to_bits(),
                    "consumed":p.child.unwrap().consumed_mask(), "definition":source,
                    "next":parents.get(i + 1).map_or(-1, |p| p.scheduler_identity.0)})
                })
                .collect::<Vec<_>>();
            assert_eq!(
                observed,
                *case["final"].as_array().unwrap(),
                "case {ordinal} final tree"
            );
            assert!(!state.document_reset_pending);
            assert!(!state.document_ended);
            assert!(state.roots.is_empty());
            assert!(state.timeline_parents.iter().all(|p| p.clips.is_empty()));
            node_states += observed.len();
        }
        std::fs::write(output.join("item-rest-owned-rust-comparison.json"),
            serde_json::to_string_pretty(&json!({"cases":cases.len(),"finalNodeStates":node_states,
                "differences":0,"productionOwnedPlaybackCompared":true,
                "scope":"Actual StagedPlayback REST dispatch, deletion/reconstruction and live registration. Initial definitions/order/ages and remapped disabled/late mappings controlled to match native fixture. Final identity/age/mask/definition/next order, no Clip/Document reset compared; downstream game Effector/no-op factory and host controlled. No Point, retired Scheduler, invalid-index deletion, full host or GPU."})).unwrap()).unwrap();
    }

    #[test]
    fn rest_matches_oldest_registered_item_before_due_pending_duplicate() {
        let mut file = rest_fixture(-1.0);
        file.schedulers[0].items[0].start_time = 5;
        let mut value = shared_trigger_playback(&file);
        value.trigger_document(0, 1).unwrap();
        value.advance(0.0).unwrap();
        let old_id = value.state.as_ref().unwrap().instances.root_id(0).unwrap();
        assert_eq!(quads(&value).len(), 1);
        // A second trigger is registered BEFORE the pending ordinary Item is
        // due. Scheduler dispatch appends that pending factory at time five;
        // REST must still delete the previously registered ordinary instance.
        value.trigger_document(0, 1).unwrap();
        value
            .state
            .as_mut()
            .unwrap()
            .advance(&value.runtime, 5.0)
            .unwrap();
        let state = value.state.as_ref().unwrap();
        assert_eq!(quads(&value).len(), 2);
        assert_eq!(state.roots.len(), 2);
        assert!((0..state.roots.len()).all(|i| state.instances.root_id(i) != Some(old_id)));
        let mut live = state
            .timeline_parents
            .iter()
            .filter(|p| p.scheduler_identity == (0, -1))
            .collect::<Vec<_>>();
        live.sort_by_key(|p| p.prepare_order);
        assert_eq!(live.len(), 2);
        assert!(live.iter().all(|p| p.child.unwrap().clock.local_age == 0.0));
        assert!(!state.document_reset_pending);
    }

    #[test]
    fn rest_point_replacement_drops_old_roots_and_uses_current_target() {
        let mut file = rest_fixture(-1.0);
        file.binders = binder_factory_fixture(true, 30, 0, -1).binders;
        file.timelines[1].binder_index = 0;
        file.timelines[0].items[0].binder_index = 127;
        let mut terminal = file.emitters[0].particle_items[0].clone();
        terminal.create_time = 2;
        terminal.create_count = 4;
        file.emitters[0].particle_items.push(terminal);
        let mut value = shared_trigger_playback(&file);
        value.advance(0.0).unwrap();
        let old_id = value.state.as_ref().unwrap().instances.root_id(0).unwrap();
        value.runtime.binder_targets = Some(point_targets(35.0));
        value.trigger_document(0, 1).unwrap();
        value.advance(0.0).unwrap();
        let state = value.state.as_ref().unwrap();
        assert_eq!(state.roots.len(), 1);
        assert_ne!(state.instances.root_id(0), Some(old_id));
        assert_eq!(quads(&value).len(), 1);
        near(quads(&value)[0].position[0], 35.0);
        assert!(
            state
                .timeline_parents
                .iter()
                .any(|p| p.point.is_some() && p.scheduler_identity == (0, -1))
        );
        assert!(!state.document_reset_pending);
    }

