    #[test]
    fn rest_self_replacement_rejects_native_freed_storage_boundaries_before_deletion() {
        for variant in 1..=4 {
            let mut file = rest_self_fixture();
            file.binders = binder_factory_fixture(true, 30, 0, -1).binders;
            file.timelines[0].binder_index = if variant == 4 { -1 } else { 0 };
            let mut value = shared_trigger_playback(&file);
            // Start old Timeline without dispatch, as in the native fixture.
            let state = value.state.as_mut().unwrap();
            let old = state.timeline_parents[0].child.unwrap();
            if variant == 1 {
                value.runtime.file.binders[0]
                    .properties_start
                    .as_mut()
                    .unwrap()
                    .generate_delay = 5;
            }
            if variant == 2 {
                value.runtime.binder_targets = Some(Vec::new());
            }
            if variant == 3 {
                value.runtime.file.timelines[0].binder_index = -1;
            }
            if variant == 4 {
                value.runtime.file.timelines[0].binder_index = 0;
            }
            assert_eq!(
                state.advance(&value.runtime, 0.0).unwrap_err(),
                "staged playback: REST self-replacement leaves freed Timeline storage"
            );
            assert_eq!(state.timeline_parents.len(), 1);
            assert_eq!(
                state.timeline_parents[0].binder_index,
                if variant == 4 { None } else { Some(0) }
            );
            assert_eq!(state.timeline_parents[0].child.unwrap().clock, old.clock);
            assert!(!state.document_reset_pending);
        }
    }

    #[test]
    #[ignore = "CPU: requires scripts/probe-item-rest-point.py exact-client Point ownership observations"]
    fn compare_original_item_rest_point_with_owned_playback() {
        use serde_json::json;
        let output =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target/weapon-vfx-audit");
        let original: serde_json::Value = serde_json::from_slice(
            &std::fs::read(output.join("item-rest-point-client-probe.json")).unwrap(),
        )
        .unwrap();
        fn normalized(node: &serde_json::Value) -> serde_json::Value {
            let mut value = node.clone();
            let o = value.as_object_mut().unwrap();
            o.remove("slot");
            o.remove("next");
            o.insert(
                "children".into(),
                json!(
                    node["children"]
                        .as_array()
                        .unwrap()
                        .iter()
                        .map(normalized)
                        .collect::<Vec<_>>()
                ),
            );
            value
        }
        let mut compared = 0;
        let mut nodes = 0;
        for (ordinal, case) in original["cases"].as_array().unwrap().iter().enumerate() {
            let item = AvfxTimelineItem {
                enabled: true,
                start_time: 0,
                end_time: 30,
                emitter_index: -1,
                effector_index: 0,
                binder_index: -1,
                clip_index: -1,
                platform: 0,
            };
            let mut source = AvfxTimeline {
                binder_index: -1,
                items: vec![item; 2],
                ..Default::default()
            };
            source.items[0].effector_index = -1;
            source.items[0].clip_index = 0;
            source.clip_count = 1;
            source.clips.push(AvfxTimelineClip {
                clip_type: Some(AvfxTimelineClipType::Reset),
                raw_ints: Some([0, 1, if case["repeats"] == 2 { 1 } else { 0 }, 0]),
                raw_floats: Some([-1.0, 0.0, 0.0, 0.0]),
                ..Default::default()
            });
            let fresh = AvfxTimeline {
                binder_index: if case["freshPoint"] == 1 { 1 } else { -1 },
                items: vec![item],
                ..Default::default()
            };
            let old = AvfxTimeline {
                binder_index: 0,
                items: vec![item],
                ..Default::default()
            };
            let mut binder = binder_factory_fixture(true, -1, 0, -1).binders.remove(0);
            binder.properties_start.as_mut().unwrap().generate_delay =
                if case["ready"] == 1 { 0 } else { 5 };
            let mut fresh_binder = binder.clone();
            fresh_binder
                .properties_start
                .as_mut()
                .unwrap()
                .generate_delay = case["delay"].as_i64().unwrap() as i32;
            let mut mappings = vec![];
            if case["present"] == 1 {
                mappings.push(AvfxSchedulerItem {
                    enabled: true,
                    start_time: 0,
                    timeline_index: 2,
                });
            }
            mappings.push(AvfxSchedulerItem {
                enabled: true,
                start_time: 0,
                timeline_index: 0,
            });
            let file = AvfxFile {
                timelines: vec![source, fresh, old],
                binders: vec![binder, fresh_binder],
                effectors: vec![AvfxEffector {
                    affect_other_vfx: false,
                    affect_game: true,
                    ..Default::default()
                }],
                schedulers: vec![AvfxScheduler {
                    items: mappings,
                    ..Default::default()
                }],
                ..Default::default()
            };
            let mut value = shared_trigger_playback(&file);
            value.runtime.file.schedulers[0].items = vec![AvfxSchedulerItem {
                enabled: false,
                start_time: 80,
                timeline_index: 1,
            }];
            if case["querySuccess"] == 0 {
                value.runtime.binder_targets = Some(Vec::new());
            }
            let state = value.state.as_mut().unwrap();
            for p in &mut state.timeline_parents {
                let is_source = p.definition.items.len() == 2;
                p.prepare_order = if case["order"] == 0 {
                    usize::from(!is_source)
                } else {
                    usize::from(is_source)
                };
                if is_source {
                    p.scheduler_identity = (1, -1);
                    let clock = &mut p.child.as_mut().unwrap().clock;
                    clock.local_age = 2.5;
                    clock.total_age = 2.5;
                    clock.previous_age = 2.5;
                    clock.nominal_life = 31.0;
                }
            }
            state.advance(&value.runtime, 0.0).unwrap();
            let mut live = state.timeline_parents.iter().collect::<Vec<_>>();
            live.sort_by_key(|p| p.prepare_order);
            let timeline_node = |p: &TimelineRootState| {
                let child = p.child.unwrap();
                json!({"kind":3,"age":child.clock.local_age.to_bits(),"delay":0,"flags":child.raw_flags(),"children":[],"definition":if p.definition.items.len()==2 {0}else{1},"ordinary":p.scheduler_identity.0,"consumed":child.consumed_mask()})
            };
            let observed=live.iter().map(|p|if let Some(point)=&p.point {let life=point.instance.lifecycle;json!({"kind":9,"age":life.clock.local_age.to_bits(),"delay":life.clock.delay.to_bits(),"flags":life.raw_flags(),"children":if p.child.is_some() {vec![timeline_node(p)]}else{vec![]}})}else{timeline_node(p)}).collect::<Vec<_>>();
            let expected = case["final"]
                .as_array()
                .unwrap()
                .iter()
                .map(normalized)
                .collect::<Vec<_>>();
            assert_eq!(observed, expected, "case {ordinal}");
            assert!(state.roots.is_empty());
            assert!(!state.document_reset_pending);
            nodes += observed.len()
                + live
                    .iter()
                    .filter(|p| p.point.is_some() && p.child.is_some())
                    .count();
            compared += 1;
        }
        assert_eq!(compared, 128);
        // Two additional original fixtures execute immediate Point self-reuse
        // and full Time -> Prepare across a delayed zero-life Point factory.
        for variant in [0, 5] {
            let native: serde_json::Value = serde_json::from_slice(
                &std::fs::read(output.join(format!("item-rest-point-self-{variant}.json")))
                    .unwrap(),
            )
            .unwrap();
            let item = AvfxTimelineItem {
                enabled: true,
                start_time: 0,
                end_time: 30,
                emitter_index: -1,
                effector_index: 0,
                binder_index: -1,
                clip_index: -1,
                platform: 0,
            };
            let mut source = AvfxTimeline {
                binder_index: 0,
                items: vec![item; if variant == 0 { 2 } else { 1 }],
                ..Default::default()
            };
            if variant == 0 {
                source.items[0].effector_index = -1;
                source.items[0].clip_index = 0;
                source.clip_count = 1;
                source.clips.push(AvfxTimelineClip {
                    clip_type: Some(AvfxTimelineClipType::Reset),
                    raw_ints: Some([0, 1, 0, 0]),
                    raw_floats: Some([-1.0, 0.0, 0.0, 0.0]),
                    ..Default::default()
                });
            }
            let fresh = AvfxTimeline {
                binder_index: 1,
                items: vec![item],
                ..Default::default()
            };
            let binder = binder_factory_fixture(
                true,
                if variant == 5 { 0 } else { -1 },
                if variant == 5 { 5 } else { 0 },
                -1,
            )
            .binders
            .remove(0);
            let file = AvfxFile {
                timelines: vec![source, fresh],
                binders: vec![binder.clone(), binder],
                effectors: vec![AvfxEffector {
                    affect_other_vfx: false,
                    affect_game: true,
                    ..Default::default()
                }],
                schedulers: vec![AvfxScheduler {
                    items: vec![AvfxSchedulerItem {
                        enabled: true,
                        start_time: 0,
                        timeline_index: 0,
                    }],
                    ..Default::default()
                }],
                ..Default::default()
            };
            let mut value = shared_trigger_playback(&file);
            if variant == 0 {
                value.runtime.file.schedulers[0].items[0].timeline_index = 1;
            }
            let state = value.state.as_mut().unwrap();
            if variant == 0 {
                let parent = &mut state.timeline_parents[0];
                let c = &mut parent.child.as_mut().unwrap().clock;
                c.local_age = 2.5;
                c.total_age = 2.5;
                c.previous_age = 2.5;
                let c = &mut parent.point.as_mut().unwrap().instance.lifecycle.clock;
                c.local_age = 2.5;
                c.total_age = 2.5;
                c.previous_age = 2.5;
            } else {
                let p = &state.timeline_parents[0]
                    .point
                    .as_ref()
                    .unwrap()
                    .instance
                    .lifecycle;
                assert_eq!(p.raw_flags() & 511, 1);
                assert_eq!(
                    p.life_limit_enabled,
                    native["initialLifeEnabled"].as_bool().unwrap()
                );
            }
            state
                .advance(&value.runtime, if variant == 5 { 5.0 } else { 0.0 })
                .unwrap();
            assert_eq!(state.timeline_parents.len(), 1);
            let p = &state.timeline_parents[0];
            let point = p.point.as_ref().unwrap().instance.lifecycle;
            let child = p.child.unwrap();
            let observed = json!({"kind":9,"age":point.clock.local_age.to_bits(),"delay":point.clock.delay.to_bits(),"flags":point.raw_flags(),"children":[{"kind":3,"age":child.clock.local_age.to_bits(),"delay":0,"flags":child.raw_flags(),"children":[],"definition":1,"ordinary":0,"consumed":child.consumed_mask()}]});
            assert_eq!(
                observed,
                normalized(&native["final"][0]),
                "additional variant {variant}"
            );
            if variant == 5 {
                assert_eq!(
                    point.life_limit_enabled,
                    native["finalLifeEnabled"].as_bool().unwrap()
                );
            }
            nodes += 2;
            compared += 1;
        }

        std::fs::write(output.join("item-rest-point-rust-comparison.json"),serde_json::to_string_pretty(&json!({"cases":compared,"finalSemanticNodeStates":nodes,"originalMatrixCases":128,"immediatePointSelfReuseCases":1,"pendingPointLifeGateCases":1,"differences":0,"productionOwnedPlaybackCompared":true,"scope":"Actual Point/direct deletion/rebuild and ordered final ownership, kind/age/delay/flags/inner masks. Controlled old definitions/order/ages, listener target success and game Effector. Native physical pool slot numbers and per-factory visits omitted; includes immediate same-class Point self-reuse and zero-life delayed factory gate. No multi-target Binder, unsafe self branches, full Emitter resources/host/GPU."})).unwrap()).unwrap();
    }

    #[test]
    #[ignore = "CPU: requires scripts/probe-item-rest-pending.py exact-client pending factory observations"]
    fn compare_original_item_rest_pending_factory_with_owned_playback() {
        use serde_json::json;
        let output =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target/weapon-vfx-audit");
        let original: serde_json::Value = serde_json::from_slice(
            &std::fs::read(output.join("item-rest-pending-client-probe.json")).unwrap(),
        )
        .unwrap();
        let mut compared = 0;
        let mut node_states = 0;
        for (ordinal, case) in original["cases"].as_array().unwrap().iter().enumerate() {
            // Scheduler mode 2/3 and raw pending bit masks are a separate
            // Common lifecycle contract; this comparison covers mode zero.
            if case["mode"] != 0 {
                continue;
            }
            let item = AvfxTimelineItem {
                enabled: true,
                start_time: 0,
                end_time: 30,
                emitter_index: -1,
                effector_index: 0,
                binder_index: -1,
                clip_index: -1,
                platform: 0,
            };
            let mut source = AvfxTimeline {
                binder_index: -1,
                items: vec![item; 2],
                ..Default::default()
            };
            source.items[0].effector_index = -1;
            source.items[0].clip_index = 0;
            source.clip_count = 1;
            source.clips.push(AvfxTimelineClip {
                clip_type: Some(AvfxTimelineClipType::Reset),
                raw_ints: Some([0, 1, if case["repeats"] == 2 { 1 } else { 0 }, 0]),
                raw_floats: Some([-1.0, 0.0, 0.0, 0.0]),
                ..Default::default()
            });
            let fresh = AvfxTimeline {
                binder_index: -1,
                items: vec![item],
                ..Default::default()
            };
            let file = AvfxFile {
                timelines: vec![source, fresh.clone(), fresh],
                effectors: vec![AvfxEffector {
                    affect_other_vfx: false,
                    affect_game: true,
                    ..Default::default()
                }],
                schedulers: vec![AvfxScheduler {
                    items: vec![
                        AvfxSchedulerItem {
                            enabled: true,
                            start_time: 0,
                            timeline_index: 2,
                        },
                        AvfxSchedulerItem {
                            enabled: true,
                            start_time: 0,
                            timeline_index: 0,
                        },
                    ],
                    ..Default::default()
                }],
                ..Default::default()
            };
            let mut value = shared_trigger_playback(&file);
            let start = case["start"].as_i64().unwrap() as f32;
            let age = f32::from_bits(case["inputAge"].as_u64().unwrap() as u32);
            // Preserve the two controlled old definitions/identities from the
            // native fixture, then remap ordinary index zero for reconstruction.
            value.runtime.file.schedulers[0].items = vec![AvfxSchedulerItem {
                enabled: case["enabled"] == 1,
                start_time: start as i32,
                timeline_index: 1,
            }];
            let mut pending = TimelineRootState::new(
                &value.runtime,
                &value.runtime.file.timelines[1],
                None,
                Some(0),
                start,
                2,
                false,
            )
            .unwrap();
            pending.constructed = false;
            pending.child = None;
            pending.scheduler_identity = (0, -1);
            let state = value.state.as_mut().unwrap();
            state.scheduler_ordinary[0] =
                super::super::scheduler_ordinary::SchedulerOrdinaryState {
                    flags: 0x3f000001,
                    consumed: !1,
                    life_limit_enabled: false,
                    active: true,
                    clock: super::super::VfxBinderBirthClock::new(age, -1, 0.0),
                    scaled_delta: 0.0,
                    numeric: super::super::VfxCommonNumericState::default(),
                    linked: true,
                };
            state.elapsed_frames = age;
            for (index, parent) in state.timeline_parents.iter_mut().enumerate() {
                parent.prepare_order = if case["order"] == 0 { 1 - index } else { index };
                let clock = &mut parent.child.as_mut().unwrap().clock;
                clock.local_age = age;
                clock.total_age = age;
                clock.previous_age = age;
                clock.nominal_life = 31.0;
            }
            if case["enabled"] == 1 {
                state.timeline_parents.push(pending);
            }
            state.advance(&value.runtime, 0.0).unwrap();
            let mut live = state
                .timeline_parents
                .iter()
                .enumerate()
                .filter(|(_, p)| p.constructed)
                .collect::<Vec<_>>();
            live.sort_by_key(|(_, p)| p.prepare_order);
            let pool_slot = |i: usize| [1, 0, 2][i];
            let observed = live.iter().enumerate().map(|(i,(slot,p))|json!({"slot":pool_slot(*slot),"age":p.child.unwrap().clock.local_age.to_bits(),"consumed":p.child.unwrap().consumed_mask(),"definition":if p.definition.items.len()==2 {0}else if p.definition==value.runtime.file.timelines[2] && p.prepare_order<2 {2}else{1},"next":live.get(i+1).map_or(-1,|(slot,_)|pool_slot(*slot))})).collect::<Vec<_>>();
            assert_eq!(
                observed,
                *case["final"].as_array().unwrap(),
                "case {ordinal}"
            );
            assert!(!state.document_reset_pending);
            assert!(state.roots.is_empty());
            node_states += observed.len();
            compared += 1;
        }
        assert_eq!(compared, 96);
        std::fs::write(output.join("item-rest-pending-rust-comparison.json"),serde_json::to_string_pretty(&json!({"cases":compared,"finalNodeStates":node_states,"differences":0,"productionOwnedPlaybackCompared":true,"scope":"Actual pending construction/tail registration before REST sibling walk, oldest duplicate selection and repeated direct replacement. Controlled initial definitions/ages/order and pending placeholder; mode zero only. No full Scheduler mask/constructor/mode lifecycle, Point/retired storage, host or GPU."})).unwrap()).unwrap();
    }

    #[test]
    fn scheduler_end_consumes_due_factories_and_reaps_empty_storage_with_pending_work() {
        for end_age in [0, 5] {
            let mut file = trigger_fixture(AvfxTimelineClipType::End, [0; 4], end_age);
            file.schedulers.push(AvfxScheduler {
                items: vec![AvfxSchedulerItem {
                    enabled: true,
                    start_time: 5,
                    timeline_index: 1,
                }],
                ..Default::default()
            });
            let mut value = shared_trigger_playback(&file);
            step(&mut value, end_age as f32);
            let state = value.state.as_ref().unwrap();
            assert!(state.document_ended);
            let scheduler = &state.scheduler_ordinary[1];
            assert!(scheduler.linked && scheduler.retired());
            assert_eq!(scheduler.flags & 511, u32::from(end_age == 0));
            assert_eq!(scheduler.life_limit_enabled, end_age == 5);
            assert_eq!(scheduler.active, end_age == 0);
            assert!(
                !state
                    .timeline_parents
                    .iter()
                    .any(|p| p.scheduler_index == Some(1) && p.child.is_some())
            );
            value.advance(0.0).unwrap();
            let state = value.state.as_ref().unwrap();
            assert!(!state.scheduler_ordinary[1].linked);
            assert_eq!(
                state.scheduler_ordinary[1].flags & 511,
                u32::from(end_age == 0)
            );
            assert!(
                !state
                    .timeline_parents
                    .iter()
                    .any(|p| p.scheduler_index == Some(1))
            );
            assert!(quads(&value).is_empty());
        }
    }

    #[test]
    fn scheduler_life_expiry_freezes_self_and_reaps_children_before_owner() {
        let file = AvfxFile {
            timelines: vec![AvfxTimeline {
                binder_index: -1,
                ..Default::default()
            }],
            schedulers: vec![AvfxScheduler {
                items: vec![AvfxSchedulerItem {
                    enabled: true,
                    start_time: 0,
                    timeline_index: 0,
                }],
                ..Default::default()
            }],
            ..Default::default()
        };
        let mut value = shared_trigger_playback(&file);
        value.state.as_mut().unwrap().scheduler_ordinary[0]
            .clock
            .nominal_life = 1.0;
        step(&mut value, 2.5);
        let state = value.state.as_ref().unwrap();
        let s = &state.scheduler_ordinary[0];
        assert!(s.retired() && s.linked);
        assert_eq!(
            (s.clock.local_age, s.clock.total_age, s.clock.previous_age),
            (1.0, 2.5, 2.5)
        );
        assert!(!state.document_ended);
        assert_eq!(s.flags & 0x3fe00, 512);
        assert!(state.timeline_parents[0].child.unwrap().retired());
        step(&mut value, 2.0);
        let state = value.state.as_ref().unwrap();
        let s = &state.scheduler_ordinary[0];
        assert!(
            s.linked,
            "Scheduler tested before its last child was destroyed"
        );
        assert_eq!(
            (s.clock.local_age, s.clock.total_age, s.clock.previous_age),
            (1.0, 2.5, 4.5)
        );
        assert_eq!(s.flags & 0x3fe00, 0);
        assert!(state.timeline_parents.is_empty());
        value.advance(0.0).unwrap();
        assert!(!value.state.as_ref().unwrap().scheduler_ordinary[0].linked);
    }

