    #[test]
    #[ignore = "CPU: requires scripts/probe-scheduler-lifecycle.py exact-client tree observations"]
    fn compare_original_scheduler_lifecycle_with_owned_playback() {
        use super::super::scheduler_ordinary::SchedulerOrdinaryState;
        use serde_json::{Value, json};
        let output =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target/weapon-vfx-audit");
        let original: Value = serde_json::from_slice(
            &std::fs::read(output.join("scheduler-lifecycle-client-probe.json")).unwrap(),
        )
        .unwrap();
        fn clock(
            flags: u32,
            c: super::super::VfxBinderBirthClock,
            delta: f32,
            gate: bool,
        ) -> Value {
            json!({"flags":flags,"age":c.local_age.to_bits(),"total":c.total_age.to_bits(),"previous":c.previous_age.to_bits(),"delta":delta.to_bits(),"lifeEnabled":gate})
        }
        fn snapshot(
            schedulers: &[SchedulerOrdinaryState],
            parents: &[TimelineRootState],
            calls: usize,
            rejected: usize,
        ) -> Value {
            let mut occupied = 0;
            let schedulers = schedulers.iter().enumerate().filter(|(_,s)|s.linked).map(|(group,s)| {
                occupied += 1;
                let mut children = parents.iter().filter(|p|p.scheduler_index==Some(group) && p.child.is_some()).collect::<Vec<_>>();
                children.sort_by_key(|p|p.prepare_order);
                occupied += children.len();
                let children = children.iter().map(|p| {
                    let n=p.child.unwrap();
                    json!({"identity":p.scheduler_identity.0,"clock":clock(n.raw_flags(),n.clock,n.scaled_delta,n.life_limit_enabled()),"consumed":n.consumed_mask(),"active":n.dispatch_active()})
                }).collect::<Vec<_>>();
                json!({"group":group,"clock":clock(s.flags,s.clock,s.scaled_delta,s.life_limit_enabled),"consumed":s.consumed,"active":s.active,"children":children})
            }).collect::<Vec<_>>();
            json!({"schedulers":schedulers,"freeCount":8-occupied,"factoryCalls":calls,"rejectedFactories":rejected})
        }
        fn expected(v: &Value) -> Value {
            let mut v = v.clone();
            v.as_object_mut().unwrap().remove("document");
            v
        }
        fn dispatch(
            runtime: &VfxRuntime,
            roots: &[Root],
            parents: &mut Vec<TimelineRootState>,
            schedulers: &mut [SchedulerOrdinaryState],
            calls: &mut usize,
            rejected: &mut usize,
        ) {
            for (group, s) in schedulers.iter_mut().enumerate() {
                let pending = s.flags & 511;
                let retired = s.retired();
                dispatch_ordinary_scheduler(
                    runtime,
                    group,
                    s.clock.local_age,
                    s,
                    roots,
                    parents,
                    None,
                )
                .unwrap();
                let n = ((pending - (s.flags & 511)) & 511) as usize;
                *calls += n;
                if retired {
                    *rejected += n;
                }
            }
        }
        let mut compared = 0;
        let mut snapshots = 0;
        let mut inputs = 0;
        for (ordinal, case) in original["cases"].as_array().unwrap().iter().enumerate() {
            let count = case["count"].as_u64().unwrap() as usize;
            // The production allocator has no artificial capacity8 exhaustion.
            // Count33 stays covered by the independent real-pool oracle.
            if count == 33 {
                continue;
            }
            let start = case["start"].as_i64().unwrap() as i32;
            let file = AvfxFile {
                timelines: vec![AvfxTimeline {
                    binder_index: -1,
                    ..Default::default()
                }],
                schedulers: (0..2)
                    .map(|group| AvfxScheduler {
                        items: (0..if group == 0 { count } else { 2 })
                            .map(|i| AvfxSchedulerItem {
                                enabled: true,
                                start_time: if group == 0 { start } else { i as i32 * 5 },
                                timeline_index: 0,
                            })
                            .collect(),
                        ..Default::default()
                    })
                    .collect(),
                ..Default::default()
            };
            let mut value = shared_trigger_playback(&file);
            let state = value.state.as_mut().unwrap();
            // Native starts immediately after ctor; optional +60 initialization
            // is separate. Reset only controlled initial storage/host settings.
            for p in &mut state.timeline_parents {
                p.constructed = false;
                p.child = None;
                p.ended = false;
                p.prepared_input = None;
            }
            state.scheduler_ordinary = file
                .schedulers
                .iter()
                .map(SchedulerOrdinaryState::new)
                .collect();
            for s in &mut state.scheduler_ordinary {
                s.clock.nominal_life = f32::from_bits(case["life"].as_u64().unwrap() as u32);
                s.flags |= (case["mode"].as_u64().unwrap() as u32) << 19;
                if case["timeEnabled"] == false {
                    s.flags &= !0x1000000;
                }
            }
            let mut calls = 0;
            let mut rejected = 0;
            if case["initialized"] == true {
                dispatch(
                    &value.runtime,
                    &state.roots,
                    &mut state.timeline_parents,
                    &mut state.scheduler_ordinary,
                    &mut calls,
                    &mut rejected,
                );
            }
            assert_eq!(
                snapshot(
                    &state.scheduler_ordinary,
                    &state.timeline_parents,
                    calls,
                    rejected
                ),
                expected(&case["initial"]),
                "case {ordinal} initial"
            );
            snapshots += 1;
            for (tick, phase) in case["inputs"].as_array().unwrap().iter().enumerate() {
                let delta = f32::from_bits(phase["delta"].as_u64().unwrap() as u32);
                state.instances.begin_input_update().unwrap();
                let input_update = state.instances.input_update();
                let input_end = state.elapsed_frames + delta;
                let mut order = state
                    .timeline_parents
                    .iter()
                    .enumerate()
                    .filter(|(_, p)| p.constructed)
                    .map(|(i, p)| (p.scheduler_index.unwrap(), p.prepare_order, true, i))
                    .collect::<Vec<_>>();
                order.sort_by_key(|e| (e.0, e.1));
                let mut operations = trace::OPERATION_LIMIT;
                state
                    .instances
                    .update_with_budget_custom_phases(
                        &file,
                        delta,
                        &mut operations,
                        |step, preparation| {
                            if step == trace::VfxTracePhase::Advance {
                                advance_owned_tree(
                                    &value.runtime,
                                    delta,
                                    input_end,
                                    input_update,
                                    &mut state.roots,
                                    &mut state.timeline_parents,
                                    &order,
                                    &mut state.scheduler_ordinary,
                                    &mut state.document_ended,
                                    preparation,
                                )?;
                                assert_eq!(
                                    snapshot(
                                        &state.scheduler_ordinary,
                                        &state.timeline_parents,
                                        calls,
                                        rejected
                                    ),
                                    expected(&phase["afterTime"]),
                                    "case {ordinal} tick {tick} after Time"
                                );
                                if case["endAt"].as_i64().unwrap() == tick as i64 {
                                    state.document_ended = true;
                                    end_document_tree(
                                        &mut state.roots,
                                        &mut state.timeline_parents,
                                        &mut state.scheduler_ordinary,
                                        preparation,
                                    )?;
                                }
                                assert_eq!(
                                    snapshot(
                                        &state.scheduler_ordinary,
                                        &state.timeline_parents,
                                        calls,
                                        rejected
                                    ),
                                    expected(&phase["beforePrepare"]),
                                    "case {ordinal} tick {tick} before Prepare"
                                );
                            } else if step == trace::VfxTracePhase::Prepare {
                                dispatch(
                                    &value.runtime,
                                    &state.roots,
                                    &mut state.timeline_parents,
                                    &mut state.scheduler_ordinary,
                                    &mut calls,
                                    &mut rejected,
                                );
                                for p in &mut state.timeline_parents {
                                    if p.child.is_some() {
                                        assert!(
                                            p.prepare(&value.runtime, input_end, input_update)?
                                                .is_none()
                                        );
                                    }
                                }
                                assert_eq!(
                                    snapshot(
                                        &state.scheduler_ordinary,
                                        &state.timeline_parents,
                                        calls,
                                        rejected
                                    ),
                                    expected(&phase["afterPrepare"]),
                                    "case {ordinal} tick {tick} after Prepare"
                                );
                            }
                            // Native probe does not execute Numeric; compare same phases.
                            Ok(())
                        },
                    )
                    .unwrap();
                state.elapsed_frames = input_end;
                inputs += 1;
                snapshots += 3;
            }
            compared += 1;
        }
        assert_eq!(compared, 864);
        std::fs::write(output.join("scheduler-lifecycle-owned-comparison.json"),serde_json::to_vec_pretty(&json!({"cases":compared,"inputs":inputs,"phaseSnapshots":snapshots,"differences":0,"productionOwnedPlaybackCompared":true,"scope":"Actual Scheduler self Time, ordered child Time/destruction, recursive Document END and ordinary factory/attachment with zero-Item Timeline children. Exact live Scheduler/child order, flags, clocks, gates, masks, callback activity and occupancy match original native pool. Controlled initial clock/mode/host settings and optional zero-delta initialization; Document phase routing supplied, Numeric omitted. Physical slot addresses and count33 capacity failures excluded; no full Document constructor/Prepare, Binder/Emitter resources, live host or GPU."})).unwrap()).unwrap();
    }

    fn scheduler_fade_fixture() -> AvfxFile {
        AvfxFile {
            timelines: vec![AvfxTimeline {
                binder_index: -1,
                ..Default::default()
            }],
            schedulers: vec![AvfxScheduler {
                items: vec![
                    AvfxSchedulerItem {
                        enabled: true,
                        start_time: 0,
                        timeline_index: 0,
                    },
                    AvfxSchedulerItem {
                        enabled: true,
                        start_time: 2,
                        timeline_index: 0,
                    },
                ],
                ..Default::default()
            }],
            ..Default::default()
        }
    }

    #[test]
    fn scheduler_fade_control_waits_for_numeric_and_late_attachment_keeps_cached_age() {
        let file = scheduler_fade_fixture();
        let mut value = shared_trigger_playback(&file);
        let input = value.state.as_ref().unwrap().instances.input_update();
        assert!(value.configure_scheduler_fade(0, 4, 5, false).unwrap());
        let state = value.state.as_ref().unwrap();
        assert_eq!(state.instances.input_update(), input);
        assert_eq!(state.elapsed_frames, 0.0);
        assert_eq!(state.scheduler_ordinary[0].numeric.alpha, 1.0);
        assert_eq!(state.scheduler_ordinary[0].flags & 511, 1);
        let pending = state
            .timeline_parents
            .iter()
            .find(|p| !p.constructed)
            .unwrap();
        assert!(
            pending.child.is_none(),
            "future definitions are not registered descendants"
        );
        step(&mut value, 0.5);
        assert_eq!(
            value.state.as_ref().unwrap().scheduler_ordinary[0]
                .numeric
                .alpha,
            0.125
        );
        step(&mut value, 1.5);
        let state = value.state.as_ref().unwrap();
        assert_eq!(
            state.scheduler_ordinary[0].numeric.alpha, 0.0625,
            "no-op provider preserves previous alpha"
        );
        let late = state
            .timeline_parents
            .iter()
            .find(|p| p.scheduler_identity == (1, -1))
            .unwrap()
            .child
            .unwrap();
        assert_eq!(late.clock.local_age, 0.0);
        assert_eq!(late.scaled_delta, 0.0);
        assert_eq!(
            late.numeric.fade.age, 0.5,
            "attachment preceded this input's owner Numeric"
        );
        assert_eq!(
            late.numeric.alpha, 0.125,
            "owner alpha is not copied at attachment"
        );
    }

