    fn compare_original_owned_control_trees(
        prefix: &str,
        clip_type: AvfxTimelineClipType,
        expected_cases: usize,
    ) {
        let fadi = clip_type == AvfxTimelineClipType::FadeIn;
        let ullp = clip_type == AvfxTimelineClipType::UnlockLoopPoint;
        let flag_mask = if ullp { 0xfffc0000 } else { 0x7f3c0000 };
        let directory =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target/weapon-vfx-audit");
        let original: serde_json::Value = serde_json::from_slice(
            &std::fs::read(directory.join(format!("{prefix}-client-probe.json"))).unwrap(),
        )
        .unwrap();
        let mut finite = 0usize;
        let mut nan = 0usize;
        let cases = original["cases"].as_array().unwrap();
        assert_eq!(cases.len(), expected_cases);
        let mut inputs = 0;
        for (case_index, case) in cases.iter().enumerate() {
            let duration = case["duration"].as_i64().unwrap() as i32;
            let mode = case["mode"].as_u64().unwrap() as u32;
            let flag = case["flag"].as_bool().unwrap();
            let end = case["end"].as_bool().unwrap();
            let first = case["targetFirst"].as_bool().unwrap();
            let triggered = case["triggered"].as_bool().unwrap();
            let own = case["selfTarget"].as_bool().unwrap();
            let mut file = trigger_fixture(
                clip_type,
                [
                    duration,
                    if triggered { -4 } else { 1 },
                    if own { 2 } else { 0 },
                    0,
                ],
                0,
            );
            file.timelines[0].clips[0].raw_floats = Some([
                if end { -1.0 } else { 0.0 },
                if mode == 2 { -1.0 } else { 0.0 },
                if flag { -1.0 } else { 0.0 },
                0.0,
            ]);
            file.timelines[0].items[0].end_time = 100;
            if fadi || ullp {
                file.timelines[0].items[0].start_time = 2;
            }
            file.timelines[1].items.push(AvfxTimelineItem {
                enabled: true,
                start_time: 100,
                end_time: 100,
                binder_index: -1,
                effector_index: -1,
                emitter_index: -1,
                clip_index: -1,
                platform: 0,
            });
            if ullp {
                file.timelines[0].clips[0].raw_floats = Some([
                    f32::from_bits(case["allBits"].as_u64().unwrap() as u32),
                    0.0,
                    0.0,
                    0.0,
                ]);
                file.timelines[1].loop_start = 0;
                file.timelines[1].loop_end = 3;
                file.timelines[1].items[0].end_time = 100;
                file.emitters[0].loop_start = 0;
                file.emitters[0].loop_end = 3;
                file.particles[0].loop_start = 0;
                file.particles[0].loop_end = 3;
            }
            file.emitters[0].position = Default::default();
            file.emitters[0].create_interval = curve(&[(0, 1000.0)]);
            file.emitters[0].particle_items[0].create_time = 1;
            file.emitters[0].color.alpha = Some(curve(&[(0, 0.8), (16, 2.8)]));
            file.particles[0].color.alpha = Some(curve(&[(0, 0.6), (16, 1.6)]));
            let ordinary_target = AvfxSchedulerItem {
                enabled: true,
                start_time: 0,
                timeline_index: 1,
            };
            // Ordinary identity 0 is the target, identity 1 is the controller.
            file.schedulers[0].items = vec![
                ordinary_target.clone(),
                AvfxSchedulerItem {
                    enabled: true,
                    start_time: 0,
                    timeline_index: 0,
                },
            ];
            if triggered {
                file.schedulers[0].items[0].enabled = false;
                file.schedulers[0].triggers[3].timeline_index = 1;
            }
            let mut playback = shared_trigger_playback(&file);
            if triggered {
                assert!(playback.trigger_document(0, 4).unwrap());
            }
            // Controlled constructor registration order, independently varied
            // from the stored ordinary Item/trigger identities.
            for parent in &mut playback.state.as_mut().unwrap().timeline_parents {
                let target = parent.scheduler_identity
                    == (
                        if triggered { -1 } else { 0 },
                        if triggered { 3 } else { -1 },
                    );
                parent.prepare_order = usize::from(target != first);
                if target && ullp && case["initialUnlocked"].as_bool().unwrap() {
                    parent.child.as_mut().unwrap().unlock_loop_point();
                }
                if target && fadi {
                    let mode = case["initialMode"].as_u64().unwrap() as u32;
                    if mode != 0 {
                        parent.child.as_mut().unwrap().configure_fade(
                            8,
                            mode,
                            case["initialFlag"].as_bool().unwrap(),
                        );
                    }
                }
            }
            for (step_index, step) in case["steps"].as_array().unwrap().iter().enumerate() {
                let delta = f32::from_bits(step["delta"].as_u64().unwrap() as u32);
                // Original probe supplies manager deltas, after Framework quantization.
                playback
                    .state
                    .as_mut()
                    .unwrap()
                    .advance(&playback.runtime, delta)
                    .unwrap();
                let state = playback.state.as_ref().unwrap();
                assert_eq!(
                    state.document_ended,
                    step["ended"].as_bool().unwrap(),
                    "case={case_index},step={step_index}"
                );
                if ullp {
                    assert_eq!(
                        state.scheduler_unlocked.contains(&0),
                        step["schedulerUnlocked"].as_bool().unwrap(),
                        "case={case_index},step={step_index}"
                    );
                }
                let target = state.timeline_parents.iter().find(|parent| {
                    parent.scheduler_identity
                        == (
                            if triggered { -1 } else { 0 },
                            if triggered { 3 } else { -1 },
                        )
                });
                let controller = state
                    .timeline_parents
                    .iter()
                    .find(|parent| parent.scheduler_identity == (1, -1));
                let root = state.roots.iter().enumerate().find(|(_, root)| {
                    root.timeline_parent.is_some_and(|(parent, _)| {
                        target.is_some_and(|target| {
                            std::ptr::eq(&state.timeline_parents[parent], target)
                        })
                    })
                });
                let tree = root.map_or_else(Vec::new, |(index, _)| {
                    state.instances.common_tree_states(index)
                });
                for (index, expected) in step["states"].as_array().unwrap().iter().enumerate() {
                    let timeline = match index {
                        0 => target.and_then(|p| p.child),
                        1 => controller.and_then(|p| p.child),
                        _ => None,
                    };
                    let clip = (index == 4)
                        .then(|| controller.and_then(|p| p.clips.first()))
                        .flatten();
                    let node = if index == 2 {
                        tree.first()
                    } else if index == 3 {
                        tree.get(1)
                    } else {
                        None
                    };
                    let registered = timeline.is_some() || clip.is_some() || node.is_some();
                    assert_eq!(
                        registered,
                        expected["registered"].as_bool().unwrap(),
                        "case={case_index},step={step_index},node={index},expected={expected}"
                    );
                    if !registered {
                        continue;
                    }
                    let (flags, children, numeric, delta, age, total, previous) =
                        if let Some(t) = timeline {
                            (
                                t.raw_flags(),
                                usize::from(t.registered_children()),
                                t.numeric,
                                t.scaled_delta,
                                t.clock.local_age,
                                t.clock.total_age,
                                Some(t.clock.previous_age),
                            )
                        } else if let Some(c) = clip {
                            let t = c.lifecycle;
                            (
                                t.raw_flags(),
                                usize::from(t.registered_children()),
                                t.numeric,
                                t.scaled_delta,
                                t.clock.local_age,
                                t.clock.total_age,
                                Some(t.clock.previous_age),
                            )
                        } else {
                            let n = node.unwrap();
                            (
                                n.flags, n.children, n.numeric, n.delta, n.age, n.total, None,
                            )
                        };
                    assert_eq!(
                        flags & flag_mask,
                        expected["flags"].as_u64().unwrap() as u32,
                        "case={case_index},step={step_index},node={index}"
                    );
                    assert_eq!(
                        children,
                        expected["children"].as_u64().unwrap() as usize,
                        "case={case_index},step={step_index},node={index}"
                    );
                    let mut compare = |value: f32, key: &str| {
                        let bits = expected[key].as_u64().unwrap() as u32;
                        if f32::from_bits(bits).is_nan() {
                            assert!(value.is_nan());
                            nan += 1
                        } else {
                            assert_eq!(
                                value.to_bits(),
                                bits,
                                "case={case_index},step={step_index},node={index},key={key},actual={value},expected={}",
                                f32::from_bits(bits)
                            );
                            finite += 1
                        }
                    };
                    compare(numeric.alpha, "alpha");
                    compare(numeric.fade.duration, "duration");
                    compare(numeric.fade.age, "fadeAge");
                    compare(delta, "delta");
                    compare(age, "age");
                    compare(total, "total");
                    if let Some(previous) = previous {
                        compare(previous, "previous")
                    }
                }
                inputs += 1;
            }
        }
        std::fs::write(directory.join(format!("{prefix}-comparison.json")),serde_json::to_vec_pretty(&serde_json::json!({"cases":cases.len(),"inputs":inputs,"finiteBitComparisons":finite,"nanClassifications":nan,"differences":0,"control":format!("{clip_type:?}"),"scope":"Actual StagedPlayback owner Time/Prepare/Numeric, raw KILL/FADI/ULLP parameters, ordinary Item and trigger-slot identity, registration order, cached alpha/fade/clocks, loop/unlock flags (ULLP mask) and collection versus original Common, selected KILL +08/+10, FADI +08 or ULLP +08/Common/Scheduler unlock and selectors. Constructor registration order, Timeline dispatch/factories, properties and transforms controlled; manager deltas supplied after Framework quantization, global +18 disabled. No complete original emitter factories, RNG, Clip Binder, live host or GPU/client pixels."})).unwrap()).unwrap();
    }

    #[test]
    fn end_retires_outer_and_item_binders_and_collects_each_owned_level() {
        let mut file = trigger_fixture(AvfxTimelineClipType::End, [0; 4], 3);
        file.emitters[0].create_interval = curve(&[(0, 100.0)]);
        file.binders = binder_factory_fixture(true, -1, 0, 12).binders;
        file.timelines[1].binder_index = 0;
        file.timelines[1].items[0].binder_index = 0;
        file.schedulers[0].items.insert(
            0,
            AvfxSchedulerItem {
                enabled: true,
                start_time: 0,
                timeline_index: 1,
            },
        );
        let mut value = shared_trigger_playback(&file);
        step(&mut value, 0.0);
        assert_eq!(quads(&value).len(), 1);
        step(&mut value, 3.0);
        let state = value.state.as_ref().unwrap();
        assert!(
            state.timeline_parents[0]
                .point
                .as_ref()
                .unwrap()
                .instance
                .lifecycle
                .retired()
        );
        assert!(
            state.roots[0]
                .point_binder
                .as_ref()
                .unwrap()
                .instance
                .lifecycle
                .retired()
        );
        assert!(quads(&value).is_empty());
        for _ in 0..5 {
            step(&mut value, 0.0);
        }
        let state = value.state.as_ref().unwrap();
        assert!(state.roots.is_empty());
        assert!(state.timeline_parents.is_empty());
        assert_eq!(value.fallback_reason(), None);
    }

    #[test]
    fn end_clip_retires_the_document_tree_and_rejects_same_prepare_births() {
        let mut file = trigger_fixture(AvfxTimelineClipType::End, [0; 4], 2);
        file.emitters[0].create_interval = curve(&[(0, 100.0)]);
        file.schedulers[0].items.insert(
            0,
            AvfxSchedulerItem {
                enabled: true,
                start_time: 0,
                timeline_index: 1,
            },
        );
        // This Item is due after END in the same dispatch, and this Scheduler
        // factory is due after its owner was retired. Neither may attach.
        let mut later_item = file.timelines[1].items[0].clone();
        later_item.start_time = 2;
        file.timelines[0].items.push(later_item);
        file.schedulers[0].items.push(AvfxSchedulerItem {
            enabled: true,
            start_time: 2,
            timeline_index: 1,
        });
        file.schedulers[0].triggers[0].timeline_index = 1;
        let mut value = shared_trigger_playback(&file);
        step(&mut value, 0.0);
        assert_eq!(quads(&value).len(), 1);
        let old_id = value.state.as_ref().unwrap().instances.root_id(0).unwrap();
        step(&mut value, 2.0);
        let state = value.state.as_ref().unwrap();
        assert_eq!(state.roots.len(), 1);
        assert_eq!(state.instances.root_id(0), Some(old_id));
        assert!(quads(&value).is_empty());
        assert!(
            state
                .timeline_parents
                .iter()
                .filter_map(|p| p.child)
                .all(|p| p.retired())
        );
        // END freezes local ages; it does not clamp to nominal life or erase
        // ownership. Empty descendants disappear on subsequent Time passes.
        near(
            state.timeline_parents[1].child.unwrap().clock.local_age,
            2.0,
        );
        step(&mut value, 0.0);
        assert_eq!(value.state.as_ref().unwrap().roots.len(), 1);
        step(&mut value, 0.0);
        assert!(value.state.as_ref().unwrap().roots.is_empty());
        step(&mut value, 0.0);
        assert!(value.state.as_ref().unwrap().timeline_parents.is_empty());
        assert!(!value.trigger_document(0, 1).unwrap());
        value.reset();
        step(&mut value, 0.0);
        assert_eq!(quads(&value).len(), 1);
    }

    #[test]
    fn external_document_trigger_attaches_now_and_receives_next_time_before_prepare() {
        let mut file = trigger_fixture(AvfxTimelineClipType::Trigger, [3, 0, 0, 0], 5);
        file.timelines[0].items.clear();
        file.timelines[0].clips.clear();
        // This fixture exercises external targets alone. An enabled ordinary
        // empty Timeline is still a native object and has its own lifetime.
        file.schedulers[0].items.clear();
        file.timelines[1].binder_index = 127; // Native trigger bypasses BnNo.
        file.timelines[1].items[0].start_time = 2;
        file.schedulers[0].triggers[3] = AvfxSchedulerItem {
            enabled: false,
            start_time: 99,
            timeline_index: 1,
        };
        let mut value = shared_trigger_playback(&file);
        let seconds = value.seconds;
        let input = value.state.as_ref().unwrap().instances.input_update();
        assert!(value.trigger_document(0, 4).unwrap());
        let state = value.state.as_ref().unwrap();
        assert_eq!(value.seconds, seconds);
        assert_eq!(state.instances.input_update(), input);
        assert_eq!(state.timeline_parents.len(), 1);
        near(
            state.timeline_parents[0].child.unwrap().clock.local_age,
            0.0,
        );
        assert!(state.roots.is_empty());
        assert!(quads(&value).is_empty());
        step(&mut value, 3.0);
        assert_eq!(value.fallback_reason(), None);
        let state = value.state.as_ref().unwrap();
        near(
            state.timeline_parents[0].child.unwrap().clock.local_age,
            3.0,
        );
        assert_eq!(state.roots.len(), 1);
        near(
            state
                .instances
                .particles(0)
                .next()
                .unwrap()
                .emitter_curve_age,
            1.0,
        );
        assert_eq!(quads(&value).len(), 1);
        // A later external call starts at zero despite Document elapsed time.
        assert!(value.trigger_document(0, 4).unwrap());
        let state = value.state.as_ref().unwrap();
        near(
            state
                .timeline_parents
                .last()
                .unwrap()
                .child
                .unwrap()
                .clock
                .local_age,
            0.0,
        );
        value.reset();
        assert!(value.state.as_ref().unwrap().timeline_parents.is_empty());
    }

    #[test]
    fn external_document_trigger_invalid_target_and_unsupported_clip_are_atomic() {
        let mut file = trigger_fixture(AvfxTimelineClipType::Trigger, [1, 0, 0, 0], 5);
        file.timelines[0].items.clear();
        file.timelines[0].clips.clear();
        file.schedulers[0].triggers[1].timeline_index = 100;
        file.schedulers[0].triggers[2].timeline_index = 0;
        file.timelines[0].items.push(AvfxTimelineItem {
            enabled: false,
            start_time: 0,
            end_time: 1,
            binder_index: -1,
            emitter_index: -1,
            effector_index: -1,
            clip_index: 0,
            platform: 0,
        });
        file.timelines[0].clips.push(AvfxTimelineClip {
            clip_type: Some(AvfxTimelineClipType::Kill),
            ..Default::default()
        });
        // The disabled Item is harmless at startup; activate it on the
        // trigger-only target copy to exercise complete preflight rejection.
        let mut unsupported = file.timelines[0].clone();
        unsupported.items[0].enabled = true;
        file.timelines.push(unsupported);
        file.schedulers[0].triggers[2].timeline_index = 2;
        let mut value = shared_trigger_playback(&file);
        let before = quads(&value);
        let parent_count = value.state.as_ref().unwrap().timeline_parents.len();
        let input = value.state.as_ref().unwrap().instances.input_update();
        for (scheduler, number) in [(-1, 1), (100, 1), (0, -1), (0, 1)] {
            assert!(!value.trigger_document(scheduler, number).unwrap());
        }
        for number in [0, 2, 3, 13] {
            assert!(value.trigger_document(0, number).is_err());
        }
        let state = value.state.as_ref().unwrap();
        assert_eq!(quads(&value), before);
        assert_eq!(state.timeline_parents.len(), parent_count);
        assert_eq!(state.instances.input_update(), input);
        assert_eq!(state.external_trigger_serial, 0);
        assert_eq!(value.seconds, 0.0);
        assert_eq!(value.fallback_reason(), None);
    }

    #[test]
    fn external_document_trigger_keeps_mixed_scheduler_prepare_order() {
        let mut file = trigger_fixture(AvfxTimelineClipType::Trigger, [1, 0, 0, 0], 5);
        let normal = file.timelines[1].clone();
        file.timelines = vec![normal.clone(), normal.clone(), normal];
        for index in 0..3 {
            file.timelines[index].items[0].emitter_index = index as i32;
        }
        let emitter = file.emitters[0].clone();
        file.emitters = vec![emitter.clone(), emitter.clone(), emitter];
        let particle = file.particles[0].clone();
        file.particles = vec![particle.clone(), particle.clone(), particle];
        for index in 0..3 {
            file.emitters[index].create_interval = curve(&[(0, 1.0)]);
            file.emitters[index].particle_items[0].target_index = index as i32;
            file.particles[index].life.value = 100.0;
        }
        file.schedulers[0].triggers[0].timeline_index = 2;
        let mut second = file.schedulers[0].clone();
        second.items[0].timeline_index = 1;
        file.schedulers.push(second);
        let mut value = shared_trigger_playback(&file);
        assert!(value.trigger_document(0, 1).unwrap());
        step(&mut value, 1.0);
        assert_eq!(value.fallback_reason(), None);
        let state = value.state.as_ref().unwrap();
        let latest = |definition| {
            let root = state
                .roots
                .iter()
                .position(|root| root.index == definition)
                .unwrap();
            state
                .instances
                .particles(root)
                .map(|particle| particle.id)
                .max()
                .unwrap()
        };
        assert!(latest(0) < latest(2));
        assert!(latest(2) < latest(1));
    }

    #[test]
    fn external_document_trigger_reclaims_finished_targets_and_enforces_live_capacity() {
        let mut file = trigger_fixture(AvfxTimelineClipType::Trigger, [0, 0, 0, 0], 5);
        file.timelines[0].items.clear();
        file.timelines[0].clips.clear();
        // This fixture exercises external targets alone. An enabled ordinary
        // empty Timeline is still a native object and has its own lifetime.
        file.schedulers[0].items.clear();
        file.timelines[1].items[0].end_time = 1;
        file.emitters[0].create_interval = curve(&[(0, 100.0)]);
        file.particles[0].life = AvfxLife {
            enabled: true,
            value: 1.0,
            ..Default::default()
        };
        file.schedulers[0].triggers[0].timeline_index = 1;
        let mut value = shared_trigger_playback(&file);
        for _ in 0..300 {
            assert!(value.trigger_document(0, 1).unwrap());
            step(&mut value, 1.0);
            step(&mut value, 4.0);
            // Common unlinks an empty retired child in the following Time,
            // after emitter/particle removal has updated child registration.
            for _ in 0..3 {
                step(&mut value, 0.0);
            }
            assert!(quads(&value).is_empty());
            assert!(value.state.as_ref().unwrap().timeline_parents.is_empty());
        }
        // Undispatched live targets occupy slots; rejecting another call
        // must not erase them or switch ordinary playback into fallback.
        for _ in 0..256 {
            assert!(value.trigger_document(0, 1).unwrap());
        }
        let input = value.state.as_ref().unwrap().instances.input_update();
        assert!(
            value
                .trigger_document(0, 1)
                .unwrap_err()
                .contains("parent limit")
        );
        let state = value.state.as_ref().unwrap();
        assert_eq!(state.timeline_parents.len(), 256);
        assert_eq!(state.external_trigger_serial, 556);
        assert_eq!(state.instances.input_update(), input);
        assert_eq!(value.fallback_reason(), None);
        value.reset();
        assert!(value.state.as_ref().unwrap().timeline_parents.is_empty());
    }

    #[test]
    fn shared_trigger_target_prepares_in_birth_input_but_does_not_receive_its_time() {
        let mut file = trigger_fixture(AvfxTimelineClipType::Trigger, [3, 0, 0, 0], 5);
        file.schedulers[0].triggers[3] = AvfxSchedulerItem {
            enabled: false,
            start_time: 99,
            timeline_index: 1,
        };
        file.timelines[1].items[0].binder_index = 0;
        file.binders = binder_factory_fixture(true, -1, 0, 12).binders;
        file.emitters[0].create_interval = curve(&[(0, 100.0)]);
        file.particles[0].life = AvfxLife {
            enabled: true,
            value: 100.0,
            ..Default::default()
        };
        let mut value = shared_trigger_playback(&file);
        assert!(quads(&value).is_empty());
        assert!(value.state.as_ref().unwrap().roots.is_empty());
        step(&mut value, 4.0);
        assert!(quads(&value).is_empty());
        step(&mut value, 2.0);
        let state = value.state.as_ref().unwrap();
        assert_eq!(state.roots.len(), 1);
        let point = state.roots[0].point_binder.as_ref().unwrap();
        near(point.instance.lifecycle.clock.local_age, 0.0);
        assert_eq!(point.prepared_input, Some(state.instances.input_update()));
        assert_eq!(quads(&value).len(), 1);
        near(quads(&value)[0].position[0], 10.0);
        value
            .advance_with_binder_target_snapshot(1.0 / 30.0, &point_targets(20.0))
            .unwrap();
        assert_eq!(value.fallback_reason(), None);
        near(
            value.state.as_ref().unwrap().roots[0]
                .point_binder
                .as_ref()
                .unwrap()
                .instance
                .lifecycle
                .clock
                .local_age,
            1.0,
        );
        // A finite delayed Item belongs to the new Timeline clock, not the
        // source's overshoot or authored trigger-map start.
        file.timelines[1].items[0].start_time = 3;
        let mut delayed = shared_trigger_playback(&file);
        step(&mut delayed, 6.0);
        assert!(delayed.state.as_ref().unwrap().roots.is_empty());
        step(&mut delayed, 2.0);
        assert!(quads(&delayed).is_empty());
        step(&mut delayed, 2.0);
        let point = delayed.state.as_ref().unwrap().roots[0]
            .point_binder
            .as_ref()
            .unwrap();
        near(point.instance.lifecycle.clock.local_age, 1.0);
        assert_eq!(quads(&delayed).len(), 1);
        near(quads(&delayed)[0].position[0], 11.0);
    }

    #[test]
    fn shared_trigger_appends_after_scheduler_siblings_before_next_scheduler() {
        let mut file = trigger_fixture(AvfxTimelineClipType::Trigger, [1, 0, 0, 0], 0);
        file.emitters[0].create_interval = curve(&[(0, 100.0)]);
        for index in 1..3 {
            let mut emitter = file.emitters[0].clone();
            emitter.position.x = Some(curve(&[(0, index as f32 * 100.0)]));
            file.emitters.push(emitter);
            let mut timeline = file.timelines[1].clone();
            timeline.items[0].emitter_index = index;
            file.timelines.push(timeline);
        }
        file.schedulers[0].triggers[1].timeline_index = 1;
        file.schedulers[0].items.push(AvfxSchedulerItem {
            enabled: true,
            start_time: 0,
            timeline_index: 2,
        });
        file.schedulers.push(AvfxScheduler {
            items: vec![AvfxSchedulerItem {
                enabled: true,
                start_time: 0,
                timeline_index: 3,
            }],
            ..Default::default()
        });
        let mut value = shared_trigger_playback(&file);
        step(&mut value, 0.0);
        let state = value.state.as_ref().unwrap();
        assert_eq!(
            state
                .roots
                .iter()
                .map(|root| root.index)
                .collect::<Vec<_>>(),
            [1, 0, 2]
        );
        assert_eq!(
            (0..3)
                .map(|i| state.instances.root_id(i).unwrap())
                .collect::<Vec<_>>(),
            [0, 2, 4]
        );
        assert_eq!(
            quads(&value)
                .iter()
                .map(|quad| quad.position[0])
                .collect::<Vec<_>>(),
            [100.0, 0.0, 200.0]
        );
    }

