    #[test]
    fn shared_trigger_loop_rearms_clips_and_reclaims_completed_target_timelines() {
        let mut file = trigger_fixture(AvfxTimelineClipType::Trigger, [1, 0, 0, 0], 0);
        file.timelines[0].loop_end = 2;
        file.timelines[1].items[0].end_time = 1;
        file.schedulers[0].triggers[1].timeline_index = 1;
        file.emitters[0].create_interval = curve(&[(0, 100.0)]);
        file.particles[0].life = AvfxLife {
            enabled: true,
            value: 1.0,
            ..Default::default()
        };
        let mut value = shared_trigger_playback(&file);
        step(&mut value, 0.0);
        for _ in 0..600 {
            step(&mut value, 1.0);
            let state = value.state.as_ref().unwrap();
            assert!(state.roots.len() <= 2);
            assert!(state.timeline_parents.len() <= 4);
            assert!(
                state
                    .timeline_parents
                    .iter()
                    .map(|parent| parent.clips.len())
                    .sum::<usize>()
                    <= 2
            );
        }
        assert_eq!(
            value.state.as_ref().unwrap().timeline_parents[0]
                .child
                .unwrap()
                .loop_generation(),
            300
        );
    }

