    #[test]
    fn staged_random_trigger_uses_one_shared_draw_for_an_inclusive_slot_range() {
        let mut file = trigger_fixture(AvfxTimelineClipType::RandomTrigger, [8, 10, 0, 0], 2);
        file.emitters[0].create_interval = curve(&[(0, 100.0)]);
        for slot in 8..=10 {
            let mut target = file.timelines[1].clone();
            target.items[0].emitter_index = (slot - 8) as i32;
            if slot != 8 {
                file.timelines.push(target);
                let mut emitter = file.emitters[0].clone();
                emitter.position.x = Some(curve(&[(0, (slot - 8) as f32 * 100.0)]));
                file.emitters.push(emitter);
            }
            file.schedulers[0].triggers[slot] = AvfxSchedulerItem {
                enabled: true,
                start_time: 0,
                timeline_index: (slot - 7) as i32,
            };
        }

        for shared in [false, true] {
            for (state, expected_x) in [([1, 2, 3, 4], 0.0), ([0, 0, 0, 65_535], 200.0)] {
                let mut value = if shared {
                    shared_trigger_playback(&file)
                } else {
                    playback(&file)
                };
                value
                    .state
                    .as_mut()
                    .unwrap()
                    .client_random
                    .replace(ClientXorShift128 { state });
                step(&mut value, 2.0);
                assert_eq!(value.state.as_ref().unwrap().roots.len(), 1);
                let emitted = quads(&value);
                assert_eq!(emitted.len(), 1);
                near(emitted[0].position[0], expected_x);
            }
        }
    }

    #[test]
    fn explicit_client_snapshot_controls_random_trigger_in_both_dispatch_paths() {
        for shared in [false, true] {
            for (words, expected_x) in [([1, 2, 3, 4], 0.0), ([0, 0, 0, 65_535], 200.0)] {
                let mut file =
                    trigger_fixture(AvfxTimelineClipType::RandomTrigger, [8, 10, 0, 0], 2);
                file.emitters[0].create_interval = curve(&[(0, 100.0)]);
                for slot in 8..=10 {
                    let mut target = file.timelines[1].clone();
                    target.items[0].emitter_index = (slot - 8) as i32;
                    if slot != 8 {
                        file.timelines.push(target);
                        let mut emitter = file.emitters[0].clone();
                        emitter.position.x = Some(curve(&[(0, (slot - 8) as f32 * 100.0)]));
                        file.emitters.push(emitter);
                    }
                    file.schedulers[0].triggers[slot] = AvfxSchedulerItem {
                        enabled: true,
                        start_time: 0,
                        timeline_index: (slot - 7) as i32,
                    };
                }
                let seed = super::super::VfxClientRandomState::from_words(words);
                let mut runtime = VfxRuntime::new(&file)
                    .with_client_binder_random_state(seed, super::super::VfxClientTrigMode::Sse2);
                if shared {
                    runtime = runtime
                        .with_binder_target_snapshot(&point_targets(10.0))
                        .unwrap();
                }
                let mut value = VfxPlayback::new(runtime);
                assert_eq!(value.fallback_reason(), None);
                // The legacy fallback stream must not choose the explicit snapshot's slot.
                value
                    .state
                    .as_ref()
                    .unwrap()
                    .client_random
                    .replace(ClientXorShift128 { state: [0; 4] });
                step(&mut value, 2.0);
                let mut expected = seed;
                expected.next_u16();
                let emitted = quads(&value);
                assert_eq!(emitted.len(), 1);
                near(emitted[0].position[0], expected_x);
                assert_eq!(value.client_binder_random_state(), Some(expected));
                assert_eq!(
                    value.state.as_ref().unwrap().client_random.borrow().state,
                    [0; 4]
                );
                assert_eq!(quads(&value), emitted);
                assert_eq!(value.client_binder_random_state(), Some(expected));
                value.reset();
                step(&mut value, 2.0);
                assert_eq!(quads(&value), emitted);
                assert_eq!(value.client_binder_random_state(), Some(expected));
            }
        }
    }

