    #[test]
    fn staged_repeat_segment_timeline_loop_keeps_previous_roots() {
        let mut file = fixture();
        file.timelines[0].loop_start = 30;
        file.timelines[0].loop_end = 60;
        file.timelines[0].binder_index = -1;
        file.timelines[0].items[0].start_time = 35;
        file.timelines[0].items[0].end_time = 50;
        file.emitters[0].create_interval = curve(&[(0, 100.0)]);
        file.particles[0].life = AvfxLife {
            enabled: true,
            value: 40.0,
            ..Default::default()
        };

        let mut value = playback(&file);
        let mut single = file.clone();
        single.timelines[0].loop_start = 0;
        single.timelines[0].loop_end = 0;
        let mut first_root = playback(&single);
        assert!(quads(&value).is_empty());
        for (delta, count) in [
            (35.0, 1),
            (24.0, 1),
            (1.0, 1),
            (4.0, 1),
            (1.0, 2),
            (10.0, 2),
            (1.0, 1),
            (19.0, 2),
        ] {
            step(&mut value, delta);
            step(&mut first_root, delta);
            let current = quads(&value);
            assert_eq!(current.len(), count, "after {delta} frames");
            if (value.state.as_ref().unwrap().elapsed_frames - 65.0).abs() < 1e-5 {
                assert_eq!(&current[..1], quads(&first_root));
            }
        }

        let item = file.timelines[0].items[0];
        file.timelines[0].items.push(AvfxTimelineItem {
            start_time: 10,
            emitter_index: -1,
            ..item
        });
        assert!(
            VfxPlayback::new(VfxRuntime::new(&file))
                .fallback_reason()
                .is_none()
        );
        file.timelines[0].items[0].start_time = 10;
        assert_eq!(
            VfxPlayback::new(VfxRuntime::new(&file)).fallback_reason(),
            Some("staged playback: Timeline loop prefix item")
        );
    }

