    #[test]
    fn staged_timeline_loop_only_rejects_referenced_clips() {
        let mut file = fixture();
        file.timelines[0].loop_end = 10;
        file.timelines[0].binder_index = -1;
        file.timelines[0].items[0].end_time = 100;
        file.timelines[0].clip_count = 1;
        file.timelines[0].clips.push(AvfxTimelineClip {
            clip_type: Some(AvfxTimelineClipType::Kill),
            raw_type: Some(0x4B49_4C4C),
            ..Default::default()
        });
        file.emitters[0].create_interval = curve(&[(0, 100.0)]);
        file.particles[0].life = AvfxLife {
            enabled: true,
            value: 100.0,
            ..Default::default()
        };

        let mut value = playback(&file);
        step(&mut value, 10.0);
        assert_eq!(quads(&value).len(), 2);

        let disabled_item = AvfxTimelineItem {
            enabled: false,
            clip_index: 0,
            ..file.timelines[0].items[0]
        };
        file.timelines[0].items.push(disabled_item);
        let mut value = playback(&file);
        step(&mut value, 10.0);
        assert_eq!(quads(&value).len(), 2);

        file.timelines[0].items[0].clip_index = 0;
        file.timelines[0].items[0].emitter_index = -1;
        let value = VfxPlayback::new(VfxRuntime::new(&file));
        assert_eq!(
            value.fallback_reason(),
            Some("staged playback: Timeline Clip reference")
        );

        file.timelines[0].items[0].clip_index = -1;
        file.timelines[0].items[0].emitter_index = 0;
        file.timelines[0].loop_start = 1;
        let value = VfxPlayback::new(VfxRuntime::new(&file));
        assert_eq!(
            value.fallback_reason(),
            Some("staged playback: Timeline loop prefix item")
        );
        file.timelines[0].loop_start = 0;
        file.timelines[0].binder_index = 0;
        let value = VfxPlayback::new(VfxRuntime::new(&file));
        assert_eq!(
            value.fallback_reason(),
            Some("staged playback: Timeline loop Binder")
        );
        file.timelines[0].binder_index = 256;
        assert_eq!(
            VfxPlayback::new(VfxRuntime::new(&file)).fallback_reason(),
            Some("staged playback: Timeline loop Binder")
        );
        file.timelines[0].binder_index = 255;
        assert_eq!(
            VfxPlayback::new(VfxRuntime::new(&file)).fallback_reason(),
            None
        );
    }

    #[test]
    fn staged_timeline_loop_does_not_start_items_at_or_after_loop_end() {
        let mut baseline = fixture();
        baseline.timelines[0].loop_end = 10;
        baseline.timelines[0].binder_index = -1;
        baseline.timelines[0].items[0].end_time = 100;
        baseline.timelines[0].clip_count = 1;
        baseline.timelines[0].clips.push(AvfxTimelineClip {
            clip_type: Some(AvfxTimelineClipType::Kill),
            raw_type: Some(0x4B49_4C4C),
            ..Default::default()
        });
        baseline.emitters[0].create_interval = curve(&[(0, 100.0)]);
        baseline.particles[0].life = AvfxLife {
            enabled: true,
            value: 100.0,
            ..Default::default()
        };

        let mut with_unreachable = baseline.clone();
        for start_time in [10, 15] {
            with_unreachable.timelines[0].items.push(AvfxTimelineItem {
                start_time,
                end_time: 100,
                clip_index: if start_time == 10 { 0 } else { -1 },
                emitter_index: if start_time == 15 { -1 } else { 0 },
                ..baseline.timelines[0].items[0]
            });
        }
        let mut expected = playback(&baseline);
        let mut actual = playback(&with_unreachable);
        assert_eq!(quads(&actual), quads(&expected));
        for frames in [10.0, 5.0, 5.0] {
            step(&mut expected, frames);
            step(&mut actual, frames);
            let actual_quads = quads(&actual);
            let expected_quads = quads(&expected);
            assert_eq!(
                actual_quads.len(),
                expected_quads.len(),
                "after {frames} frames"
            );
            assert_eq!(actual_quads, expected_quads);
        }

        let mut with_reachable = baseline.clone();
        with_reachable.timelines[0].items.push(AvfxTimelineItem {
            start_time: 9,
            end_time: 100,
            ..baseline.timelines[0].items[0]
        });
        let mut reachable = playback(&with_reachable);
        for (frames, count) in [(9.0, 2), (1.0, 3), (9.0, 4)] {
            step(&mut reachable, frames);
            assert_eq!(quads(&reachable).len(), count, "after {frames} frames");
        }
    }

    #[test]
    fn staged_timeline_loop_ignores_unfired_trigger_and_keeps_root_tails() {
        let mut file = fixture();
        file.timelines[0].loop_end = 10;
        file.timelines[0].binder_index = -1;
        file.timelines[0].items[0].end_time = 100;
        file.emitters[0].create_interval = curve(&[(0, 100.0)]);
        file.particles[0].life = AvfxLife {
            enabled: true,
            value: 100.0,
            ..Default::default()
        };
        file.schedulers = vec![AvfxScheduler {
            items: vec![AvfxSchedulerItem {
                enabled: true,
                start_time: 2,
                timeline_index: 0,
            }],
            triggers: vec![AvfxSchedulerItem {
                enabled: true,
                start_time: 5,
                timeline_index: 0,
            }],
            ..Default::default()
        }];

        let mut without_trigger = file.clone();
        without_trigger.schedulers[0].triggers.clear();
        let mut expected = playback(&without_trigger);
        let mut actual = playback(&file);
        assert_eq!(quads(&actual), quads(&expected));
        for (frames, count) in [(2.0, 1), (9.0, 1), (1.0, 2), (10.0, 3)] {
            step(&mut expected, frames);
            step(&mut actual, frames);
            assert_eq!(quads(&actual), quads(&expected), "after {frames} frames");
            assert_eq!(quads(&actual).len(), count, "after {frames} frames");
        }

        file.schedulers[0].items.clear();
        let mut trigger_only = playback(&file);
        assert!(quads(&trigger_only).is_empty());
        step(&mut trigger_only, 22.0);
        assert!(quads(&trigger_only).is_empty());
    }

