    #[test]
    fn polygon_and_ring_draw_curves_use_start_age_without_a_normal_update() {
        for prewarm in [false, true] {
            for kind in [ParticleType::Polygon, ParticleType::DecalRing] {
                let mut file = fixture();
                let item = &mut file.emitters[0].particle_items[0];
                item.create_time = 1;
                item.start_frame = 4;
                item.start_frame_null_update = prewarm;
                let particle = &mut file.particles[0];
                particle.particle_type = Some(kind);
                particle.data = match kind {
                    ParticleType::Polygon => AvfxParticleData::Polygon(AvfxParticleDataPolygon {
                        count: curve(&[(0, 3.0), (10, 13.0)]),
                        ..Default::default()
                    }),
                    _ => AvfxParticleData::DecalRing(AvfxParticleDataDecalRing {
                        width: curve(&[(0, 1.0), (10, 3.0)]),
                        ddtt: 0,
                        ..Default::default()
                    }),
                };
                let mut value = playback(&file);
                let initial = quads(&value);
                assert_eq!(initial.len(), 1);
                match kind {
                    ParticleType::Polygon => assert_eq!(initial[0].polygon.unwrap().count, 7),
                    _ => near(initial[0].decal.unwrap().ring_width, 1.8),
                }
                assert_eq!(quads(&value), initial);
                step(&mut value, 1.0);
                let next = quads(&value);
                match kind {
                    ParticleType::Polygon => assert_eq!(next[0].polygon.unwrap().count, 8),
                    _ => near(next[0].decal.unwrap().ring_width, 2.0),
                }
            }
        }
    }

    #[test]
    fn staged_powder_and_decal_admission_keeps_strict_exclusions() {
        let mut file = fixture();
        file.particles[0].particle_type = Some(ParticleType::Powder);
        file.particles[0].simple_anim_enable = true;
        assert!(
            VfxPlayback::new(VfxRuntime::new(&file))
                .fallback_reason()
                .is_some_and(|reason| reason.contains("Smpl"))
        );

        for depth_type in [3, 6] {
            file.particles[0] = AvfxParticle {
                particle_type: Some(ParticleType::Decal),
                collision_type: -1,
                data: AvfxParticleData::Decal(AvfxParticleDataDecal {
                    ddtt: depth_type,
                    ..Default::default()
                }),
                ..Default::default()
            };
            let playback = VfxPlayback::new(VfxRuntime::new(&file));
            let reason = playback
                .fallback_reason()
                .expect("unsupported DDTT must keep continuous fallback");
            if depth_type <= 5 {
                assert!(reason.contains("deferred Decal GBuffer target"));
            } else {
                assert!(reason.contains("unsupported staged Decal DDTT=6"));
            }
        }

        file.particles[0] = AvfxParticle {
            particle_type: Some(ParticleType::DecalRing),
            collision_type: -1,
            data: AvfxParticleData::Decal(AvfxParticleDataDecal::default()),
            ..Default::default()
        };
        assert!(
            VfxPlayback::new(VfxRuntime::new(&file))
                .fallback_reason()
                .is_some_and(|reason| reason.contains("typed Decal data"))
        );
    }

