    #[test]
    fn staged_polyline_point_distortion_advances_three_shared_draws_per_update() {
        let mut file = polyline_fixture();
        if let AvfxParticleData::Polyline(data) = &mut file.particles[0].data {
            data.point_distortion = curve(&[(0, 0.5)]);
        }
        let mut value = playback(&file);
        assert_eq!(value.fallback_reason(), None);

        step(&mut value, 1.0);
        let first = one_polyline(&value).polyline.unwrap();
        assert!(first.points()[0][0].abs() <= 0.5);
        assert!(first.points()[0][1].abs() <= 0.5);
        assert!(first.points()[0][2].abs() <= 0.5);
        assert_eq!(one_polyline(&value).polyline, Some(first));

        step(&mut value, 0.0);
        assert_eq!(one_polyline(&value).polyline, Some(first));
        step(&mut value, 2.0);
        let second = one_polyline(&value).polyline.unwrap();
        assert_eq!(second.points()[1], first.points()[0]);
        assert!((0.5..=1.5).contains(&second.points()[0][0]));
        assert!(second.points()[0][1].abs() <= 0.5);
        assert!(second.points()[0][2].abs() <= 0.5);
        assert_ne!(second.points()[0], first.points()[0]);

        value.reset();
        step(&mut value, 1.0);
        assert_eq!(one_polyline(&value).polyline, Some(first));
    }

