    #[test]
    fn staged_shape_counter_ignores_capacity_rejections() {
        let mut file = polyline_fixture();
        let emitter = &mut file.emitters[0];
        emitter.emitter_type = Some(EmitterType::SphereModel);
        emitter.data = Some(AvfxEmitterData::SphereModel(SphereModelEmitterData {
            generate_method: 3,
            divide_x: 4,
            divide_y: 2,
            radius: curve(&[(0, 2.0)]),
            injection_speed: curve(&[(0, 0.0)]),
            ..Default::default()
        }));
        emitter.child_limit = 1;
        emitter.create_count = curve(&[(0, 2.0)]);
        emitter.create_interval = curve(&[(0, 1.0)]);
        emitter.position = Default::default();
        emitter.particle_items[0].create_time = 0;
        file.particles[0].life = crate::avfx::AvfxLife {
            enabled: true,
            value: 10.0,
            ..Default::default()
        };
        file.particles[0].position = Default::default();
        if let AvfxParticleData::Polyline(data) = &mut file.particles[0].data {
            data.use_edge = false;
        }

        let mut value = playback(&file);
        assert_eq!(
            one_polyline(&value).polyline.unwrap().points(),
            [[0.0, 2.0, 0.0]; 4]
        );
        let mut retired = false;
        let mut replacement = None;
        for _ in 0..30 {
            step(&mut value, 1.0);
            let values = quads(&value);
            if values.is_empty() {
                retired = true;
            } else if retired {
                replacement = Some(values[0].polyline.unwrap());
                break;
            }
        }
        let replacement = replacement.expect("capacity did not admit a replacement");
        for point in replacement.points() {
            near(point[0], 0.0);
            near(point[1], 0.0);
            near(point[2], 2.0);
        }
    }

    #[test]
    fn default_polyline_cf_softness_match_original_positions_and_replay() {
        use super::super::{VfxClientColorCurveDefaults, VfxClientRandomState, VfxClientTrigMode};
        let cases: Vec<serde_json::Value> =
            serde_json::from_str(include_str!("fixtures/polyline-history.json")).unwrap();
        // The point-writer capture supplies its TLS input. This public fixture
        // also runs emitter/property consumers, whose full native prefix is
        // not captured here, so compare positions with PnDs disabled. The full
        // point-writer matrix separately compares nonzero PnDs and exact RNG.
        for case in cases
            .iter()
            .filter(|c| c["production"] == true && c["distortion"] == 0)
        {
            let read = |name: &str| f32::from_bits(case[name].as_u64().unwrap() as u32);
            let mut file = polyline_fixture();
            // Binary-exact timestamps and key interval keep this point-writer
            // regression independent of Framework and curve interpolation rounding.
            file.particles[0].position.x = Some(curve(&[(0, 0.0), (32, 32.0)]));
            file.emitters[0].particle_items[0].create_time = 0;
            file.emitters[0].create_interval = curve(&[(0, 1000.0)]);
            file.emitters[0].position = Default::default();
            file.emitters[0].emitter_type = Some(EmitterType::SphereModel);
            file.emitters[0].data = Some(AvfxEmitterData::SphereModel(SphereModelEmitterData {
                generate_method: 3,
                divide_x: 4,
                divide_y: 2,
                radius: curve(&[(0, 2.0)]),
                injection_speed: curve(&[(0, 0.0)]),
                ..Default::default()
            }));
            file.particles[0].rotation_direction_base = case["axis"].as_i64().unwrap() as i32;
            let AvfxParticleData::Polyline(data) = &mut file.particles[0].data else {
                unreachable!()
            };
            data.length = curve(&[(0, read("length"))]);
            data.cf = curve(&[(0, read("cf"))]);
            data.softness = curve(&[(0, read("softness"))]);
            data.point_distortion = curve(&[(0, read("distortion"))]);
            let mut value = VfxPlayback::new(
                VfxRuntime::new(&file)
                    .with_client_binder_random_state(
                        VfxClientRandomState::from_words([
                            123456789, 362436069, 521288629, 88675123,
                        ]),
                        VfxClientTrigMode::Sse2,
                    )
                    .with_client_color_curve_defaults(VfxClientColorCurveDefaults {
                        empty_random_type: 0,
                        empty_rgba: [1.0; 4],
                    })
                    .with_client_particle_constructor(),
            );
            let check = |value: &VfxPlayback, index: usize| {
                assert_eq!(value.fallback_reason(), None, "{case}");
                let output = one_polyline(value);
                let row = &case["steps"][index];
                let points: Vec<[u32; 3]> = output
                    .polyline
                    .unwrap()
                    .points()
                    .iter()
                    .map(|point| point.map(f32::to_bits))
                    .collect();
                assert_eq!(
                    serde_json::json!(points),
                    row["points"],
                    "{case} step {index}"
                );
                let random = value.client_binder_random_state();
                assert_eq!(one_polyline(value), output);
                assert_eq!(value.client_binder_random_state(), random);
            };
            check(&value, 0);
            let initial_random = value.client_binder_random_state();
            for (index, frames) in [7.5, 7.5, 0.0, 7.5, 7.5].into_iter().enumerate() {
                step(&mut value, frames);
                check(&value, index + 1);
            }
            value.reset();
            check(&value, 6);
            assert_eq!(value.client_binder_random_state(), initial_random);
            step(&mut value, 7.5);
            check(&value, 1);
        }
    }

