    #[test]
    fn staged_sphere_model_random_lifetimes_are_per_instance_and_repeatable() {
        let mut file = polyline_fixture();
        file.emitters[0].emitter_type = Some(EmitterType::SphereModel);
        file.emitters[0].data = Some(AvfxEmitterData::SphereModel(SphereModelEmitterData {
            generate_method: 3,
            divide_x: 4,
            divide_y: 2,
            radius: curve(&[(0, 2.0)]),
            injection_speed: curve(&[(0, 0.0)]),
            ..Default::default()
        }));
        file.emitters[0].create_interval = curve(&[(0, 1000.0)]);
        file.emitters[0].particle_items[0].create_count = 8;
        file.particles[0].life = AvfxLife {
            enabled: true,
            value: 12.0,
            value_random: 2.0,
            random_type: 0,
        };

        let sample_counts = |mut value: VfxPlayback| {
            let mut counts = vec![quads(&value).len()];
            for _ in 0..15 {
                step(&mut value, 1.0);
                counts.push(quads(&value).len());
            }
            counts
        };
        let first = sample_counts(playback(&file));
        let second = sample_counts(playback(&file));
        assert_eq!(first, second);
        assert_eq!(first[0], 8);
        assert_eq!(first[15], 0);
        assert!(first.iter().any(|&count| (1..8).contains(&count)));
        assert!(first.windows(2).all(|pair| pair[1] <= pair[0]));
    }

