    fn gravity_fixture(kind: ParticleType) -> AvfxFile {
        let mut file = if kind == ParticleType::Quad {
            fixture()
        } else {
            mesh_fixture(kind)
        };
        file.emitters[0].particle_items[0].create_time = 1;
        file.particles[0].gravity = curve(&[(0, 1.0)]);
        file
    }

    fn heights(value: &VfxPlayback) -> Vec<f32> {
        let mut quads = Vec::new();
        let mut meshes = Vec::new();
        value.sample(&mut quads, &mut meshes);
        quads
            .iter()
            .map(|p| p.position[1])
            .chain(meshes.iter().map(|p| p.position[1]))
            .collect()
    }

