    #[test]
    fn always_gravity_redraws_on_zero_delta_callbacks_without_moving_until_next_step() {
        for kind in [
            ParticleType::Quad,
            ParticleType::Model,
            ParticleType::LightModel,
        ] {
            for emitter_random in [false, true] {
                let mut file = gravity_fixture(kind);
                file.emitters[0].gravity = curve(&[(0, 0.0)]);
                file.particles[0].gravity = curve(&[(0, 0.0)]);
                if emitter_random {
                    file.emitters[0].particle_items[0].create_time = 0;
                    file.emitters[0].create_interval = curve(&[(0, 1.0)]);
                }
                let random = AvfxCurve {
                    random_type: 4,
                    ..curve(&[(0, 10.0)])
                };
                if emitter_random {
                    file.emitters[0].gravity_random = random;
                } else {
                    file.particles[0].gravity_random = random;
                }

                let mut with_zero = playback(&file);
                step(&mut with_zero, 1.0);
                let before_zero = heights(&with_zero);
                assert_eq!(before_zero, heights(&with_zero));
                step(&mut with_zero, 0.0);
                assert_eq!(before_zero, heights(&with_zero));
                step(&mut with_zero, 1.0);
                let after_zero = heights(&with_zero);

                let mut without_zero = playback(&file);
                step(&mut without_zero, 1.0);
                step(&mut without_zero, 1.0);
                let without_zero_heights = heights(&without_zero);
                let index = if emitter_random {
                    after_zero.len() - 1
                } else {
                    0
                };
                assert_eq!(after_zero.len(), without_zero_heights.len());
                assert!(
                    (after_zero[index] - without_zero_heights[index]).abs() > 1.0e-5,
                    "kind={kind:?}, emitter_random={emitter_random}, before={before_zero:?}, after={after_zero:?}, direct={without_zero_heights:?}"
                );

                let mut replay = playback(&file);
                step(&mut replay, 1.0);
                step(&mut replay, 0.0);
                step(&mut replay, 1.0);
                assert_eq!(after_zero, heights(&replay));

                if emitter_random {
                    file.emitters[0].gravity_random.random_type = 1;
                } else {
                    file.particles[0].gravity_random.random_type = 1;
                }
                let mut first_with_zero = playback(&file);
                step(&mut first_with_zero, 1.0);
                step(&mut first_with_zero, 0.0);
                step(&mut first_with_zero, 1.0);
                let mut first_without_zero = playback(&file);
                step(&mut first_without_zero, 1.0);
                step(&mut first_without_zero, 1.0);
                assert_eq!(heights(&first_with_zero), heights(&first_without_zero));
            }
        }
    }

