    #[test]
    fn gravity_prewarm_and_newborn_preparation_use_type_specific_phases() {
        for kind in [
            ParticleType::Quad,
            ParticleType::Model,
            ParticleType::LightModel,
        ] {
            for null_update in [false, true] {
                let mut file = gravity_fixture(kind);
                file.particles[0].gravity = curve(&[(0, 0.0), (20, 20.0)]);
                let item = &mut file.emitters[0].particle_items[0];
                item.start_frame = 2;
                item.start_frame_null_update = null_update;
                let warm = if null_update && kind != ParticleType::Quad {
                    1.0
                } else {
                    0.0
                };
                let mut initial = playback(&file);
                near(heights(&initial)[0], warm);
                step(&mut initial, 2.0);
                // Normal gravity samples current age 4, after property caching at 2.
                near(heights(&initial)[0], warm * 3.0 + 16.0);

                file.emitters[0].particle_items[0].generate_delay = 1;
                let mut delayed = playback(&file);
                assert!(heights(&delayed).is_empty());
                step(&mut delayed, 2.0);
                // A newborn retains the last prewarm delta (1); assigned age
                // without prewarm retains the constructor's zero delta.
                let born = if null_update { warm * 2.0 + 2.0 } else { 0.0 };
                near(heights(&delayed)[0], born);
                step(&mut delayed, 0.0);
                near(heights(&delayed)[0], born);
                step(&mut delayed, 1.0);
                near(
                    heights(&delayed)[0],
                    born + if null_update { warm + 5.0 } else { 3.0 },
                );
            }
        }
    }

    #[test]
    fn gravity_loops_preserve_velocity_and_use_rated_delta() {
        let mut file = gravity_fixture(ParticleType::Quad);
        file.particles[0].gravity = curve(&[(0, 0.0), (20, 20.0)]);
        file.particles[0].loop_end = 3;
        let mut value = playback(&file);
        for expected in [1.0, 4.0, 7.0, 11.0] {
            step(&mut value, 1.0);
            near(heights(&value)[0], expected);
        }
        file.particles[0].life = AvfxLife {
            enabled: true,
            value: 8.0,
            ..Default::default()
        };
        file.particles[0].loop_end = 0;
        let item = &mut file.emitters[0].particle_items[0];
        item.override_life = true;
        item.override_life_value = 4;
        let mut value = playback(&file);
        step(&mut value, 1.0);
        near(heights(&value)[0], 8.0);
        step(&mut value, 1.0);
        near(heights(&value)[0], 32.0);
    }

    #[test]
    fn emitter_gravity_precedes_birth_and_freezes_after_root_finish() {
        for mode in [0, 1, 2, 3, 8] {
            let mut file = gravity_fixture(ParticleType::Quad);
            file.timelines[0].items[0].end_time = 2;
            file.emitters[0].gravity = curve(&[(0, 0.0), (20, 20.0)]);
            file.emitters[0].create_interval = curve(&[(0, 1.0)]);
            let item = &mut file.emitters[0].particle_items[0];
            item.create_time = 0;
            item.parent_influence_coord = mode;
            item.influence_coord_pos = true;
            let mut value = playback(&file);
            step(&mut value, 1.0);
            let follows = mode == 1 || mode == 2 || mode == 8;
            assert_eq!(heights(&value), [if follows { 2.0 } else { 1.0 }, 1.0]);
            step(&mut value, 1.0);
            assert_eq!(
                heights(&value),
                if follows {
                    vec![7.0, 5.0, 4.0]
                } else {
                    vec![3.0, 2.0, 4.0]
                }
            );
            // Root finishes before preparation; its children retain gravity and
            // the final parent transform while their own motion keeps advancing.
            step(&mut value, 1.0);
            assert_eq!(
                heights(&value),
                if follows {
                    vec![10.0, 7.0, 5.0]
                } else {
                    vec![6.0, 4.0, 5.0]
                }
            );
        }
    }

    #[test]
    fn gravity_uses_quantized_updates_and_world_y_outside_coordinate_transforms() {
        let mut file = gravity_fixture(ParticleType::Quad);
        file.particles[0].gravity = curve(&[(0, -1.0)]);
        file.emitters[0].rotation.z = Some(curve(&[(0, 1.0)]));
        file.emitters[0].scale.y = Some(curve(&[(0, -3.0)]));
        file.emitters[0].particle_items[0].parent_influence_coord = 3;
        let particle = &mut file.particles[0];
        particle.rotation.z = Some(curve(&[(0, 2.0)]));
        particle.scale.y = Some(curve(&[(0, -2.0)]));
        particle.air_resistance = curve(&[(0, 0.0)]);
        for order in 0..6 {
            file.particles[0].coord_compute_order = order;
            let mut value = playback(&file);
            for _ in 0..3 {
                value.advance(0.001).unwrap();
                near(heights(&value)[0], 0.0);
            }
            for invalid in [f32::NAN, -1.0, f32::INFINITY] {
                assert!(value.advance(invalid).is_err());
            }
            value.advance(0.001).unwrap();
            near(heights(&value)[0], -0.01);
            value.advance(0.01).unwrap();
            near(heights(&value)[0], -0.13);
        }
    }

    #[test]
    fn gravity_overflow_discards_partial_staged_state() {
        let mut file = gravity_fixture(ParticleType::Quad);
        file.particles[0].gravity = curve(&[(0, f32::MAX)]);
        let runtime = VfxRuntime::new(&file);
        let mut value = playback(&file);
        value.advance(2.0 / 30.0).unwrap();
        assert_eq!(value.fallback_reason(), Some("staged gravity overflow"));
        let mut expected = Vec::new();
        runtime.sample(2.0 / 30.0, &mut expected);
        assert_eq!(quads(&value), expected);
        // The scheduling-only trace does not gain a dependency on motion.
        assert!(
            runtime
                .trace_emitter_updates(0, -1.0, &[2.0 / 30.0])
                .is_ok()
        );
    }

