    fn activated_powder(file: &AvfxFile) -> VfxPlayback {
        let mut value = playback(file);
        assert!(quads(&value).is_empty());
        step(&mut value, 0.1);
        value
    }

    fn sample_powder_frame(file: &AvfxFile, staged: bool) -> [f32; 3] {
        let output = if staged {
            let mut value = playback(file);
            step(&mut value, 0.1); // activation only; no movement on this substep
            step(&mut value, 1.0);
            step(&mut value, 0.0);
            quads(&value)
        } else {
            let mut output = Vec::new();
            VfxRuntime::new(file).sample(1.0 / 30.0, &mut output);
            output
        };
        assert_eq!(output.len(), 1);
        output[0].position
    }

    #[test]
    fn staged_powder_updates_motion_once_and_caps_each_input() {
        let mut file = powder_motion_fixture(0, false, -1, 0.0);
        file.emitters[0].particle_items[0].create_time = 1;
        file.particles[0].life = AvfxLife {
            enabled: true,
            value: -1.0,
            ..Default::default()
        };
        file.particles[0].rotation = Default::default();
        file.particles[0].scale = Default::default();
        let simple = file.particles[0].simple.as_mut().unwrap();
        simple.create_interval_life = 0;
        simple.injection_direction_type = 2;
        simple.velocity_min = 2.0;
        simple.velocity_max = 2.0;
        simple.coord_accuracy = [1.0; 3];
        let mut value = playback(&file);
        assert!(quads(&value).is_empty());
        step(&mut value, 0.0);
        assert!(quads(&value).is_empty());
        step(&mut value, 0.1);
        near(quads(&value)[0].position[0], 0.0); // activation-only substep
        step(&mut value, 0.1);
        near(quads(&value)[0].position[0], 0.2); // the next substep moves once
        let snapshot = quads(&value);
        for _ in 0..4 {
            assert_eq!(quads(&value), snapshot);
        }
        step(&mut value, 0.0);
        assert_eq!(quads(&value), snapshot);

        // Repeated f32 subtraction leaves a positive remainder after the
        // fifth subtraction from .5, so this input executes SIX substeps.
        let mut fractional = playback(&file);
        step(&mut fractional, 0.1);
        step(&mut fractional, 0.5);
        near(quads(&fractional)[0].position[0], 1.2);

        let mut tenths = playback(&file);
        step(&mut tenths, 0.1);
        for _ in 0..9 {
            step(&mut tenths, 0.1);
        }
        near(quads(&tenths)[0].position[0], 1.8);

        // Large constructor ages lose .1 when added in f32. The received
        // delta still advances Powder, and assigning start age is not a birth.
        let mut aged_file = file.clone();
        aged_file.emitters[0].particle_items[0].start_frame = 10_000_000;
        let mut aged = playback(&aged_file);
        assert!(quads(&aged).is_empty());
        step(&mut aged, 0.1);
        step(&mut aged, 0.1);
        near(quads(&aged)[0].position[0], 0.2);

        let mut ten = playback(&file);
        let mut hundred = playback(&file);
        step(&mut ten, 10.0);
        step(&mut hundred, 100.0);
        assert_eq!(quads(&ten), quads(&hundred));
        let first = quads(&ten)[0].position[0];
        step(&mut ten, 10.0);
        assert!(quads(&ten)[0].position[0] > first + 19.9);
        ten.reset();
        assert!(quads(&ten).is_empty());

        let mut expensive = file.clone();
        expensive.particles[0].simple.as_mut().unwrap().create_count = 2000;
        let mut exhausted = playback(&expensive);
        exhausted.advance(10.0 / 30.0).unwrap();
        assert_eq!(
            exhausted.fallback_reason(),
            Some("staged playback: Powder substep budget")
        );
        assert!(exhausted.state.is_none());

        // Parent property loops must not reset the slot's incremental clock.
        let mut looped = file.clone();
        looped.particles[0].loop_start = 0;
        looped.particles[0].loop_end = 1;
        let mut baseline = playback(&file);
        let mut looping = playback(&looped);
        for _ in 0..4 {
            step(&mut baseline, 0.75);
            step(&mut looping, 0.75);
            assert_eq!(quads(&baseline), quads(&looping));
        }
    }

    #[test]
    fn powder_prewarm_keeps_each_slot_update_and_birth_property_age() {
        for animated in [false, true] {
            let mut file = powder_motion_fixture(0, false, -1, 0.0);
            file.emitters[0].particle_items[0].create_time = 1;
            file.particles[0].rotation = Default::default();
            file.particles[0].scale = Default::default();
            file.particles[0].life.enabled = false;
            let simple = file.particles[0].simple.as_mut().unwrap();
            simple.create_new_after_delete = true;
            simple.create_interval_life = if animated { 2 } else { 0 };
            simple.injection_direction_type = 2;
            simple.velocity_min = 1.0;
            simple.velocity_max = 1.0;
            simple.coord_accuracy = [1.0; 3];
            if animated {
                file.particles[0].position.x = Some(curve(&[(0, 0.0), (30, 30.0)]));
            }
            let mut reference = playback(&file);
            for _ in 0..20 {
                step(&mut reference, 1.0);
            }
            file.emitters[0].particle_items[0].start_frame = 20;
            file.emitters[0].particle_items[0].start_frame_null_update = true;
            let mut warmed = playback(&file);
            assert_eq!(quads(&warmed).len(), 1);
            assert_eq!(quads(&warmed), quads(&reference), "animated={animated}");
            step(&mut warmed, 0.0);
            assert_eq!(quads(&warmed).len(), 1);
            assert_eq!(quads(&warmed), quads(&reference));
            step(&mut reference, 1.0);
            step(&mut warmed, 1.0);
            assert_eq!(quads(&warmed).len(), 1);
            assert_eq!(quads(&warmed), quads(&reference));
        }
    }

    #[test]
    fn nested_powder_prewarm_latches_each_parent_emitter_age() {
        for depth in [1, 2] {
            let mut file = powder_motion_fixture(0, false, -1, 0.0);
            file.emitters[0].particle_items[0].create_time = 1;
            file.emitters[0].particle_items[0].parent_influence_coord = 2;
            file.particles[0].rotation = Default::default();
            file.particles[0].scale = Default::default();
            file.particles[0].life.enabled = false;
            file.particles[0].position.x = Some(curve(&[(0, 0.5)]));
            let simple = file.particles[0].simple.as_mut().unwrap();
            simple.create_new_after_delete = true;
            simple.create_interval_life = 2;
            simple.velocity_min = 0.0;
            simple.velocity_max = 0.0;
            let mut child = file.emitters[0].clone();
            child.position.x = Some(curve(&[(0, 0.0), (30, 30.0)]));
            child.scale.x = Some(curve(&[(0, 1.0), (30, 2.0)]));
            child.rotation.z = Some(curve(&[(0, 0.0), (30, 1.0)]));
            file.emitters[0].particle_items.clear();
            file.emitters[0].emitter_items = vec![AvfxEmitterItem {
                enabled: true,
                target_index: 1,
                create_time: 1,
                create_count: 1,
                create_probability: 100,
                parameter_link: -1,
                ..Default::default()
            }];
            file.emitters.push(child);
            if depth == 2 {
                let mut leaf = file.emitters[1].clone();
                leaf.position = Default::default();
                leaf.scale = Default::default();
                leaf.rotation = Default::default();
                file.emitters[1].particle_items.clear();
                file.emitters[1].emitter_items = vec![AvfxEmitterItem {
                    enabled: true,
                    target_index: 2,
                    create_time: 1,
                    create_count: 1,
                    create_probability: 100,
                    parameter_link: -1,
                    parent_influence_coord: 2,
                    ..Default::default()
                }];
                file.emitters.push(leaf);
            }
            if depth == 2 {
                let mut constructor = file.clone();
                constructor.emitters[1].position.x = Some(curve(&[(0, 5.0)]));
                constructor.emitters[2].particle_items[0].start_frame = 1;
                constructor.emitters[2].particle_items[0].start_frame_null_update = true;
                let initial = quads(&playback(&constructor));
                assert_eq!(initial.len(), 1);
                near(initial[0].position[0], 5.5);
                constructor.emitters[1].gravity = curve(&[(0, 1.0)]);
                constructor.emitters[2].particle_items[0].generate_delay = 1;
                let mut delayed = playback(&constructor);
                assert!(quads(&delayed).is_empty());
                step(&mut delayed, 1.0);
                let born = quads(&delayed);
                assert_eq!(born.len(), 1);
                near(born[0].position[1], 1.0);
            }
            if depth == 2 {
                let mut initial_file = file.clone();
                initial_file.emitters[2].particle_items[0].parent_influence_coord = 3;
                let mut initial_space = playback(&initial_file);
                for _ in 0..20 {
                    step(&mut initial_space, 1.0);
                }
                let initial_particles = quads(&initial_space);
                assert_eq!(initial_particles.len(), 1);
                near(initial_particles[0].position[0], 0.5);
                near(initial_particles[0].position[1], 0.0);
                // Freeze a child emitter beneath two moving/current levels,
                // while its Powder follows that frozen emitter (Always).
                let mut leaf = initial_file.emitters[2].clone();
                leaf.particle_items[0].parent_influence_coord = 2;
                initial_file.emitters[2].particle_items.clear();
                initial_file.emitters[2].emitter_items = vec![AvfxEmitterItem {
                    enabled: true,
                    target_index: 3,
                    create_time: 1,
                    create_count: 1,
                    create_probability: 100,
                    parameter_link: -1,
                    parent_influence_coord: 3,
                    ..Default::default()
                }];
                initial_file.emitters.push(leaf);
                let mut initial_emitter = playback(&initial_file);
                for _ in 0..20 {
                    step(&mut initial_emitter, 1.0);
                }
                let particles = quads(&initial_emitter);
                assert_eq!(particles.len(), 1);
                near(particles[0].position[0], 0.5);
                near(particles[0].position[1], 0.0);
            }
            let mut reference = playback(&file);
            for _ in 0..20 {
                step(&mut reference, 1.0);
            }
            file.emitters[0].emitter_items[0].start_frame = 20;
            file.emitters[0].emitter_items[0].start_frame_null_update = true;
            let warmed = playback(&file);
            assert_eq!(quads(&warmed).len(), 1);
            assert_eq!(quads(&warmed), quads(&reference));
        }
    }

