    #[test]
    fn powder_negative_uv_interval_retires_in_continuous_and_staged_output() {
        for staged in [false, true] {
            for loops in [-1, 0, 1] {
                for recreate in [false, true] {
                    let mut file = powder_motion_fixture(0, false, -1, 0.0);
                    let simple = file.particles[0].simple.as_mut().unwrap();
                    simple.uv_interval = 254; // signed byte -2
                    simple.uv_loop_count = loops;
                    simple.create_new_after_delete = recreate;
                    for frame in [0.0, 1.0, 2.0, 3.0] {
                        let output = if staged {
                            let mut value = playback(&file);
                            step(&mut value, frame);
                            step(&mut value, 0.0);
                            quads(&value)
                        } else {
                            let mut output = Vec::new();
                            VfxRuntime::new(&file).sample(frame / 30.0, &mut output);
                            output
                        };
                        let visible = if staged {
                            frame > 0.0 && (loops <= 0 || recreate || frame <= 2.0)
                        } else {
                            loops <= 0 || recreate || frame < 2.0
                        };
                        assert_eq!(
                            output.len(),
                            usize::from(visible),
                            "staged={staged}, loops={loops}, recreate={recreate}, frame={frame}"
                        );
                    }
                }
            }
        }
    }

