    #[test]
    fn powder_velocity_transforms_before_world_decay_or_after_local_decay() {
        for position_type in [0, 1] {
            for bind_parent in [false, true] {
                for bind_model in [-1, 0] {
                    for staged in [false, true] {
                        let mut file =
                            powder_motion_fixture(position_type, bind_parent, bind_model, 0.5);
                        let simple = file.particles[0].simple.as_mut().unwrap();
                        simple.injection_direction_type = 2;
                        simple.coord_accuracy = [0.5, 1.0, 1.0];
                        simple.velocity_min = 0.0;
                        simple.velocity_max = 0.0;
                        let baseline = sample_powder_frame(&file, staged);
                        let simple = file.particles[0].simple.as_mut().unwrap();
                        simple.velocity_min = 2.0;
                        simple.velocity_max = 2.0;
                        let moving = sample_powder_frame(&file, staged);
                        // Ten explicit substeps distinguish decay in world Y
                        // from decay in local X before the 90-degree rotation.
                        let local = bind_parent || position_type == 2;
                        let mut velocity = if local { 2.0_f64 } else { 4.0 };
                        let mut distance = 0.0;
                        for _ in 0..10 {
                            velocity *= if local { 0.5 } else { 1.0 };
                            distance += velocity * 0.1;
                        }
                        if position_type != 2 && bind_parent {
                            distance *= 2.0;
                        }
                        if position_type != 2 && bind_model >= 0 {
                            distance *= 0.5;
                        }
                        let expected = if position_type == 2 {
                            [distance as f32, 0.0, 0.0]
                        } else {
                            [0.0, distance as f32, 0.0]
                        };
                        for axis in 0..3 {
                            assert!(
                                (moving[axis] - baseline[axis] - expected[axis]).abs() < 1e-4,
                                "SIPT={position_type}, bBnP={bind_parent}, VBMN={bind_model}, staged={staged}: {moving:?} vs {baseline:?}, delta={expected:?}"
                            );
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn powder_gravity_obeys_vertex_binding_and_parent_draw_space() {
        for position_type in [0, 1] {
            for bind_parent in [false, true] {
                for bind_model in [-1, 0] {
                    for rate in [0.0, 0.5, 1.0] {
                        let mut file =
                            powder_motion_fixture(position_type, bind_parent, bind_model, rate);
                        for staged in [false, true] {
                            file.particles[0].simple.as_mut().unwrap().coord_gravity = [0.0; 3];
                            let baseline = sample_powder_frame(&file, staged);
                            file.particles[0].simple.as_mut().unwrap().coord_gravity =
                                [2.0, 0.0, 0.0];
                            let gravity = sample_powder_frame(&file, staged);
                            let expected = if position_type != 2 && bind_model >= 0 {
                                [0.0; 3]
                            } else if position_type != 2 && bind_parent {
                                [0.0, 2.0, 0.0]
                            } else {
                                [1.0, 0.0, 0.0]
                            };
                            for axis in 0..3 {
                                assert!(
                                    (gravity[axis] - baseline[axis] - expected[axis]).abs() < 1e-4,
                                    "SIPT={position_type}, bBnP={bind_parent}, VBMN={bind_model}, FltR={rate}, staged={staged}: {gravity:?} vs {baseline:?}, delta={expected:?}"
                                );
                            }
                        }
                    }
                }
            }
        }
    }

