    #[test]
    fn staged_powder_sipt_controls_model_position_and_binding() {
        let mut file = fixture();
        file.emitters[0].position = Default::default();
        file.particles[0] = AvfxParticle {
            particle_type: Some(ParticleType::Powder),
            collision_type: -1,
            position: AvfxCurve3Axis {
                x: Some(curve(&[(0, 0.0), (20, 20.0)])),
                ..Default::default()
            },
            simple_anim_enable: true,
            simple: Some(AvfxParticleSimple {
                create_count: 1,
                create_interval_life: 100,
                injection_position_type: 1,
                injection_model_index: 0,
                injection_vertex_bind_model_index: 1,
                velocity_flattery_rate: 1.0,
                scale_start: [1.0; 2],
                scale_end: [1.0; 2],
                scale_rand_x: [1.0; 2],
                scale_rand_y: [1.0; 2],
                colors: [[255; 4]; 4],
                ..Default::default()
            }),
            data: AvfxParticleData::Powder {
                use_character_movement: false,
                use_character_location: false,
                is_lightning: false,
                directional_light_type: 0,
                center_offset: 0.0,
            },
            ..Default::default()
        };
        file.models = vec![
            VfxModelGeometry {
                emit_vertices: vec![
                    VfxEmitVertex {
                        position: [99.0, 0.0, 0.0],
                        ..Default::default()
                    },
                    VfxEmitVertex {
                        position: [1.0, 1.0, 3.0],
                        ..Default::default()
                    },
                ],
                emit_vertex_numbers: vec![1, 0],
                ..Default::default()
            },
            VfxModelGeometry {
                emit_vertices: vec![VfxEmitVertex {
                    position: [5.0, 0.0, 0.0],
                    ..Default::default()
                }],
                emit_vertex_numbers: vec![0],
                ..Default::default()
            },
        ];

        file.particles[0]
            .simple
            .as_mut()
            .unwrap()
            .velocity_flattery_rate = 0.0;
        let injection_only = quads(&activated_powder(&file));
        assert_eq!(injection_only.len(), 1);
        let packed_birth = super::super::powder::packed_position([1.0, 1.0, 3.0], true);
        assert_eq!(injection_only[0].position, packed_birth);
        let mut moving_emitter = activated_powder(&file);
        step(&mut moving_emitter, 1.0);
        step(&mut moving_emitter, 1.0);
        assert_eq!(quads(&moving_emitter)[0].position, packed_birth);

        file.particles[0]
            .simple
            .as_mut()
            .unwrap()
            .velocity_flattery_rate = 0.5;
        let halfway = quads(&activated_powder(&file));
        assert_eq!(halfway.len(), 1);
        assert_eq!(
            halfway[0].position,
            std::array::from_fn(|axis| 0.5 * (packed_birth[axis] + [5.0, 0.0, 0.0][axis]))
        );

        file.particles[0]
            .simple
            .as_mut()
            .unwrap()
            .velocity_flattery_rate = 1.0;
        let mut attached = activated_powder(&file);
        let position_only = quads(&attached);
        assert_eq!(position_only.len(), 1);
        assert_eq!(position_only[0].position, [5.0, 0.0, 0.0]);
        step(&mut attached, 1.0);
        step(&mut attached, 1.0);
        near(quads(&attached)[0].position[0], 6.1);

        let simple = file.particles[0].simple.as_mut().unwrap();
        simple.injection_model_index = 256;
        simple.injection_vertex_bind_model_index = 257;
        simple.velocity_flattery_rate = 0.0;
        assert_eq!(
            quads(&activated_powder(&file))[0].position,
            super::super::powder::packed_position([1.0, 1.0, 3.0], true)
        );
        file.particles[0]
            .simple
            .as_mut()
            .unwrap()
            .velocity_flattery_rate = 1.0;
        assert_eq!(quads(&activated_powder(&file))[0].position, [5.0, 0.0, 0.0]);
        file.particles[0]
            .simple
            .as_mut()
            .unwrap()
            .injection_vertex_bind_model_index = 255;
        assert_eq!(
            quads(&activated_powder(&file))[0].position,
            super::super::powder::packed_position([1.0, 1.0, 3.0], false)
        );

        file.particles[0]
            .simple
            .as_mut()
            .unwrap()
            .injection_position_type = 2;
        file.particles[0].simple.as_mut().unwrap().create_area = [0.75, 1.25, 0.5];
        file.particles[0].position.x = Some(curve(&[(0, 7.0), (20, 27.0)]));
        for bind_parent in [false, true] {
            file.particles[0].simple.as_mut().unwrap().bind_parent = bind_parent;
            let mut no_binding = activated_powder(&file);
            assert!(quads(&no_binding).is_empty());
            step(&mut no_binding, 1.0);
            step(&mut no_binding, 1.0);
            assert!(quads(&no_binding).is_empty());
        }
    }

    #[test]
    fn staged_powder_sipt_zero_and_one_separate_model_position_from_normal() {
        let mut file = fixture();
        file.emitters[0].position = Default::default();
        file.particles[0] = AvfxParticle {
            particle_type: Some(ParticleType::Powder),
            collision_type: -1,
            simple_anim_enable: true,
            simple: Some(AvfxParticleSimple {
                create_count: 1,
                create_interval_life: 100,
                injection_position_type: 1,
                injection_direction_type: 5,
                injection_model_index: 0,
                injection_vertex_bind_model_index: -1,
                coord_accuracy: [1.0; 3],
                velocity_min: 2.0,
                velocity_max: 2.0,
                scale_start: [1.0; 2],
                scale_end: [1.0; 2],
                scale_rand_x: [1.0; 2],
                scale_rand_y: [1.0; 2],
                colors: [[255; 4]; 4],
                ..Default::default()
            }),
            data: AvfxParticleData::Powder {
                use_character_movement: false,
                use_character_location: false,
                is_lightning: false,
                directional_light_type: 0,
                center_offset: 0.0,
            },
            ..Default::default()
        };
        file.models = vec![VfxModelGeometry {
            emit_vertices: vec![VfxEmitVertex {
                position: [1.0, 1.0, 3.0],
                normal: [0.0, 0.0, 1.0],
                ..Default::default()
            }],
            emit_vertex_numbers: vec![0],
            ..Default::default()
        }];
        let packed_birth = super::super::powder::packed_position([1.0, 1.0, 3.0], false);

        for position_type in [0, 1] {
            file.particles[0]
                .simple
                .as_mut()
                .unwrap()
                .injection_position_type = position_type;
            let birth = if position_type == 0 {
                [0.0; 3]
            } else {
                packed_birth
            };
            let mut value = activated_powder(&file);
            assert_eq!(quads(&value)[0].position, birth);
            step(&mut value, 1.0);
            let position = quads(&value)[0].position;
            for axis in 0..3 {
                near(
                    position[axis],
                    birth[axis] + if axis == 2 { 2.0 } else { 0.0 },
                );
            }
        }

        let simple = file.particles[0].simple.as_mut().unwrap();
        simple.injection_position_type = 0;
        simple.injection_model_index = 256;
        assert_eq!(quads(&activated_powder(&file))[0].position, [0.0; 3]);
        let simple = file.particles[0].simple.as_mut().unwrap();
        simple.injection_direction_type = 0;
        simple.injection_model_index = 511;
        simple.velocity_min = 0.0;
        simple.velocity_max = 0.0;
        assert_eq!(quads(&activated_powder(&file))[0].position, [0.0; 3]);

        file.particles[0]
            .simple
            .as_mut()
            .unwrap()
            .injection_position_type = 2;
        file.particles[0]
            .simple
            .as_mut()
            .unwrap()
            .injection_direction_type = 5;
        assert!(
            VfxPlayback::new(VfxRuntime::new(&file))
                .fallback_reason()
                .is_some()
        );
        file.particles[0]
            .simple
            .as_mut()
            .unwrap()
            .injection_position_type = 1;
        file.particles[0]
            .simple
            .as_mut()
            .unwrap()
            .injection_direction_type = 6;
        assert!(
            VfxPlayback::new(VfxRuntime::new(&file))
                .fallback_reason()
                .is_some()
        );
        file.particles[0]
            .simple
            .as_mut()
            .unwrap()
            .injection_direction_type = 5;
        file.particles[0]
            .simple
            .as_mut()
            .unwrap()
            .injection_model_index = -1;
        assert!(
            VfxPlayback::new(VfxRuntime::new(&file))
                .fallback_reason()
                .is_some()
        );
        file.particles[0]
            .simple
            .as_mut()
            .unwrap()
            .injection_model_index = 0;
        file.models[0].emit_vertex_numbers.clear();
        assert!(
            VfxPlayback::new(VfxRuntime::new(&file))
                .fallback_reason()
                .is_some()
        );
    }

