    #[test]
    fn continuous_and_staged_sampling_share_order_across_quad_and_mesh() {
        for reverse in [false, true] {
            let mut file = mesh_fixture(ParticleType::Model);
            file.global.draw_layer = if reverse { 10 } else { 4 };
            file.global.soft_key_offset = if reverse { -1.25 } else { 0.625 };
            let mut quad = file.particles[0].clone();
            quad.particle_type = Some(ParticleType::Quad);
            quad.data = AvfxParticleData::None;
            file.particles.push(quad.clone());
            file.particles.push(quad);
            for priority in [7, -7] {
                let mut decal = file.particles[1].clone();
                decal.particle_type = Some(ParticleType::Decal);
                decal.data = AvfxParticleData::Decal(AvfxParticleDataDecal {
                    ddtt: 0,
                    ..Default::default()
                });
                decal.draw_priority = priority;
                file.particles.push(decal);
            }
            let item = file.emitters[0].particle_items[0].clone();
            file.emitters[0].particle_items = [1, 3, 0, 4, 2]
                .map(|target_index| AvfxEmitterItem {
                    target_index,
                    ..item.clone()
                })
                .to_vec();

            file.global.draw_order = i32::from(reverse);
            for particle in &mut file.particles[..3] {
                particle.draw_priority = 257;
            }
            file.particles[1].position.x = Some(curve(&[(0, 1.0)]));
            file.particles[2].position.x = Some(curve(&[(0, 2.0)]));
            let expected_x = if reverse { [2.0, 1.0] } else { [1.0, 2.0] };
            let runtime = VfxRuntime::new(&file);
            let mut quads = Vec::new();
            let mut meshes = Vec::new();
            runtime.sample(0.0, &mut quads);
            runtime.sample_mesh(0.0, &mut meshes);
            assert!(quads.iter().all(|q| q.draw_layer == file.global.draw_layer));
            assert!(
                quads
                    .iter()
                    .all(|q| q.soft_key_offset == file.global.soft_key_offset)
            );
            assert!(
                meshes
                    .iter()
                    .all(|m| m.draw_layer == file.global.draw_layer)
            );
            assert!(
                meshes
                    .iter()
                    .all(|m| m.soft_key_offset == file.global.soft_key_offset)
            );
            assert_eq!(
                quads
                    .iter()
                    .filter(|q| q.decal.is_some())
                    .map(|q| q.draw_order)
                    .collect::<Vec<_>>(),
                [Some(0), Some(1)]
            );
            quads.retain(|q| q.decal.is_none());
            assert!(quads.iter().all(|quad| quad.draw_priority == 1));
            assert!(meshes.iter().all(|mesh| mesh.draw_priority == 1));
            assert_eq!(
                quads
                    .iter()
                    .map(|quad| quad.position[0])
                    .collect::<Vec<_>>(),
                expected_x
            );
            assert_eq!(
                quads.iter().map(|quad| quad.draw_order).collect::<Vec<_>>(),
                [Some(0), Some(2)]
            );
            assert_eq!(
                meshes
                    .iter()
                    .map(|mesh| mesh.draw_order)
                    .collect::<Vec<_>>(),
                [Some(1)]
            );

            let staged = playback(&file);
            staged.sample(&mut quads, &mut meshes);
            assert!(quads.iter().all(|q| q.draw_layer == file.global.draw_layer));
            assert!(
                quads
                    .iter()
                    .all(|q| q.soft_key_offset == file.global.soft_key_offset)
            );
            assert!(
                meshes
                    .iter()
                    .all(|m| m.draw_layer == file.global.draw_layer)
            );
            assert!(
                meshes
                    .iter()
                    .all(|m| m.soft_key_offset == file.global.soft_key_offset)
            );
            assert_eq!(
                quads
                    .iter()
                    .filter(|q| q.decal.is_some())
                    .map(|q| q.draw_order)
                    .collect::<Vec<_>>(),
                [Some(0), Some(1)]
            );
            quads.retain(|q| q.decal.is_none());
            assert!(quads.iter().all(|quad| quad.draw_priority == 1));
            assert!(meshes.iter().all(|mesh| mesh.draw_priority == 1));
            assert_eq!(
                quads
                    .iter()
                    .map(|quad| quad.position[0])
                    .collect::<Vec<_>>(),
                expected_x
            );
            assert_eq!(
                quads.iter().map(|quad| quad.draw_order).collect::<Vec<_>>(),
                [Some(0), Some(2)]
            );
            assert_eq!(
                meshes
                    .iter()
                    .map(|mesh| mesh.draw_order)
                    .collect::<Vec<_>>(),
                [Some(1)]
            );
        }
    }

    fn meshes(playback: &VfxPlayback) -> Vec<VfxMeshInstance> {
        let mut quads = Vec::new();
        let mut meshes = Vec::new();
        playback.sample(&mut quads, &mut meshes);
        assert!(quads.is_empty());
        meshes
    }

    #[test]
    fn mesh_prewarm_separates_property_uv_and_fresnel_ages() {
        for kind in [ParticleType::Model, ParticleType::LightModel] {
            for null_update in [false, true] {
                let mut file = mesh_fixture(kind);
                let item = &mut file.emitters[0].particle_items[0];
                item.start_frame = 4;
                item.start_frame_null_update = null_update;
                let mut value = playback(&file);
                let initial = meshes(&value);
                assert_eq!(initial.len(), 1);
                near(initial[0].position[0], if null_update { 3.0 } else { 0.0 });
                near(initial[0].uv_origins[0][0], 0.0);
                if kind == ParticleType::Model {
                    let fresnel = initial[0].fresnel.unwrap();
                    near(fresnel.exponent, 4.0);
                    near(fresnel.color_begin[3], 1.0);
                    near(fresnel.color_end[3], 0.0);
                    assert_eq!(fresnel.direction, [0.0, -1.0, 0.0]);
                }
                assert_eq!(meshes(&value), initial);
                step(&mut value, 2.0);
                let updated = meshes(&value);
                near(updated[0].position[0], 4.0);
                near(updated[0].uv_origins[0][0], 4.0);
                if kind == ParticleType::Model {
                    let fresnel = updated[0].fresnel.unwrap();
                    near(fresnel.exponent, 6.0);
                    near(fresnel.color_begin[3], 0.8);
                    near(fresnel.color_end[3], 0.2);
                    near(fresnel.direction[0], 0.4_f32.sin());
                    near(fresnel.direction[1], -0.4_f32.cos());
                }
            }
        }
    }

