    #[test]
    fn mesh_cache_ages_follow_lifetime_rate_and_loop_writeback() {
        let mut file = mesh_fixture(ParticleType::Model);
        let particle = &mut file.particles[0];
        particle.life.enabled = true;
        particle.life.value = 10.0;
        particle.loop_start = 1;
        particle.loop_end = 5;
        let item = &mut file.emitters[0].particle_items[0];
        item.start_frame = 4;
        item.start_frame_null_update = true;
        item.override_life = true;
        item.override_life_value = 20;
        let mut value = playback(&file);
        let initial = meshes(&value)[0];
        near(initial.position[0], 1.5);
        near(initial.uv_origins[0][0], 0.0);
        near(initial.fresnel.unwrap().exponent, 2.0);
        step(&mut value, 2.0);
        let updated = meshes(&value)[0];
        near(updated.position[0], 2.0);
        near(updated.uv_origins[0][0], 2.0);
        near(updated.fresnel.unwrap().exponent, 1.0);
    }

