    #[test]
    fn unsupported_mesh_selection_falls_back_but_empty_or_null_pools_stay_staged() {
        let base = mesh_fixture(ParticleType::Model);
        for variant in 0..4 {
            let mut file = base.clone();
            let AvfxParticleData::Model {
                model_indexes,
                is_morph,
                ..
            } = &mut file.particles[0].data
            else {
                unreachable!()
            };
            match variant {
                0 => *is_morph = true,
                1 => model_indexes.clear(),
                2 => model_indexes[0] = 254,
                _ => model_indexes[0] = 255,
            }
            let runtime = VfxRuntime::new(&file);
            let mut value = VfxPlayback::new(runtime.clone());
            if matches!(variant, 1 | 3) {
                // Original Model selection returns without geometry for an
                // empty pool or 0xff entry. Texture callbacks still run in the
                // wrapper; their shared stream is covered by the joint capture.
                assert_eq!(value.fallback_reason(), None);
                assert!(meshes(&value).is_empty());
            } else {
                assert!(
                    value
                        .fallback_reason()
                        .unwrap()
                        .contains("supported static draw model pool")
                );
            }
            value.advance(0.125).unwrap();
            let mut expected = Vec::new();
            runtime.sample_mesh(0.125, &mut expected);
            assert_eq!(meshes(&value), expected);
        }
    }

    #[test]
    fn staged_model_pool_selection_is_stable_between_reads() {
        let mut file = mesh_fixture(ParticleType::Model);
        file.models.push(file.models[0].clone());
        let AvfxParticleData::Model {
            model_indexes,
            animation_number,
            ..
        } = &mut file.particles[0].data
        else {
            unreachable!()
        };
        *model_indexes = vec![0, 1, 255];
        *animation_number = Some(curve(&[(0, 1.0)]));
        let value = playback(&file);
        assert!(value.fallback_reason().is_none());
        assert_eq!(meshes(&value)[0].model_index, 1);
        assert_eq!(meshes(&value)[0].model_index, 1);

        let AvfxParticleData::Model {
            model_number_random_value,
            model_number_random_type,
            animation_number,
            ..
        } = &mut file.particles[0].data
        else {
            unreachable!()
        };
        *model_number_random_value = 2;
        *model_number_random_type = 0;
        *animation_number = Some(curve(&[(0, 0.0)]));
        let value = playback(&file);
        let mut control = file.clone();
        let AvfxParticleData::Model {
            model_number_random_value,
            ..
        } = &mut control.particles[0].data
        else {
            unreachable!()
        };
        *model_number_random_value = 0;
        let control = playback(&control);
        let random_after_birth = value.state.as_ref().unwrap().client_random.borrow().state;
        assert_ne!(
            random_after_birth,
            control.state.as_ref().unwrap().client_random.borrow().state
        );
        let birth_state = *value
            .state
            .as_ref()
            .unwrap()
            .model_number_state
            .borrow()
            .values()
            .next()
            .unwrap();
        assert!((-2..=2).contains(&birth_state.random_base));
        let first = meshes(&value);
        let repeated = meshes(&value);
        assert_eq!(first, repeated);
        assert_eq!(
            value.state.as_ref().unwrap().client_random.borrow().state,
            random_after_birth
        );

        let AvfxParticleData::Model {
            model_number_random_interval,
            ..
        } = &mut file.particles[0].data
        else {
            unreachable!()
        };
        *model_number_random_interval = 2;
        let mut value = playback(&file);
        let _ = meshes(&value);
        let initial = *value
            .state
            .as_ref()
            .unwrap()
            .model_number_state
            .borrow()
            .values()
            .next()
            .unwrap();
        let _ = meshes(&value);
        let repeated = *value
            .state
            .as_ref()
            .unwrap()
            .model_number_state
            .borrow()
            .values()
            .next()
            .unwrap();
        assert_eq!(initial.bucket, repeated.bucket);
        assert_eq!(initial.value, repeated.value);
        step(&mut value, 3.0);
        let _ = meshes(&value);
        let advanced = *value
            .state
            .as_ref()
            .unwrap()
            .model_number_state
            .borrow()
            .values()
            .next()
            .unwrap();
        assert_ne!(initial.bucket, advanced.bucket);
    }

    #[test]
    fn staged_model_birth_random_follows_creation_order_and_ignores_output_capacity() {
        let mut file = mesh_fixture(ParticleType::Model);
        file.emitters[0].particle_items[0].create_count = 3;
        let AvfxParticleData::Model {
            model_number_random_value,
            model_number_random_type,
            ..
        } = &mut file.particles[0].data
        else {
            unreachable!()
        };
        *model_number_random_value = 7;
        *model_number_random_type = 1;

        let mut control_file = file.clone();
        let AvfxParticleData::Model {
            model_number_random_value,
            ..
        } = &mut control_file.particles[0].data
        else {
            unreachable!()
        };
        *model_number_random_value = 0;
        let control = playback(&control_file);
        let mut expected_random = *control.state.as_ref().unwrap().client_random.borrow();
        let expected = (0..3)
            .map(|_| {
                super::super::model_number_random_base_from_unit(7, 1, expected_random.next_u16())
            })
            .collect::<Vec<_>>();

        let mut runtime = VfxRuntime::new(&file);
        runtime.max_quads = 1;
        let value = VfxPlayback::new(runtime);
        let state = value.state.as_ref().unwrap();
        let mut actual = state
            .model_number_state
            .borrow()
            .iter()
            .map(|(&id, state)| (id, state.random_base))
            .collect::<Vec<_>>();
        actual.sort_unstable_by_key(|&(id, _)| id);
        assert_eq!(
            actual.iter().map(|&(_, base)| base).collect::<Vec<_>>(),
            expected
        );
        assert_eq!(state.client_random.borrow().state, expected_random.state);

        let before_sample = state.client_random.borrow().state;
        assert_eq!(meshes(&value).len(), 1);
        assert_eq!(state.client_random.borrow().state, before_sample);
        assert_eq!(
            state.model_number_state.borrow().len(),
            3,
            "capacity-limited output retains every live Model state"
        );
    }

