    #[test]
    fn distortion_reads_draw_age_while_uv_keeps_its_callback_cache() {
        for kind in [
            ParticleType::Quad,
            ParticleType::Model,
            ParticleType::LightModel,
        ] {
            for null_update in [false, true] {
                let mut file = mesh_fixture(ParticleType::LightModel);
                file.particles[0].particle_type = Some(kind);
                if kind == ParticleType::Quad {
                    file.particles[0].data = AvfxParticleData::None;
                } else if kind == ParticleType::Model {
                    file.particles[0].data = mesh_fixture(kind).particles.remove(0).data;
                }
                let item = &mut file.emitters[0].particle_items[0];
                item.start_frame = 4;
                item.start_frame_null_update = null_update;
                file.particles[0].texture_distortion = Some(AvfxParticleDistortion {
                    enabled: true,
                    texture_index: 0,
                    power: curve(&[(0, 0.0), (20, 2.0)]),
                    ..Default::default()
                });
                let mut value = playback(&file);
                for (delta, uv_age, draw_age) in [
                    (None, 0.0, 4.0),
                    (Some(2.0), 4.0, 6.0),
                    (Some(0.0), 6.0, 6.0),
                ] {
                    if let Some(delta) = delta {
                        step(&mut value, delta);
                    }
                    let (power, uv) = if kind == ParticleType::Quad {
                        let quad = quads(&value)[0];
                        (quad.distortion_power, quad.uvd_origin[0])
                    } else {
                        let mesh = meshes(&value)[0];
                        (mesh.distortion_power, mesh.uvd_origin[0])
                    };
                    near(power, draw_age * 0.1);
                    near(uv, uv_age);
                }
            }
        }
    }

    #[test]
    fn finite_root_finishes_with_previous_matrix_and_keeps_particle_tails() {
        let mut file = fixture();
        file.timelines[0].items[0].end_time = 2;
        let item = file.emitters[0].particle_items[0];
        file.emitters[0].particle_items.push(AvfxEmitterItem {
            create_time: 2,
            ..item
        });
        file.particles[0].life = AvfxLife {
            enabled: true,
            value: 5.0,
            ..Default::default()
        };
        let mut value = playback(&file);
        step(&mut value, 2.0);
        assert_eq!(quads(&value).len(), 2);
        step(&mut value, 1.0);
        assert_eq!(quads(&value).len(), 3);
        assert!(quads(&value).iter().all(|quad| quad.position == [0.0; 3]));
        step(&mut value, 1.0);
        assert_eq!(quads(&value).len(), 3);
        step(&mut value, 6.0);
        assert!(quads(&value).is_empty());
    }

    #[test]
    fn playback_quantizes_updates_and_rejects_invalid_input_without_mutation() {
        let mut file = fixture();
        file.emitters[0].create_interval = curve(&[(0, 0.1)]);
        let mut value = playback(&file);
        for _ in 0..3 {
            value.advance(0.001).unwrap();
            assert_eq!(quads(&value).len(), 1);
        }
        for delta in [f32::NAN, f32::INFINITY, -0.1, 10_000_000.0] {
            assert!(value.advance(delta).is_err());
        }
        value.advance(0.001).unwrap();
        assert_eq!(quads(&value).len(), 2);
        near(value.clock.remainder, 0.02);
    }

    #[test]
    fn unsupported_files_and_budget_exhaustion_render_complete_continuous_fallback() {
        let mut files = Vec::new();
        let mut file = fixture();
        file.timelines[0].loop_end = 10;
        file.timelines[0].binder_index = 0;
        files.push(file);
        let mut file = fixture();
        file.emitters[0].particle_items[0].create_time = 1;
        file.emitters[0].particle_items[0].create_count = 20_000;
        files.push(file);
        for file in files {
            let runtime = VfxRuntime::new(&file);
            let mut value = VfxPlayback::new(runtime.clone());
            assert!(value.fallback_reason().is_some());
            let mut expected = Vec::new();
            runtime.sample(2.0, &mut expected);
            let mut actual = Vec::new();
            value.sample_at(2.0, &mut actual, &mut Vec::new());
            assert_eq!(actual, expected);
        }
        let mut file = fixture();
        file.emitters[0].loop_end = 1;
        let runtime = VfxRuntime::new(&file);
        let mut value = playback(&file);
        value.advance(100_000.0).unwrap();
        assert!(value.fallback_reason().unwrap().contains("operation limit"));
        let mut expected = Vec::new();
        runtime.sample(100_000.0, &mut expected);
        assert_eq!(quads(&value), expected);
    }

