    #[test]
    fn model_skin_requires_explicit_target_and_retains_live_instance_identity() {
        let mut file = fixture();
        file.emitters[0].create_interval = curve(&[(0, 100.0)]);
        file.particles[0].particle_type = Some(ParticleType::ModelSkin);
        file.particles[0].data = AvfxParticleData::ModelSkin(Default::default());
        file.particles[0].life = AvfxLife {
            enabled: true,
            value: 3.0,
            ..Default::default()
        };

        assert!(
            VfxPlayback::new_with_model_skin(VfxRuntime::new(&file), &[99])
                .fallback_reason()
                .is_some()
        );
        let mut missing_data = file.clone();
        missing_data.particles[0].data = AvfxParticleData::None;
        assert!(
            VfxPlayback::new_with_model_skin(VfxRuntime::new(&missing_data), &[0])
                .fallback_reason()
                .is_some()
        );
        let mut value = VfxPlayback::new_with_model_skin(VfxRuntime::new(&file), &[0]);
        assert!(value.fallback_reason().is_none());
        let initial = value.model_skin_instances();
        assert_eq!(initial.len(), 1);
        assert_eq!(initial[0].particle_index, 0);
        assert_eq!(initial[0].age, 0.0);
        assert_eq!(initial, value.model_skin_instances());
        let mut quads = Vec::new();
        let mut meshes = Vec::new();
        value.sample(&mut quads, &mut meshes);
        assert!(quads.is_empty() && meshes.is_empty());

        step(&mut value, 2.0);
        let active = value.model_skin_instances();
        assert_eq!(active.len(), 1);
        assert_eq!(active[0].instance_id, initial[0].instance_id);
        assert_eq!(active[0].total_age, 2.0);
        step(&mut value, 2.0);
        assert!(value.model_skin_instances().is_empty());
        value.update_to(0.0);
        assert_eq!(value.model_skin_instances().len(), 1);
    }

    #[test]
    fn model_skin_history_preserves_first_binding_after_late_sample() {
        let mut file = fixture();
        file.emitters[0].create_interval = curve(&[(0, 100.0)]);
        file.particles[0].particle_type = Some(ParticleType::ModelSkin);
        file.particles[0].data = AvfxParticleData::ModelSkin(Default::default());
        file.particles[0].life = AvfxLife {
            enabled: true,
            value: 3.0,
            ..Default::default()
        };

        let mut value = VfxPlayback::new_with_model_skin(VfxRuntime::new(&file), &[0]);
        let first = value.observed_model_skin_instances()[0];
        step(&mut value, 2.0);
        let last = value.observed_model_skin_instances()[0];
        assert_eq!(last.instance_id, first.instance_id);
        assert_eq!(last.total_age, 2.0);
        step(&mut value, 2.0);
        assert!(value.model_skin_instances().is_empty());
        assert_eq!(value.observed_model_skin_instances(), vec![last]);

        step(&mut value, 100.0);
        assert!(
            value
                .model_skin_instances()
                .iter()
                .any(|instance| instance.instance_id > first.instance_id)
        );
        assert_eq!(value.observed_model_skin_instances(), vec![last]);

        let mut late = VfxPlayback::new_with_model_skin(VfxRuntime::new(&file), &[0]);
        assert!(late.update_to(4.0 / 30.0));
        assert!(late.model_skin_instances().is_empty());
        assert_eq!(
            late.observed_model_skin_instances()[0].instance_id,
            first.instance_id
        );
        late.update_to(0.0);
        assert_eq!(late.observed_model_skin_instances()[0].total_age, 0.0);
    }

