    #[test]
    fn model_skin_instance_color_matches_staged_particle_color() {
        let mut file = fixture();
        file.emitters[0].create_interval = curve(&[(0, 100.0)]);
        file.emitters[0].color.alpha = Some(curve(&[(0, 0.8), (10, 0.4)]));
        file.emitters[0].particle_items[0].parent_influence_color = 2;
        let mut aura_item = file.emitters[0].particle_items[0];
        aura_item.target_index = 1;
        file.emitters[0].particle_items.push(aura_item);
        file.particles[0].color.rgb = Some(AvfxCurve {
            keys: vec![AvfxCurveKey {
                time: 0,
                interpolation: 1,
                x: 0.3,
                y: 0.5,
                z: 0.7,
            }],
            ..Default::default()
        });
        file.particles[0].color.alpha = Some(curve(&[(0, 0.9), (10, 0.3)]));
        file.global.revised_color = [0.5, 1.25, 0.75];
        let mut aura = file.particles[0].clone();
        aura.particle_type = Some(ParticleType::ModelSkin);
        let begin = AvfxColorCurve {
            rgb: Some(AvfxCurve {
                keys: vec![AvfxCurveKey {
                    time: 0,
                    interpolation: 1,
                    x: 0.2,
                    y: 0.4,
                    z: 0.6,
                }],
                ..Default::default()
            }),
            alpha: Some(curve(&[(0, 0.25), (10, 0.5)])),
            ..Default::default()
        };
        let end = AvfxColorCurve {
            rgb: Some(AvfxCurve {
                keys: vec![AvfxCurveKey {
                    time: 0,
                    interpolation: 1,
                    x: 0.8,
                    y: 0.6,
                    z: 0.4,
                }],
                ..Default::default()
            }),
            alpha: Some(curve(&[(0, 0.75), (10, 0.5)])),
            ..Default::default()
        };
        aura.data = AvfxParticleData::ModelSkin(AvfxParticleDataModelSkin {
            fresnel_type: 1,
            color_begin: begin.clone(),
            color_end: end.clone(),
            ..Default::default()
        });
        file.particles.push(aura);

        let mut value = VfxPlayback::new_with_model_skin(VfxRuntime::new(&file), &[1]);
        assert_eq!(value.fallback_reason(), None);
        for frames in [0.0, 2.0, 4.0] {
            step(&mut value, frames);
            let instance = value.model_skin_instances()[0];
            let color = instance.color;
            let quad_color = quads(&value)[0].color;
            for (actual, expected) in color.into_iter().zip(quad_color) {
                near(actual, expected);
            }
            for axis in 0..3 {
                near(
                    instance.aura_color_begin[axis],
                    color[axis] * [0.2, 0.4, 0.6][axis],
                );
                near(
                    instance.aura_color_end[axis],
                    color[axis] * [0.8, 0.6, 0.4][axis],
                );
            }
            let ages = CurveAges {
                local: instance.curve_age,
                total: instance.curve_total_age,
            };
            near(
                instance.aura_color_begin[3],
                begin
                    .alpha
                    .as_ref()
                    .unwrap()
                    .value_at(ages.local, ages.total, 1.0),
            );
            near(
                instance.aura_color_end[3],
                end.alpha
                    .as_ref()
                    .unwrap()
                    .value_at(ages.local, ages.total, 1.0),
            );
            assert_eq!(value.model_skin_instances()[0], instance);
        }
    }

    #[test]
    fn model_skin_data_color_add_uses_total_age_after_loop_writeback() {
        let mut file = fixture();
        file.emitters[0].particle_items[0].create_time = 1;
        let particle = &mut file.particles[0];
        particle.particle_type = Some(ParticleType::ModelSkin);
        particle.loop_start = 1;
        particle.loop_end = 5;
        let mut alpha = curve(&[(0, 0.0), (4, 1.0)]);
        alpha.post_behavior = crate::avfx::BEHAVIOR_ADD;
        particle.data = AvfxParticleData::ModelSkin(AvfxParticleDataModelSkin {
            fresnel_type: 1,
            color_begin: AvfxColorCurve {
                alpha: Some(alpha.clone()),
                ..Default::default()
            },
            sem: alpha.clone(),
            uv_point_density: AvfxCurve3Axis {
                x: Some(alpha.clone()),
                ..Default::default()
            },
            ..Default::default()
        });

        let mut value = VfxPlayback::new_with_model_skin(VfxRuntime::new(&file), &[0]);
        assert_eq!(value.fallback_reason(), None);
        step(&mut value, 10.0);
        step(&mut value, 0.0);
        let instance = value.model_skin_instances()[0];
        assert!(instance.curve_total_age > instance.curve_age);
        let expected = alpha.value_at(instance.curve_age, instance.curve_total_age, 1.0);
        let local_only = alpha.value_at(instance.curve_age, instance.curve_age, 1.0);
        assert_ne!(expected, local_only);
        near(instance.aura_color_begin[3], expected);
        near(instance.aura_sem, expected);
        near(instance.aura_uv_point_density[0], expected);
        assert_eq!(instance.aura_uv_point_density[3], 1.0);
    }

    #[test]
